from html import escape


def escape_field(value):
    return escape(str(value), quote=True)


def build_headings(name, title):
    heading = "  <h1>{}</h1>".format(escape_field(name))
    subheading = "  <h2>{}</h2>".format(escape_field(title))
    return "{}\n{}".format(heading, subheading)


def build_contact(email, phone, website, location):
    link = '<a href="mailto:{}">{}</a>'.format(escape_field(email), escape_field(email))
    site = '<a href="{}">{}</a>'.format(escape_field(website), escape_field(website))
    parts = [link, escape_field(phone), site, escape_field(location)]
    joined = " | ".join(part for part in parts if part)
    return '  <p class="contact">{}</p>'.format(joined)


def build_skill(skill):
    return "    <li>{}</li>".format(escape_field(skill))


def build_skill_list(skills):
    if not skills:
        return "  <p>No skills listed.</p>"
    items = "\n".join(build_skill(skill) for skill in skills)
    return "  <ul>\n{}\n  </ul>".format(items)


def format_job(job):
    role = "    <h3>{}</h3>".format(escape_field(job['role']))
    company = "    <h4>{}</h4>".format(escape_field(job['company']))
    span = "{} &ndash; {}".format(escape_field(job['start']), escape_field(job['end']))
    dates = "    <p>{}</p>".format(span)
    return '  <section class="job">\n{}\n{}\n{}\n  </section>'.format(role, company, dates)


def build_experience(jobs):
    if not jobs:
        return "  <p>No experience listed.</p>"
    return "\n".join(format_job(job) for job in jobs)


def resume(profile):
    name = profile["name"]
    blocks = [
        "<!DOCTYPE html>",
        '<html lang="en">',
        "<head>",
        '  <meta charset="utf-8">',
        "  <title>{} &ndash; Resume</title>".format(escape_field(name)),
        "</head>",
        "<body>",
        build_headings(name, profile["title"]),
        build_contact(
            profile["email"], profile["phone"], profile["website"], profile["location"]
        ),
        "  <h2>Skills</h2>",
        build_skill_list(profile.get("skills", [])),
        "  <h2>Experience</h2>",
        build_experience(profile.get("jobs", [])),
        "</body>",
        "</html>",
    ]
    return "\n".join(blocks)


def main():
    profile = {
        "name": "Alice",
        "title": "Engineer",
        "email": "alice@example.com",
        "phone": "+1 555 0100",
        "website": "https://alice.example.com",
        "location": "Berlin, DE",
        "skills": ["Python", "SQL", "Distributed Systems"],
        "jobs": [
            {
                "role": "Senior Engineer",
                "company": "Example Corp",
                "start": "2021-03",
                "end": "Present",
            },
            {
                "role": "Engineer",
                "company": "Startup GmbH",
                "start": "2018-01",
                "end": "2021-02",
            },
        ],
    }
    page = resume(profile)
    print(page)
    print("\n<!-- generated {} characters for {} -->".format(len(page), profile['name']))


if __name__ == "__main__":
    main()

