def drop_table(table_name):
    return f"DROP TABLE IF EXISTS {table_name};"


def create_header(table_name):
    return f"CREATE TABLE {table_name} ("


def column_definition(column_name, data_type):
    return f"    {column_name} {data_type}"


def comment_line(table_name):
    return f"-- Migration for table {table_name}"


def insert_statement(table_name, column_names, values):
    columns = ", ".join(column_names)
    data = ", ".join(values)
    return f"INSERT INTO {table_name} ({columns}) VALUES ({data});"


def format_value(value, data_type):
    if value is None:
        return "NULL"
    lowered = data_type.lower()
    if lowered.startswith("int") or lowered.startswith("float") or lowered.startswith("numeric"):
        return f"{value}"
    escaped = str(value).replace("'", "''")
    return f"'{escaped}'"


def validate_table(table):
    name = table.get("name")
    if not name:
        raise ValueError("every table definition needs a non-empty 'name'")
    columns = table.get("columns", [])
    types = table.get("types", [])
    if len(columns) != len(types):
        raise ValueError(f"table {name} has {len(columns)} columns but {len(types)} types")
    for row in table.get("rows", []):
        if len(row) != len(columns):
            raise ValueError(f"row {row!r} of table {name} does not match {len(columns)} columns")
    return name, columns, types, table.get("rows", [])


def create_table(table_name, columns, types):
    lines = [create_header(table_name)]
    definitions = [column_definition(c, t) for c, t in zip(columns, types)]
    lines.append(",\n".join(definitions))
    lines.append(");")
    return lines


def migrate(schema):
    statements = []
    for table in schema:
        name, columns, types, rows = validate_table(table)
        statements.append(comment_line(name))
        statements.append(drop_table(name))
        statements.extend(create_table(name, columns, types))
        for row in rows:
            values = [format_value(v, t) for v, t in zip(row, types)]
            statements.append(insert_statement(name, columns, values))
        statements.append("")
    return "\n".join(statements).rstrip("\n")


def main():
    schema = [
        {
            "name": "users",
            "columns": ["id", "email"],
            "types": ["INTEGER", "VARCHAR(255)"],
            "rows": [[1, "ada@example.com"], [2, "o'brien@example.com"]],
        },
        {
            "name": "orders",
            "columns": ["id", "user_id", "total"],
            "types": ["INTEGER", "INTEGER", "NUMERIC(10,2)"],
            "rows": [[10, 1, 49.99], [11, 2, None]],
        },
    ]
    sql = migrate(schema)
    print(sql)
    print(f"\n-- generated {len(sql.splitlines())} lines for {len(schema)} tables")


if __name__ == "__main__":
    main()

