def build_from(base_image, version):
    return f"FROM {base_image}:{version}"


def build_label(maintainer):
    return f'LABEL maintainer="{maintainer}"'


def build_expose(port):
    return f"EXPOSE {port}"


def build_workdir(path):
    return f"WORKDIR {path}"


def build_install(packages):
    package_list = " ".join(packages)
    return f"RUN apt-get update && apt-get install -y {package_list}"


def build_env_port(port):
    return f"ENV APP_PORT={port}"


def build_cmd(command):
    parts = ", ".join(f'"{token}"' for token in command.split())
    return f"CMD [{parts}]"


def validate(config):
    required = ("base_image", "version", "maintainer", "port", "workdir",
                "packages", "run_command")
    for key in required:
        if key not in config:
            raise KeyError(f"missing configuration key: {key}")
    port = config["port"]
    if not isinstance(port, int) or isinstance(port, bool):
        raise TypeError(f"port must be an integer, got {type(port).__name__}")
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range: {port}")
    if not config["packages"]:
        raise ValueError("packages must contain at least one entry")
    return port


def dockerize(config):
    port = validate(config)
    lines = [
        build_from(config["base_image"], config["version"]),
        build_label(config["maintainer"]),
        build_expose(port),
        build_install(config["packages"]),
        build_workdir(config["workdir"]),
        build_env_port(port),
        build_cmd(config["run_command"]),
    ]
    return "\n".join(lines)


def main():
    config = {
        "base_image": "ubuntu",
        "version": "latest",
        "maintainer": "Ada Lovelace",
        "port": 80,
        "workdir": "/srv/app",
        "packages": ["python3", "python3-pip", "curl"],
        "run_command": "python3 -m app.server",
    }
    dockerfile = dockerize(config)
    print(dockerfile)
    directives = dockerfile.splitlines()
    print(f"\n# {len(directives)} directives generated for {config['base_image']}")
    print(f"# service will listen on port {config['port']}")


if __name__ == "__main__":
    main()

