def listen_directive(port):
    if not isinstance(port, int) or isinstance(port, bool):
        raise TypeError(f"listen port must be an int, got {type(port).__name__}")
    if not 1 <= port <= 65535:
        raise ValueError(f"listen port out of range: {port}")
    return f"listen {port};"


def server_name_directive(domain):
    if not domain or " " in domain:
        raise ValueError(f"invalid domain name: {domain!r}")
    return f"server_name {domain};"


def root_directive(document_root):
    return f"root {document_root};"


def access_log_directive(path):
    return f"access_log {path};"


def error_log_directive(path):
    return f"error_log {path};"


def ssl_certificate_directive(path):
    return f"ssl_certificate {path};"


def ssl_certificate_key_directive(path):
    return f"ssl_certificate_key {path};"


def proxy_pass_directive(url):
    if not url.startswith(("http://", "https://")):
        raise ValueError(f"proxy url must be http(s): {url}")
    return f"proxy_pass {url};"


REQUIRED_KEYS = (
    "domain", "port", "document_root", "access_log",
    "error_log", "proxy_url", "ssl_certificate", "ssl_certificate_key",
)


def nginx(config):
    missing = [key for key in REQUIRED_KEYS if key not in config]
    if missing:
        raise KeyError(f"missing settings: {', '.join(missing)}")
    body = [
        listen_directive(config["port"]),
        server_name_directive(config["domain"]),
        root_directive(config["document_root"]),
        access_log_directive(config["access_log"]),
        error_log_directive(config["error_log"]),
        ssl_certificate_directive(config["ssl_certificate"]),
        ssl_certificate_key_directive(config["ssl_certificate_key"]),
        proxy_pass_directive(config["proxy_url"]),
    ]
    lines = ["server {"]
    for directive in body:
        lines.append(f"    {directive}")
    lines.append("}")
    return "\n".join(lines)


def main():
    settings = {
        "domain": "example.com",
        "port": 80,
        "document_root": "/var/www/example.com/html",
        "access_log": "/var/log/nginx/example.com.access.log",
        "error_log": "/var/log/nginx/example.com.error.log",
        "proxy_url": "http://127.0.0.1:8080",
        "ssl_certificate": "/etc/ssl/certs/example.com.pem",
        "ssl_certificate_key": "/etc/ssl/private/example.com.key",
    }
    block = nginx(settings)
    print(f"# configuration for {settings['domain']}")
    print(block)
    print(f"# {len(block.splitlines())} lines generated")


if __name__ == "__main__":
    main()

