def start_tag():
    return "@startuml"


def title_line(title):
    return f"title {title}"


def theme_line(theme):
    return f"!theme {theme}"


def solid_arrow(sender, receiver, text):
    return f"{sender} -> {receiver}: {text}"


def dotted_arrow(sender, receiver, text):
    return f"{sender} --> {receiver}: {text}"


def async_arrow(sender, receiver, text):
    return f"{sender} ->> {receiver}: {text}"


def note_line(receiver, text):
    return f"note right of {receiver}: {text}"


def end_tag():
    return "@enduml"


DISPATCH = {
    "solid": solid_arrow,
    "dotted": dotted_arrow,
    "async": async_arrow,
}


def render_interaction(interaction):
    kind = interaction.get("type", "solid")
    sender = interaction["sender"]
    receiver = interaction["receiver"]
    text = interaction["message"]
    if kind == "note":
        return note_line(receiver, text)
    builder = DISPATCH.get(kind)
    if builder is None:
        raise ValueError(f"unsupported interaction type: {kind!r}")
    return builder(sender, receiver, text)


def sequence(interactions):
    lines = [start_tag()]
    title = interactions.get("title")
    if title:
        lines.append(title_line(title))
    theme = interactions.get("theme")
    if theme:
        lines.append(theme_line(theme))
    for interaction in interactions.get("interactions", []):
        lines.append(render_interaction(interaction))
    lines.append(end_tag())
    return "\n".join(lines)


def summarize(interactions):
    steps = interactions.get("interactions", [])
    participants = set()
    for step in steps:
        participants.add(step["sender"])
        participants.add(step["receiver"])
    names = ", ".join(sorted(participants))
    return f"{len(steps)} interactions among {len(participants)} participants: {names}"


