def xml_declaration(encoding="UTF-8"):
    return f'<?xml version="1.0" encoding="{encoding}"?>'


def urlset_open():
    namespaces = {
        "xmlns": "http://www.sitemaps.org/schemas/sitemap/0.9",
        "xmlns:xhtml": "http://www.w3.org/1999/xhtml",
    }
    attributes = " ".join(f'{name}="{uri}"' for name, uri in namespaces.items())
    return f"<urlset {attributes}>"


def normalize_host(host):
    stripped = host.strip().rstrip("/")
    if stripped.startswith("http://") or stripped.startswith("https://"):
        return stripped
    return f"https://{stripped}"


def location_tag(host, path):
    clean_path = path.strip().lstrip("/")
    return f"    <loc>{host}/{clean_path}</loc>"


def lastmod_tag(lastmod):
    return f"    <lastmod>{lastmod}</lastmod>"


def changefreq_tag(changefreq):
    allowed = ("always", "hourly", "daily", "weekly", "monthly", "yearly", "never")
    value = changefreq.strip().lower()
    if value not in allowed:
        raise ValueError(f"unsupported change frequency: {changefreq!r}")
    return f"    <changefreq>{value}</changefreq>"


def priority_tag(priority):
    value = float(priority)
    if not 0.0 <= value <= 1.0:
        raise ValueError(f"priority must be between 0.0 and 1.0, got {value}")
    return f"    <priority>{value:.1f}</priority>"


def alternate_link_tag(host, lang, alt_path):
    clean_path = alt_path.strip().lstrip("/")
    href = f"{host}/{clean_path}"
    return f'    <xhtml:link rel="alternate" hreflang="{lang}" href="{href}"/>'


def url_close():
    return "  </url>"


def sitemap(pages):
    host = normalize_host(pages["host"])
    lines = [xml_declaration(), urlset_open()]
    for index, page in enumerate(pages["pages"]):
        if "path" not in page:
            raise KeyError(f"page #{index} is missing a relative path")
        lines.append("  <url>")
        lines.append(location_tag(host, page["path"]))
        lines.append(lastmod_tag(page["lastmod"]))
        lines.append(changefreq_tag(page["changefreq"]))
        lines.append(priority_tag(page["priority"]))
        lines.append(alternate_link_tag(host, page["alt_lang"], page["alt_path"]))
        lines.append(url_close())
    lines.append("</urlset>")
    return "\n".join(lines)


def main():
    website = {
        "host": "example.com",
        "pages": [
            {
                "path": "about",
                "lastmod": "2026-09-18",
                "changefreq": "monthly",
                "priority": 0.8,
                "alt_lang": "fr",
                "alt_path": "fr/a-propos",
            },
            {
                "path": "contact",
                "lastmod": "2026-08-01",
                "changefreq": "yearly",
                "priority": 0.5,
                "alt_lang": "de",
                "alt_path": "de/kontakt",
            },
        ],
    }
    document = sitemap(website)
    print(document)
    print(f"Generated sitemap for {len(website['pages'])} pages "
          f"({len(document)} characters).")


if __name__ == "__main__":
    main()

