    if stripped.startswith("http://") or stripped.startswith("https://"):
        return stripped
    return "https://{}".format(stripped)


def location_tag(host, path):
    clean_path = path.strip().lstrip("/")
    return "    <loc>{}/{}</loc>".format(host, clean_path)


def lastmod_tag(lastmod):
    return "    <lastmod>{}</lastmod>".format(lastmod)


def changefreq_tag(changefreq):
    allowed = ("always", "hourly", "daily", "weekly", "monthly", "yearly", "never")
    value = changefreq.strip().lower()
    if value not in allowed:
        raise ValueError("unsupported change frequency: {!r}".format(changefreq))
    return "    <changefreq>{}</changefreq>".format(value)


def priority_tag(priority):
    value = float(priority)
    if not 0.0 <= value <= 1.0:
        raise ValueError("priority must be between 0.0 and 1.0, got {}".format(value))
    return "    <priority>{:.1f}</priority>".format(value)


def alternate_link_tag(host, lang, alt_path):
    clean_path = alt_path.strip().lstrip("/")
    href = "{}/{}".format(host, clean_path)
    return '    <xhtml:link rel="alternate" hreflang="{}" href="{}"/>'.format(lang, href)


def url_close():
    return "  </url>"


def sitemap(pages):
    host = normalize_host(pages["host"])
    lines = [xml_declaration(), urlset_open()]
    for index, page in enumerate(pages["pages"]):
        if "path" not in page:
            raise KeyError("page #{} is missing a relative path".format(index))
        lines.append("  <url>")
        lines.append(location_tag(host, page["path"]))
        lines.append(lastmod_tag(page["lastmod"]))
        lines.append(changefreq_tag(page["changefreq"]))
        lines.append(priority_tag(page["priority"]))
        lines.append(alternate_link_tag(host, page["alt_lang"], page["alt_path"]))
        lines.append(url_close())
    lines.append("</urlset>")
    return "\n".join(lines)


def main():
    website = {
        "host": "example.com",
        "pages": [
            {
                "path": "about",
                "lastmod": "2026-09-18",
                "changefreq": "monthly",
                "priority": 0.8,
                "alt_lang": "fr",
                "alt_path": "fr/a-propos",
            },
            {
                "path": "contact",
                "lastmod": "2026-08-01",
                "changefreq": "yearly",
                "priority": 0.5,
                "alt_lang": "de",
                "alt_path": "de/kontakt",
            },
        ],
    }
    document = sitemap(website)
    print(document)
    print("Generated sitemap for {} pages ".format(len(website['pages'])) +
          "({} characters).".format(len(document)))


if __name__ == "__main__":
    main()

