from datetime import datetime

DATE_FORMATS = ("%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d")


def parse_moment(value, field):
    """Turn a string or datetime into a datetime object."""
    if isinstance(value, datetime):
        return value
    for pattern in DATE_FORMATS:
        try:
            return datetime.strptime(value, pattern)
        except ValueError:
            continue
    raise ValueError(f"cannot read {field} from {value!r}")


def stamp(moment):
    """Render a datetime in the compact iCalendar form."""
    return moment.strftime("%Y%m%dT%H%M%S")


def check_event(event):
    """Validate one event tuple and return its normalised fields."""
    if len(event) != 8:
        raise ValueError(f"event needs 8 fields, got {len(event)}")
    uid, start, end, title, location, organizer, status, sequence = event
    begins = parse_moment(start, "start date")
    finishes = parse_moment(end, "end date")
    if finishes < begins:
        raise ValueError(f"event {uid} ends ({finishes}) before it starts ({begins})")
    if "@" not in organizer:
        raise ValueError(f"organizer {organizer!r} is not an email address")
    return uid, begins, finishes, title, location, organizer, status, int(sequence)


def calendar(events):
    """Build the text lines of a calendar containing the given events."""
    lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//text-schedule//EN"]
    for event in events:
        uid, begins, finishes, title, location, organizer, status, sequence = check_event(event)
        lines.append("BEGIN:VEVENT")
        lines.append(f"UID:{uid}")
        lines.append(f"DTSTART:{stamp(begins)}")
        lines.append(f"DTEND:{stamp(finishes)}")
        lines.append(f"SUMMARY:{title}")
        lines.append(f"LOCATION:{location}")
        lines.append(f"ORGANIZER;CN={organizer}:mailto:{organizer}")
        lines.append(f"STATUS:{status.upper()}")
        lines.append(f"SEQUENCE:{sequence}")
        lines.append("END:VEVENT")
    lines.append("END:VCALENDAR")
    return lines


def summarise(events):
    """Produce a short human readable digest of the same events."""
    report = []
    for event in events:
        uid, begins, finishes, title, location, _, status, sequence = check_event(event)
        span = (finishes - begins).total_seconds() / 3600
        when = begins.strftime("%d %b %Y %H:%M")
        report.append(f"{uid}: {title} at {location} on {when} ({span:.1f}h, {status}, rev {sequence})")
    return report


def main():
    events = [
        ("evt-001", "2024-05-03 09:30", "2024-05-03 11:00", "Design review",
         "Room 4B", "ana@example.com", "confirmed", 0),
        ("evt-002", "2024-05-07 14:00", "2024-05-07 15:30", "Sprint planning",
         "Online", "ben@example.com", "tentative", 2),
    ]
    for line in calendar(events):
        print(line)
    print()
    for line in summarise(events):
        print(line)
    print(f"{len(events)} events rendered")


if __name__ == "__main__":
    main()

