def column_spec(cols):
    if cols < 1:
        raise ValueError(f"column count must be at least 1, got {cols}")
    return "l" + "r" * (cols - 1)


def money(value):
    return f"\\${value:,.2f}"


def table_lines(name, cols, qty, price, total, caption, label, stamp):
    spec = column_spec(cols)
    lines = [f"\\begin{{tabular}}{{{spec}}}"]
    lines.append("\\hline")
    lines.append(f"Item & {name} \\\\")
    lines.append(f"Quantity & {qty} \\\\")
    lines.append(f"Unit price & {money(price)} \\\\")
    lines.append(f"Total & {money(total)} \\\\")
    lines.append("\\hline")
    lines.append("\\end{tabular}")
    lines.append(f"\\caption{{{caption}}}")
    lines.append(f"\\label{{tab:{label}}}")
    lines.append(f"% generated on {stamp}")
    return lines


def validate(row):
    if len(row) != 8:
        raise ValueError(f"each table entry needs 8 fields, got {len(row)}")
    name, cols, qty, price, total, caption, label, stamp = row
    if qty < 0:
        raise ValueError(f"negative quantity {qty} for item {name}")
    expected = qty * price
    if abs(expected - total) > 0.005:
        raise ValueError(f"total {total} does not match {qty} x {price} for {name}")
    return name, cols, qty, price, total, caption, label, stamp


