    document = []
    for row in rows:
        name, cols, qty, price, total, caption, label, stamp = validate(row)
        document.append("\\begin{table}[ht]")
        document.append("\\centering")
        document.extend(table_lines(name, cols, qty, price, total, caption, label, stamp))
        document.append("\\end{table}")
    return document


def summarize(rows):
    grand = sum(row[4] for row in rows)
    report = [f"{len(rows)} table(s) rendered"]
    for row in rows:
        report.append(f"  {row[0]}: {row[2]} @ {money(row[3])} = {money(row[4])}")
    report.append(f"  grand total: {money(grand)}")
    return report


