import re

SEVERITIES = ("critical", "warning", "info")
DURATION_PATTERN = re.compile(r"^\d+(ms|s|m|h)$")


def normalize_duration(duration):
    """Turn an int (seconds) or a duration string into a canonical '<n><unit>' form."""
    if isinstance(duration, int):
        return f"{duration}s"
    text = str(duration).strip()
    if not DURATION_PATTERN.match(text):
        raise ValueError(f"invalid evaluation duration {duration!r}")
    return text


def validate_rule(index, rule):
    """Check one raw rule tuple and return its eight fields with the duration normalized."""
    if len(rule) != 8:
        raise ValueError(f"rule #{index} needs 8 fields but has {len(rule)}")
    name, expr, duration, severity, team, description, runbook, environment = rule
    if not name.strip():
        raise ValueError(f"rule #{index} has an empty alert name")
    if not expr.strip():
        raise ValueError(f"rule {name!r} has an empty threshold expression")
    if severity not in SEVERITIES:
        raise ValueError(f"rule {name!r} has unsupported severity {severity!r}")
    if not team.strip():
        raise ValueError(f"rule {name!r} must name an owning team")
    return (name.strip(), expr.strip(), normalize_duration(duration),
            severity, team.strip(), description.strip(), runbook.strip(), environment.strip())


def format_rule(rule, index=0):
    """Render a single validated rule tuple as the lines of a rules file entry."""
    name, expr, duration, severity, team, description, runbook, environment = validate_rule(index, rule)
    lines = [f"  - alert: {name}"]
    lines.append(f"    expr: {expr}")
    lines.append(f"    for: {duration}")
    lines.append("    labels:")
    lines.append(f"      severity: {severity}")
    lines.append(f"      team: {team}")
    lines.append("    annotations:")
    lines.append(f"      description: {description}")
    lines.append(f"      runbook_url: {runbook}")
    lines.append(f"      environment: {environment}")
    return lines


def alert(rules):
    """Build the full text based monitoring configuration for a list of rule tuples."""
    lines = ["groups:", f"  # {len(rules)} alerting rule(s)", "  rules:"]
    for index, rule in enumerate(rules, start=1):
        lines.extend(format_rule(rule, index))
    return lines


def ownership_report(rules):
    """Summarize how many rules each team owns, sorted by team name."""
    counts = {}
    for index, rule in enumerate(rules, start=1):
        team = validate_rule(index, rule)[4]
        counts[team] = counts.get(team, 0) + 1
    return [f"{team} owns {count} rule(s)" for team, count in sorted(counts.items())]


def main():
    rules = [
        ("HighCpuUsage", "avg(rate(cpu_seconds[5m])) > 0.9", 300, "critical", "platform",
         "CPU saturated on the API fleet.", "https://runbooks.example.com/cpu", "production"),
        ("DiskFillingUp", "predict_linear(disk_free[6h], 3600) < 0", "15m", "warning", "storage",
         "Disk will fill within the hour.", "https://runbooks.example.com/disk", "staging"),
    ]
    for line in alert(rules):
        print(line)
    print()
    for summary in ownership_report(rules):
        print(f"* {summary}")


if __name__ == "__main__":
    main()

