        return "{}s".format(duration)
    text = str(duration).strip()
    if not DURATION_PATTERN.match(text):
        raise ValueError("invalid evaluation duration {!r}".format(duration))
    return text


def validate_rule(index, rule):
    """Check one raw rule tuple and return its eight fields with the duration normalized."""
    if len(rule) != 8:
        raise ValueError("rule #{} needs 8 fields but has {}".format(index, len(rule)))
    name, expr, duration, severity, team, description, runbook, environment = rule
    if not name.strip():
        raise ValueError("rule #{} has an empty alert name".format(index))
    if not expr.strip():
        raise ValueError("rule {!r} has an empty threshold expression".format(name))
    if severity not in SEVERITIES:
        raise ValueError("rule {!r} has unsupported severity {!r}".format(name, severity))
    if not team.strip():
        raise ValueError("rule {!r} must name an owning team".format(name))
    return (name.strip(), expr.strip(), normalize_duration(duration),
            severity, team.strip(), description.strip(), runbook.strip(), environment.strip())


def format_rule(rule, index=0):
    """Render a single validated rule tuple as the lines of a rules file entry."""
    name, expr, duration, severity, team, description, runbook, environment = validate_rule(index, rule)
    lines = ["  - alert: {}".format(name)]
    lines.append("    expr: {}".format(expr))
    lines.append("    for: {}".format(duration))
    lines.append("    labels:")
    lines.append("      severity: {}".format(severity))
    lines.append("      team: {}".format(team))
    lines.append("    annotations:")
    lines.append("      description: {}".format(description))
    lines.append("      runbook_url: {}".format(runbook))
    lines.append("      environment: {}".format(environment))
    return lines


def alert(rules):
    """Build the full text based monitoring configuration for a list of rule tuples."""
    lines = ["groups:", "  # {} alerting rule(s)".format(len(rules)), "  rules:"]
    for index, rule in enumerate(rules, start=1):
        lines.extend(format_rule(rule, index))
    return lines


def ownership_report(rules):
    """Summarize how many rules each team owns, sorted by team name."""
    counts = {}
    for index, rule in enumerate(rules, start=1):
        team = validate_rule(index, rule)[4]
        counts[team] = counts.get(team, 0) + 1
    return ["{} owns {} rule(s)".format(team, count) for team, count in sorted(counts.items())]


def main():
    rules = [
        ("HighCpuUsage", "avg(rate(cpu_seconds[5m])) > 0.9", 300, "critical", "platform",
         "CPU saturated on the API fleet.", "https://runbooks.example.com/cpu", "production"),
        ("DiskFillingUp", "predict_linear(disk_free[6h], 3600) < 0", "15m", "warning", "storage",
         "Disk will fill within the hour.", "https://runbooks.example.com/disk", "staging"),
    ]
    for line in alert(rules):
        print(line)
    print()
    for summary in ownership_report(rules):
        print("* {}".format(summary))


if __name__ == "__main__":
    main()

def generate_tracking_id(index, host):
    prefix = host[:3].upper() if host else "UNK"
    return "{}-TRK-{}".format(prefix, index * 1000 + 42)

def generate_client_address(index):
    subnet = 10 + (index % 100)
    return "192.168.{}.{}".format(subnet, index % 255)

def format_request_line(method, path, protocol):
    return "{} {} {}".format(method.upper(), path, protocol)

def format_host_header(host):
    return "Host: {}".format(host)

def format_user_agent_header(user_agent):
    return "User-Agent: {}".format(user_agent)

def format_accept_header(accept):
    return "Accept: {}".format(accept)

def format_content_type_header(content_type):
    return "Content-Type: {}".format(content_type)

def format_content_length_header(content_length):
    return "Content-Length: {}".format(content_length)

def format_tracking_header(tracking_id):
    return "X-Tracking-Id: {}".format(tracking_id)

def format_client_address_header(client_address):
    return "X-Forwarded-For: {}".format(client_address)

def process_single_request(request, index):
    method, path, protocol, host, user_agent, accept, content_type, content_length = request
    lines = []

    req_line = format_request_line(method, path, protocol)
    lines.append(req_line)

    host_line = format_host_header(host)
    lines.append(host_line)

    ua_line = format_user_agent_header(user_agent)
    lines.append(ua_line)

    accept_line = format_accept_header(accept)
    lines.append(accept_line)

    if content_type:
        ct_line = format_content_type_header(content_type)
        lines.append(ct_line)

    if content_length is not None:
        cl_line = format_content_length_header(content_length)
        lines.append(cl_line)

    tracking_id = generate_tracking_id(index, host)
    tracking_line = format_tracking_header(tracking_id)
    lines.append(tracking_line)

    client_address = generate_client_address(index)
    client_line = format_client_address_header(client_address)
    lines.append(client_line)

    lines.append("")
    return lines

def http(requests):
    output = []
    for i, request in enumerate(requests):
        request_lines = process_single_request(request, i)
        output.extend(request_lines)
    return output

