BACKGROUND_OPACITY = 0.75
FIELD_COUNT = 8


def parse_time(value):
    """Turn 'HH:MM:SS.mmm', 'MM:SS.mmm' or a number of seconds into seconds."""
    if isinstance(value, (int, float)):
        return float(value)
    parts = str(value).strip().split(":")
    if len(parts) > 3:
        raise ValueError("too many time components in {!r}".format(value))
    seconds = 0.0
    for part in parts:
        try:
            seconds = seconds * 60.0 + float(part)
        except ValueError:
            raise ValueError("cannot read time component {!r} of {!r}".format(part, value))
    return seconds


def format_time(seconds):
    """Render seconds as a WebVTT timestamp."""
    hours, rest = divmod(seconds, 3600.0)
    minutes, secs = divmod(rest, 60.0)
    whole = int(secs)
    millis = int(round((secs - whole) * 1000))
    return "{:02d}:{:02d}:{:02d}.{:03d}".format(int(hours), int(minutes), whole, millis)


def cue_timing(start, end):
    """Build the 'start --> end' arrow line for one cue."""
    begin = parse_time(start)
    finish = parse_time(end)
    if finish <= begin:
        raise ValueError("end time {!r} does not follow start time {!r}".format(end, start))
    return "{} --> {}".format(format_time(begin), format_time(finish))


def check_caption(caption):
    if len(caption) != FIELD_COUNT:
        raise ValueError("caption needs {} fields, got {}".format(FIELD_COUNT, len(caption)))
    if not str(caption[5]).strip():
        raise ValueError("caption {} carries no text payload".format(caption[0]))


def subtitles(captions):
    """Return the caption file as a list of lines."""
    lines = ["WEBVTT", ""]
    for caption in captions:
        check_caption(caption)
        seq, start, end, region, speaker, text, color, align = caption
        cue_id = "cue-{}".format(seq)
        lines.append("{}".format(seq))
        lines.append(cue_timing(start, end))
        lines.append("Region: {}".format(region))
        lines.append("<v {}>".format(speaker))
        lines.append("{}".format(str(text).strip()))
        lines.append("::cue(#{}) {{ color: {}; }}".format(cue_id, color))
        lines.append("::cue(#{}) {{ background: rgba(0, 0, 0, {}); }}".format(cue_id, BACKGROUND_OPACITY))
        lines.append("::cue(#{}) {{ text-align: {}; }}".format(cue_id, align))
        lines.append("")
    return lines


def main():
    captions = [
        (1, "00:00.000", "00:02.500", "top", "Narrator",
         "A quiet street at dawn.", "#ffffff", "center"),
        (2, "00:02.500", "00:06.250", "bottom", "Mira",
