def _validate_peer(index, peer):
    if len(peer) != 8:
        raise ValueError("peer {} must have 8 fields, got {}".format(index, len(peer)))
    address, listen_port, private_key, public_key, allowed, host, remote_port, keepalive = peer
    for name, port in (("listen port", listen_port), ("endpoint port", remote_port)):
        if not 1 <= int(port) <= 65535:
            raise ValueError("peer {} has an out of range {}: {}".format(index, name, port))
    if int(keepalive) < 0:
        raise ValueError("peer {} has a negative keepalive: {}".format(index, keepalive))
    if "/" not in str(allowed):
        raise ValueError("peer {} allowed range {} is missing a prefix length".format(index, allowed))
    if not str(private_key) or not str(public_key):
        raise ValueError("peer {} is missing key material".format(index))
    return (str(address), int(listen_port), str(private_key), str(public_key),
            str(allowed), str(host), int(remote_port), int(keepalive))


def wireguard(peers):
    lines = []
    for index, raw in enumerate(peers):
        peer = _validate_peer(index, raw)
        address, listen_port, private_key, public_key, allowed, host, remote_port, keepalive = peer
        lines.append("[Interface]")
        lines.append("Address = {}".format(address))
        lines.append("ListenPort = {}".format(listen_port))
        lines.append("PrivateKey = {}".format(private_key))
        lines.append("Table = {}".format(100 + index))
        lines.append("")
        lines.append("[Peer]")
        lines.append("PublicKey = {}".format(public_key))
        lines.append("AllowedIPs = {}".format(allowed))
        lines.append("Endpoint = {}:{}".format(host, remote_port))
        lines.append("PersistentKeepalive = {}".format(keepalive))
        lines.append("")
    return lines


def render(peers):
    return "\n".join(wireguard(peers))


def write_config(peers, path):
    text = render(peers)
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(text)
        handle.write("\n")
    return "wrote {} lines to {}".format(len(text.splitlines()), path)


def summarize(peers):
    report = []
    for index, raw in enumerate(peers):
        address, _, _, _, allowed, host, remote_port, keepalive = _validate_peer(index, raw)
        report.append("tunnel {}: {} -> {}:{}".format(index, address, host, remote_port))
        report.append("  routes {}, ping every {}s".format(allowed, keepalive))
    return report


def main():
