def suite_header(name):
    return "*** Settings ***    # Suite: {}".format(name)


def library_line(library):
    return "Library    {}".format(library)


def variable_line(var_name, value):
    declaration = "${{{}}}".format(var_name)
    return "{}    {}".format(declaration, value)


def timeout_line(index, seconds):
    return "Test Timeout    {} seconds    # step group {}".format(seconds, index)


def documentation_line(text):
    return "    [Documentation]    {}".format(text)


def action_line(step):
    return "    {}".format(step)


def verification_line(step):
    return "    Should Be True    {}".format(step)


def estimate_timeout(action, verification):
    weight = len(action.split()) + len(verification.split())
    return 10 + 5 * weight


def validate(index, test):
    if len(test) != 8:
        raise ValueError("test #{} must have 8 fields, got {}".format(index, len(test)))
    for position, field in enumerate(test):
        if not isinstance(field, str) or not field.strip():
            raise ValueError("test #{} field {} must be a non-empty string".format(index, position))


def robot(tests):
    lines = []
    for index, test in enumerate(tests, start=1):
        validate(index, test)
        suite, library, var_name, var_value, case_id, action, check, doc = test
        lines.append(suite_header(suite))
        lines.append(library_line(library))
        lines.append("")
        lines.append("*** Variables ***")
        lines.append(variable_line(var_name, var_value))
        lines.append("")
        lines.append("*** Test Cases ***")
        lines.append("{}".format(case_id))
        lines.append(documentation_line(doc))
        lines.append(action_line(action))
        lines.append(verification_line(check))
        lines.append(timeout_line(index, estimate_timeout(action, check)))
        lines.append("")
    return lines


def main():
    tests = [
        (
            "Login Checks",
            "SeleniumLibrary",
            "BASE_URL",
            "https://example.test/login",
            "Valid User Can Log In",
            "Open Browser    ${BASE_URL}    chrome",
            "${TITLE} == 'Dashboard'",
            "Verifies that a registered user reaches the dashboard.",
        ),
        (
            "API Checks",
            "RequestsLibrary",
            "API_ROOT",
            "https://example.test/api",
            "Health Endpoint Responds",
            "GET    ${API_ROOT}/health",
            "${RESPONSE.status_code} == 200",
            "Verifies that the health endpoint answers with HTTP 200.",
        ),
    ]
    script = robot(tests)
    for line in script:
        print(line)
    print("Generated {} lines for {} suites.".format(len(script), len(tests)))


if __name__ == "__main__":
    main()

