    "nastype": str,
    "max_connections": int,
    "idle_timeout": int,
    "virtual_server": str,
}

INDENT = "\t"


def validate_client(client, position):
    for key, expected in REQUIRED_FIELDS.items():
        if key not in client:
            raise KeyError(f"client #{position} is missing the '{key}' setting")
        value = client[key]
        if not isinstance(value, expected) or isinstance(value, bool):
            found = type(value).__name__
            raise TypeError(f"client #{position}: '{key}' must be {expected.__name__}, got {found}")
    if not client["id"].strip():
        raise ValueError(f"client #{position} has an empty identifier")
    return client


def format_setting(key, value):
    if isinstance(value, int):
        return f"{INDENT}{key} = {value}"
    return f'{INDENT}{key} = "{value}"'


def format_client(client):
    lines = [f"client {client['id']} {{}}".replace("{}", "{")]
    for key in REQUIRED_FIELDS:
        if key == "id":
            continue
        lines.append(format_setting(key, client[key]))
    lines.append("}")
    return "\n".join(lines)


def generate(clients):
    blocks = []
    for position, client in enumerate(clients, start=1):
        validate_client(client, position)
        blocks.append(format_client(client))
    return "\n\n".join(blocks)


