def _require(definition, key, expected, index):
    if key not in definition:
        raise KeyError(f"host #{index} is missing the required field '{key}'")
    value = definition[key]
    if not isinstance(value, expected):
        got = type(value).__name__
        raise TypeError(f"host #{index} field '{key}' must be {expected.__name__}, got {got}")
    return value


def normalize_forward_agent(flag):
    cleaned = flag.strip().lower()
    if cleaned in ("yes", "true", "on", "1"):
        return "yes"
    if cleaned in ("no", "false", "off", "0"):
        return "no"
    raise ValueError(f"unrecognised forward agent flag: {flag!r}")


def validate(definition, index):
    alias = _require(definition, "alias", str, index).strip()
    if not alias:
        raise ValueError(f"host #{index} has an empty alias")
    hostname = _require(definition, "hostname", str, index).strip()
    if not hostname:
        raise ValueError(f"host '{alias}' has an empty hostname")
    port = _require(definition, "port", int, index)
    if not 1 <= port <= 65535:
        raise ValueError(f"host '{alias}' has a port outside 1-65535: {port}")
    timeout = _require(definition, "timeout", int, index)
    if timeout <= 0:
        raise ValueError(f"host '{alias}' needs a positive timeout, not {timeout}")
    keep_alive = _require(definition, "keep_alive_interval", int, index)
    if keep_alive < 0:
        raise ValueError(f"host '{alias}' needs a non-negative keep alive, not {keep_alive}")
    return {
        "alias": alias,
        "hostname": hostname,
        "username": _require(definition, "username", str, index).strip(),
        "port": port,
        "identity_file": _require(definition, "identity_file", str, index).strip(),
        "timeout": timeout,
        "keep_alive_interval": keep_alive,
        "forward_agent": normalize_forward_agent(_require(definition, "forward_agent", str, index)),
    }


def render_host(entry):
    lines = [f"Host {entry['alias']}"]
    lines.append(f"    HostName {entry['hostname']}")
    lines.append(f"    User {entry['username']}")
    lines.append(f"    Port {entry['port']}")
    lines.append(f"    IdentityFile {entry['identity_file']}")
    lines.append(f"    ConnectTimeout {entry['timeout']}")
    lines.append(f"    ServerAliveInterval {entry['keep_alive_interval']}")
    lines.append(f"    ForwardAgent {entry['forward_agent']}")
    return "\n".join(lines)


def generate(hosts):
    blocks = []
    for index, definition in enumerate(hosts, start=1):
        blocks.append(render_host(validate(definition, index)))
    return "\n\n".join(blocks)


def main():
    hosts = [
        {"alias": "web", "hostname": "web.example.com", "username": "deploy", "port": 22,
         "identity_file": "~/.ssh/id_deploy", "timeout": 10, "keep_alive_interval": 60,
         "forward_agent": "yes"},
        {"alias": "db", "hostname": "10.0.3.17", "username": "dbadmin", "port": 2222,
         "identity_file": "~/.ssh/id_db", "timeout": 15, "keep_alive_interval": 30,
         "forward_agent": "no"},
    ]
    config = generate(hosts)
    print(config)
    print(f"\n# {len(hosts)} host block(s), {len(config.splitlines())} line(s) rendered")


