    lines = [f"frontend {proxy['frontend_name']}"]
    lines.append(f"    bind {proxy['bind_address']}:{proxy['bind_port']}")
    lines.append(f"    timeout client {proxy['timeout_client']}ms")
    lines.append(f"    default_backend {proxy['backend_name']}")
