REQUIRED_SETTINGS = {
    "input_port": str,
    "input_type": str,
    "match_field": str,
    "match_pattern": str,
    "target_index": str,
    "template_name": str,
    "pipeline_workers": int,
    "elasticsearch_hosts": list,
}


def validate_pipeline(pipeline):
    """Check that the pipeline description carries every setting we render."""
    for key, kind in REQUIRED_SETTINGS.items():
        if key not in pipeline:
            raise KeyError(f"missing pipeline setting: {key}")
        value = pipeline[key]
        if not isinstance(value, kind) or isinstance(value, bool):
            raise TypeError(f"setting {key!r} must be of type {kind.__name__}")
    workers = pipeline["pipeline_workers"]
    if workers < 1:
        raise ValueError(f"pipeline_workers must be at least 1, got {workers}")
    hosts = pipeline["elasticsearch_hosts"]
    if not hosts:
        raise ValueError("elasticsearch_hosts must contain at least one host")
    for host in hosts:
        if not isinstance(host, str):
            raise TypeError(f"elasticsearch host {host!r} is not a string")


def format_hosts(hosts):
    """Render the host list as a Logstash array literal."""
    quoted = [f'"{host}"' for host in hosts]
    return "[" + ", ".join(quoted) + "]"


def global_block(workers):
    settings = f"  pipeline.workers: {workers}"
    return "\n".join(["settings {", settings, "}"])


def input_block(port, input_type):
    lines = ["input {", "  beats {"]
    lines.append(f"    port => {port}")
    lines.append(f'    type => "{input_type}"')
    lines.extend(["  }", "}"])
    return "\n".join(lines)


def filter_block(field, pattern):
    match = f'      "{field}" => "{pattern}"'
    lines = ["filter {", "  grok {", "    match => {", match, "    }", "  }", "}"]
    return "\n".join(lines)


def output_block(hosts, index, template_name):
    lines = ["output {", "  elasticsearch {"]
    lines.append(f"    hosts => {format_hosts(hosts)}")
    lines.append(f'    index => "{index}"')
    lines.append(f'    template_name => "{template_name}"')
    lines.extend(["  }", "}"])
    return "\n".join(lines)


def configure(pipeline):
    """Build a complete Logstash configuration from a pipeline dictionary."""
    validate_pipeline(pipeline)
    blocks = [
        global_block(pipeline["pipeline_workers"]),
        input_block(pipeline["input_port"], pipeline["input_type"]),
        filter_block(pipeline["match_field"], pipeline["match_pattern"]),
        output_block(
            pipeline["elasticsearch_hosts"],
            pipeline["target_index"],
            pipeline["template_name"],
        ),
    ]
    return "\n\n".join(blocks) + "\n"


def main():
    pipeline = {
        "input_port": "5044",
        "input_type": "filebeat",
        "match_field": "message",
        "match_pattern": "%{COMBINEDAPACHELOG}",
        "target_index": "weblogs-%{+YYYY.MM.dd}",
        "template_name": "weblogs",
        "pipeline_workers": 4,
        "elasticsearch_hosts": ["es-01:9200", "es-02:9200"],
    }
    config = configure(pipeline)
    print(config, end="")
    print(f"# {len(config.splitlines())} lines for index {pipeline['target_index']}")


if __name__ == "__main__":
