def fqdn(name):
    """Return a fully qualified (dot terminated) version of *name*."""
    if name.endswith("."):
        return name
    return f"{name}."


def admin_contact(email):
    """Turn an admin email address into zone-file contact notation."""
    local, at, domain = email.partition("@")
    if at:
        return fqdn(f"{local}.{domain}")
    return fqdn(email)


def check_keys(zone):
    for key in ("domain", "admin", "serial", "refresh", "retry",
                "expiry", "minimum", "nameserver", "records"):
        if key not in zone:
            raise KeyError(f"zone definition is missing the '{key}' entry")


def check_timings(zone):
    for key in ("serial", "refresh", "retry", "expiry", "minimum"):
        value = zone[key]
        if not isinstance(value, int) or value < 0:
            raise ValueError(f"{key} must be a non-negative integer, got {value!r}")


def check_address(ip):
    octets = ip.split(".")
    if len(octets) != 4:
        raise ValueError(f"address {ip!r} does not have four octets")
    for octet in octets:
        if not octet.isdigit() or int(octet) > 255:
            raise ValueError(f"invalid octet {octet!r} in address {ip}")


def soa_lines(zone):
    origin = fqdn(zone["domain"])
    server = fqdn(zone["nameserver"])
    contact = admin_contact(zone["admin"])
    lines = [f"{origin}\tIN\tSOA\t{server} {contact} ("]
    for key, comment in (("serial", "serial"), ("refresh", "refresh"),
                         ("retry", "retry"), ("expiry", "expire"),
                         ("minimum", "minimum TTL")):
        lines.append(f"\t\t\t\t{zone[key]}\t; {comment}")
    lines.append("\t\t\t\t)")
    return lines


def build(zone):
    check_keys(zone)
    check_timings(zone)
    origin = fqdn(zone["domain"])
    lines = [f"$TTL {zone['minimum']}"]
    lines.extend(soa_lines(zone))
    lines.append("")
    lines.append(f"{origin}\tIN\tNS\t{fqdn(zone['nameserver'])}")
    for record in zone["records"]:
        check_address(record["ip"])
        sub = record["subdomain"]
        name = origin if sub in ("", "@") else fqdn(f"{sub}.{zone['domain']}")
        lines.append(f"{name}\tIN\tA\t{record['ip']}")
    return "\n".join(lines) + "\n"


