def _validate(function):
    missing = [field for field in REQUIRED_FIELDS if field not in function]
    if missing:
        raise KeyError(f"missing documentation fields: {', '.join(missing)}")
    params = function["params"]
    if not isinstance(params, list):
        raise TypeError(f"'params' must be a list of tuples, got {type(params).__name__}")
    for index, entry in enumerate(params):
        if len(entry) != 2:
            raise ValueError(f"parameter entry {index} must be a (name, description) pair")


def _directive(tag, value):
    return f" * @{tag} {value}"


def _param_directive(name, description):
    return f" * @param {name} {description}"


def document(function):
    _validate(function)
    lines = ["/**", _directive("brief", function["brief"])]
    for name, description in function["params"]:
        lines.append(_param_directive(name, description))
    lines.append(_directive("return", function["returns"]))
    lines.append(_directive("author", function["author"]))
    lines.append(_directive("date", function["date"]))
    lines.append(_directive("version", function["version"]))
    lines.append(_directive("deprecated", function["deprecated"]))
    lines.append(" */")
    return "\n".join(lines)


def summarize(function):
