PLUGIN_DIR = "/usr/lib/nagios/plugins"

REQUIRED_FIELDS = (
    "command", "plugin", "warning", "critical",
    "user", "timeout", "retries", "args",
)


def _validate(check, index):
    for field in REQUIRED_FIELDS:
        if field not in check:
            raise ValueError(f"check #{index} is missing the field {field!r}")
    for field in ("command", "plugin", "user", "args"):
        if not isinstance(check[field], str):
            raise ValueError(f"check #{index}: {field!r} must be a string")
    for field in ("warning", "critical", "timeout", "retries"):
        if not isinstance(check[field], int) or isinstance(check[field], bool):
            raise ValueError(f"check #{index}: {field!r} must be an integer")
    if check["timeout"] <= 0:
        raise ValueError(f"check #{index}: timeout must be positive, got {check['timeout']}")


def plugin_path(plugin):
    return f"{PLUGIN_DIR}/{plugin}"


def build_command(check):
    parts = [
        plugin_path(check["plugin"]),
        f"-w {check['warning']}",
        f"-c {check['critical']}",
        f"-t {check['timeout']}",
        f"-r {check['retries']}",
        f"-u {check['user']}",
        check["args"],
    ]
    return " ".join(part for part in parts if part)


def configure(checks):
    lines = []
    for index, check in enumerate(checks, start=1):
        _validate(check, index)
        lines.append(f"[{check['command']}]={build_command(check)}")
    return "\n".join(lines)


def summarize(checks):
    report = [f"configured commands: {len(checks)}"]
    for check in checks:
        span = check["critical"] - check["warning"]
        report.append(f"  {check['command']}: alert span {span} on {check['plugin']}")
    return "\n".join(report)


def main():
    checks = [
        {"command": "check_load", "plugin": "check_load", "warning": 5, "critical": 10,
         "user": "nagios", "timeout": 30, "retries": 3, "args": "--percpu"},
        {"command": "check_disk_root", "plugin": "check_disk", "warning": 80, "critical": 95,
         "user": "monitor", "timeout": 20, "retries": 2, "args": "-p /"},
        {"command": "check_http_site", "plugin": "check_http", "warning": 2, "critical": 5,
         "user": "nagios", "timeout": 15, "retries": 1, "args": "-H example.org -S"},
    ]
    print(configure(checks))
    print()
    print(summarize(checks))


if __name__ == "__main__":
    main()

