        if not isinstance(check[field], int) or isinstance(check[field], bool):
            raise ValueError("check #{}: {!r} must be an integer".format(index, field))
    if check["timeout"] <= 0:
        raise ValueError("check #{}: timeout must be positive, got {}".format(index, check['timeout']))


def plugin_path(plugin):
    return "{}/{}".format(PLUGIN_DIR, plugin)


def build_command(check):
    parts = [
        plugin_path(check["plugin"]),
        "-w {}".format(check['warning']),
        "-c {}".format(check['critical']),
        "-t {}".format(check['timeout']),
        "-r {}".format(check['retries']),
        "-u {}".format(check['user']),
        check["args"],
    ]
    return " ".join(part for part in parts if part)


def configure(checks):
    lines = []
    for index, check in enumerate(checks, start=1):
        _validate(check, index)
        lines.append("[{}]={}".format(check['command'], build_command(check)))
    return "\n".join(lines)


def summarize(checks):
    report = ["configured commands: {}".format(len(checks))]
    for check in checks:
        span = check["critical"] - check["warning"]
        report.append("  {}: alert span {} on {}".format(check['command'], span, check['plugin']))
    return "\n".join(report)


def main():
    checks = [
        {"command": "check_load", "plugin": "check_load", "warning": 5, "critical": 10,
         "user": "nagios", "timeout": 30, "retries": 3, "args": "--percpu"},
