import sys


REQUIRED_KEYS = (
    "source_pool",
    "source_fs",
    "snapshot_name",
    "remote_user",
    "remote_host",
    "destination_pool",
    "destination_fs",
    "ssh_key",
    "bandwidth_limit",
)


def validate(replication):
    missing = [key for key in REQUIRED_KEYS if key not in replication]
    if missing:
        raise KeyError("missing backup instructions: {}".format(', '.join(missing)))
    limit = replication["bandwidth_limit"]
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise TypeError("bandwidth_limit must be an int, got {}".format(type(limit).__name__))
    if limit <= 0:
        raise ValueError("bandwidth_limit must be positive, got {}".format(limit))
    return limit


def dataset(pool, filesystem):
    return "{}/{}".format(pool, filesystem)


def snapshot_target(replication):
    source = dataset(replication["source_pool"], replication["source_fs"])
    return "{}@{}".format(source, replication['snapshot_name'])


def ssh_command(replication):
    destination = dataset(replication["destination_pool"], replication["destination_fs"])
    login = "{}@{}".format(replication['remote_user'], replication['remote_host'])
    receive = "zfs receive -F {}".format(destination)
    return "ssh -i {} {} '{}'".format(replication['ssh_key'], login, receive)


def script(replication):
    limit = validate(replication)
    target = snapshot_target(replication)
    create = "zfs snapshot -r {}".format(target)
    throttle = "pv -q -L {}m".format(limit)
    transfer = "zfs send -R {} | {} | {}".format(target, throttle, ssh_command(replication))
    log = 'echo "{} $(date)" >> /var/log/zfs-replication.log'.format(replication["snapshot_name"])
    return "\n".join([create, transfer, log])


def main():
    plan = {
        "source_pool": "tank",
        "source_fs": "projects",
        "snapshot_name": "nightly-2024-05-01",
        "remote_user": "backup",
        "remote_host": "offsite.example.com",
        "destination_pool": "vault",
        "destination_fs": "projects",
        "ssh_key": "/root/.ssh/replication_ed25519",
        "bandwidth_limit": 40,
    }
    try:
        body = script(plan)
    except (KeyError, TypeError, ValueError) as error:
        sys.exit("cannot build replication script: {}".format(error))
    print("#!/bin/bash")
    print("set -euo pipefail")
    print(body)


if __name__ == "__main__":
    main()

