OPERATIONS = ("match", "create", "relate")


def validate(operation):
    if len(operation) != 8:
        raise ValueError(f"expected 8 fields per operation, got {len(operation)}")
    kind = operation[0]
    if kind not in OPERATIONS:
        raise ValueError(f"unsupported operation type: {kind!r}")
    return kind


def match_lines(label, node_id, prop):
    return [
        f"MATCH (n:{label}) WHERE id(n) = {node_id};",
        f"RETURN n.{prop};",
    ]


def create_lines(label, prop, value):
    escaped = value.replace("'", "\\'")
    node = f"CREATE (n:{label} {{{prop}: '{escaped}'}});"
    index = f"CREATE INDEX ON :{label}({prop});"
    return [node, index]


def relate_lines(node_id, target_id, target_label, rel_type):
    lines = [f"MATCH (a) WHERE id(a) = {node_id};"]
    lines.append(f"MATCH (b:{target_label}) WHERE id(b) = {target_id};")
    lines.append(f"CREATE (a)-[:{rel_type}]->(b);")
    return lines


def cypher(operations):
    queries = []
    for operation in operations:
        kind = validate(operation)
        _, label, node_id, prop, value, target_id, target_label, rel_type = operation
        if kind == "match":
            queries.extend(match_lines(label, node_id, prop))
        elif kind == "create":
            queries.extend(create_lines(label, prop, value))
        else:
            queries.extend(relate_lines(node_id, target_id, target_label, rel_type))
    return queries


def summarize(operations):
    counts = {kind: 0 for kind in OPERATIONS}
    for operation in operations:
        counts[validate(operation)] += 1
    parts = [f"{kind}={counts[kind]}" for kind in OPERATIONS]
    return " ".join(parts)


def main():
    script = [
        ("create", "Person", 1, "name", "Alice", 2, "Department", "WORKS_IN"),
        ("relate", "Person", 1, "name", "Alice", 2, "Department", "WORKS_IN"),
        ("match", "Department", 2, "title", "Research", 0, "", ""),
    ]
    print(f"operation mix: {summarize(script)}")
    lines = cypher(script)
    width = len(str(len(lines)))
    for number, line in enumerate(lines, start=1):
        print(f"{number:>{width}}  {line}")
    print(f"generated {len(lines)} query lines")


if __name__ == "__main__":
