        "meta:",
        f'    author = "{author}"',
        f'    date = "{date}"',
        f"    threat_level = {threat_level}",
    ]


def format_strings(hex_pattern, text_pattern):
    cleaned = " ".join(hex_pattern.split())
    return [
        "strings:",
        "    $hex_pattern = { " + cleaned + " }",
        f'    $text_pattern = "{text_pattern}"',
    ]


def format_condition(size_limit):
    return [
        "condition:",
        f"    filesize < {size_limit}KB and $hex_pattern and $text_pattern",
    ]


def validate(rule):
    name, author, date, threat_level, hex_pattern, text_pattern, size_limit, is_global = rule
    if not name.strip():
        raise ValueError("rule name must not be empty")
    if isinstance(threat_level, bool) or not isinstance(threat_level, int):
        raise ValueError(f"threat level for rule {name} must be an int")
    if isinstance(size_limit, bool) or not isinstance(size_limit, int):
        raise ValueError(f"file size limit for rule {name} must be an int")
    return name, author, date, threat_level, hex_pattern, text_pattern, size_limit, is_global


