def _validate(machine):
    if len(machine) != 8:
        raise ValueError(f"expected 8 fields per machine, got {len(machine)}")
    name, box, memory, cpus, ip, host_dir, guest_dir, port = machine
    if not name:
        raise ValueError(f"machine name must not be empty (box {box!r})")
    if memory <= 0:
        raise ValueError(f"machine {name!r} has invalid memory {memory}")
    if cpus <= 0:
        raise ValueError(f"machine {name!r} has invalid cpu count {cpus}")
    if not 1 <= port <= 65535:
        raise ValueError(f"machine {name!r} has invalid forwarded port {port}")
    return name, box, memory, cpus, ip, host_dir, guest_dir, port


def vagrant(machines):
    lines = []
    for machine in machines:
        name, box, memory, cpus, ip, host_dir, guest_dir, port = _validate(machine)
        lines.append(f'config.vm.define "{name}" do |{name}|')
        lines.append(f'  {name}.vm.box = "{box}"')
        lines.append(f'  {name}.vm.network "private_network", ip: "{ip}"')
        lines.append(f'  {name}.vm.synced_folder "{host_dir}", "{guest_dir}"')
        lines.append(f'  {name}.vm.network "forwarded_port", guest: 80, host: {port}')
        lines.append(f'  {name}.vm.provider "virtualbox" do |vb|')
        lines.append(f'    vb.memory = "{memory}"')
        lines.append(f'    vb.cpus = {cpus}')
        lines.append(f'    vb.name = "{name}"')
        lines.append("  end")
        lines.append("end")
    return lines


def render_vagrantfile(machines):
    body = vagrant(machines)
    out = ['Vagrant.configure("2") do |config|']
    for line in body:
        out.append(f"  {line}")
    out.append("end")
    return "\n".join(out)


def summarize(machines):
    report = []
    total_memory = 0
    total_cpus = 0
    for machine in machines:
        name, box, memory, cpus, ip, host_dir, guest_dir, port = _validate(machine)
        total_memory += memory
        total_cpus += cpus
        report.append(f"{name}: {box} @ {ip} ({memory} MB, {cpus} vCPU)")
        report.append(f"  mount {host_dir} -> {guest_dir}, http on localhost:{port}")
    report.append(f"total: {len(machines)} machine(s), {total_memory} MB, {total_cpus} vCPU")
    return report


def main():
    machines = [
        ("webserver", "ubuntu/focal64", 1024, 2, "192.168.33.10", "./src", "/var/www", 8080),
        ("database", "debian/bullseye64", 2048, 4, "192.168.33.11", "./data", "/var/lib/pgsql", 5432),
    ]
    print(render_vagrantfile(machines))
