LOG_FORMAT = "%ts.%03tu %6tr %>a %Ss/%03>Hs %<st %rm %ru %[un %Sh/%<a %mt"


def validate(policy):
    name, network, domain, port, maxconn, days, timerange, allow = policy
    if not name or any(c.isspace() for c in name):
        raise ValueError(f"invalid access control name: {name!r}")
    if "/" not in network:
        raise ValueError(f"network for {name} must include a prefix length: {network}")
    if not domain.startswith("."):
        raise ValueError(f"domain for {name} must start with a dot: {domain}")
    if not 1 <= port <= 65535:
        raise ValueError(f"port for {name} out of range: {port}")
    if maxconn < 1:
        raise ValueError(f"maximum connections for {name} must be positive: {maxconn}")
    if "-" not in timerange:
        raise ValueError(f"time range for {name} must be HH:MM-HH:MM: {timerange}")
    if not days:
        raise ValueError(f"days of week for {name} must not be empty")
    return name, network, domain, port, maxconn, days, timerange, allow


def acl_lines(name, network, domain, port, maxconn, days, timerange):
    return [
        f"acl {name} src {network}",
        f"acl {name} dstdomain {domain}",
        f"acl {name} port {port}",
        f"acl {name} maxconn {maxconn}",
        f"acl {name} time {days} {timerange}",
    ]


def access_lines(name, allow):
    verdict = "allow" if allow else "deny"
    return [
        f"http_access {verdict} {name}",
        f"cache allow {name}",
    ]


def logging_lines(name):
    fmt = f"{name}_fmt"
    return [
        f"logformat {fmt} {LOG_FORMAT}",
        f"access_log daemon:/var/log/squid/{name}.log {fmt} {name}",
    ]


def squid(policies):
    lines = []
    for policy in policies:
        name, network, domain, port, maxconn, days, timerange, allow = validate(policy)
        lines.extend(acl_lines(name, network, domain, port, maxconn, days, timerange))
        lines.extend(access_lines(name, allow))
        lines.extend(logging_lines(name))
    return lines


def main():
    policies = [
        ("office", "10.0.0.0/8", ".example.com", 8080, 100, "MTWHF", "09:00-17:00", True),
        ("guests", "192.168.5.0/24", ".social.net", 3128, 20, "SMTWHFA", "08:00-20:00", False),
    ]
    config = squid(policies)
    print(f"# squid.conf generated from {len(policies)} policies")
    for line in config:
        print(line)
    denied = [p[0] for p in policies if not p[-1]]
    print(f"# blocked groups: {', '.join(denied) or 'none'}")


if __name__ == "__main__":
    main()

