def type_attribute(data_type, nullable):
    if nullable:
        return f'  "type": ["{data_type}", "null"],'
    return f'  "type": "{data_type}",'


def validate_property(prop):
    if len(prop) != 8:
        raise ValueError(f"property tuple must have 8 fields, got {len(prop)}")
    key, data_type, fmt, description, min_len, max_len, default, nullable = prop
    if not key:
        raise ValueError("property key name must not be empty")
    if not isinstance(min_len, int) or not isinstance(max_len, int):
        raise TypeError(f"length bounds for {key} must be integers")
    if min_len > max_len:
        raise ValueError(f"minLength {min_len} exceeds maxLength {max_len} for {key}")
    if not isinstance(nullable, bool):
        raise TypeError(f"nullable flag for {key} must be a boolean")
    return key, data_type, fmt, description, min_len, max_len, default, nullable


def property_lines(prop):
    key, data_type, fmt, description, min_len, max_len, default, nullable = validate_property(prop)
    lines = [f'"{key}": {{']
    lines.append(type_attribute(data_type, nullable))
    lines.append(f'  "format": "{fmt}",')
    lines.append(f'  "description": "{description}",')
    lines.append(f'  "minLength": {min_len},')
    lines.append(f'  "maxLength": {max_len},')
    lines.append(f'  "default": "{default}",')
    lines.append(f'  "errorMessage": "Invalid {key}"')
    lines.append("}")
    lines.append(f"// Processed {key}")
    return lines


def jsonschema(properties):
    lines = []
    for prop in properties:
        lines.extend(property_lines(prop))
    return lines


def schema_document(title, properties):
    body = jsonschema(properties)
    document = ["{", f'  "title": "{title}",', '  "type": "object",', '  "properties": {']
    for line in body:
        document.append(f"    {line}")
    document.append("  }")
    document.append("}")
    return document


def summarize(properties):
    names = ", ".join(prop[0] for prop in properties)
    nullable_count = sum(1 for prop in properties if prop[7])
    header = f"{len(properties)} properties defined: {names}"
    detail = f"{nullable_count} of them accept null values"
    return [header, detail]


