FIELDS = ("title", "partition", "kernel", "initrd", "uuid", "gfxmode", "timeout", "splash")


def _validate(position, entry):
    if len(entry) != len(FIELDS):
        raise ValueError(f"entry {position} needs exactly {len(FIELDS)} fields")
    for name, value in zip(FIELDS[:6], entry[:6]):
        if not isinstance(value, str) or not value.strip():
            raise ValueError(f"entry {position}: field '{name}' must be a non-empty string")
    timeout, splash = entry[6], entry[7]
    if isinstance(timeout, bool) or not isinstance(timeout, int) or timeout < 0:
        raise ValueError(f"entry {position}: timeout must be a non-negative integer, got {timeout!r}")
    if not isinstance(splash, bool):
        raise ValueError(f"entry {position}: splash must be a boolean, got {splash!r}")


def grub(kernels):
    lines = []
    for position, entry in enumerate(kernels, start=1):
        _validate(position, entry)
        title, partition, kernel, initrd, uuid, gfxmode, timeout, splash = entry
        cmdline = "quiet splash" if splash else "quiet"
        lines.append(f"menuentry '{title}' {{")
        lines.append(f"  set timeout={timeout}")
        lines.append(f"  search --no-floppy --fs-uuid --set=root {partition}")
        lines.append(f"  linux {kernel} root=UUID={uuid} {cmdline}")
        lines.append(f"  set gfxpayload={gfxmode}")
        if splash:
            lines.append(f"  splashimage=({partition})/boot/splash.xpm.gz")
        else:
            lines.append("  splashimage=none")
        lines.append(f"  initrd {initrd}")
        lines.append("}")
        lines.append(f"echo 'Loaded {title}'")
    return lines


def summarize(kernels):
    summary = []
    for entry in kernels:
        title, partition, kernel = entry[0], entry[1], entry[2]
        timeout, splash = entry[6], entry[7]
        state = "on" if splash else "off"
        summary.append(f"{title}: {kernel} from {partition}, timeout {timeout}s, splash {state}")
    return summary


def write_config(kernels, path):
    lines = grub(kernels)
    with open(path, "w", encoding="utf-8") as handle:
        for line in lines:
            handle.write(f"{line}\n")
    return len(lines)


def main():
    kernels = [
        ("Ubuntu", "hd0,msdos1", "/boot/vmlinuz", "/boot/initrd.img", "1234-5678", "keep", 5, True),
        ("Recovery", "hd0,msdos2", "/boot/vmlinuz-old", "/boot/initrd-old.img", "8765-4321", "1024x768", 10, False),
    ]
    for line in grub(kernels):
        print(line)
    print()
    for row in summarize(kernels):
        print(f"- {row}")
    written = write_config(kernels, "grub.cfg")
    print(f"wrote {written} lines to grub.cfg")


if __name__ == "__main__":
    main()

