GRADE_POINTS = {
    "A": 4.0, "A-": 3.7, "B+": 3.3, "B": 3.0, "B-": 2.7,
    "C+": 2.3, "C": 2.0, "C-": 1.7, "D": 1.0, "F": 0.0,
}
WIDTH = 48


def header_lines():
    return ["STATE UNIVERSITY", "OFFICIAL ACADEMIC TRANSCRIPT", "=" * WIDTH]


def student_block(student):
    lines = [f"Student: {student['name']}"]
    lines.append(f"Student ID: {student['id']}")
    lines.append(f"Major: {student['major']}")
    return lines


def course_line(course):
    subject, number, title, credits, grade = course
    return f"{subject} {number} {title} - {credits} credits (Grade: {grade})"


def term_heading(term):
    return f"{term['name']} {term['year']}"


def earned_credits(courses):
    return sum(credits for _, _, _, credits, grade in courses if grade != "F")


def quality_points(courses):
    total = 0.0
    for subject, number, _, credits, grade in courses:
        if grade not in GRADE_POINTS:
            raise ValueError(f"Unknown grade {grade!r} for {subject} {number}")
        total += GRADE_POINTS[grade] * credits
    return total


def semester_lines(term):
    lines = ["", term_heading(term), "-" * WIDTH]
    for course in term["courses"]:
        lines.append(course_line(course))
    lines.append(f"Term credits earned: {earned_credits(term['courses'])}")
    return lines


def degree_lines(degree, total_credits, gpa):
    lines = ["", "=" * WIDTH, f"Total credits earned: {total_credits}"]
    lines.append(f"Cumulative GPA: {gpa:.2f}")
    honors = degree.get("honors")
    award = f"Degree awarded {degree['graduation_date']}"
    if honors:
        award = f"{award}, {honors}"
    lines.append(award)
    return lines


def render_transcript(student, semesters, degree):
    lines = header_lines() + student_block(student)
    total_credits = 0
    total_points = 0.0
    graded_credits = 0
    for term in semesters:
        lines.extend(semester_lines(term))
        total_credits += earned_credits(term["courses"])
        total_points += quality_points(term["courses"])
        graded_credits += sum(c[3] for c in term["courses"])
    gpa = total_points / graded_credits if graded_credits else 0.0
    lines.extend(degree_lines(degree, total_credits, gpa))
    return "\n".join(lines)


def format(student, semesters, degree):
    return render_transcript(student, semesters, degree)


def main():
    student = {"name": "Bob", "id": "S-10482", "major": "Computer Science"}
    semesters = [
        {"name": "Fall", "year": 2023, "courses": [
            ("CS", 101, "Intro", 3, "A"),
            ("MATH", 121, "Calculus I", 4, "B+"),
        ]},
        {"name": "Spring", "year": 2024, "courses": [
            ("CS", 201, "Data Structures", 4, "A-"),
            ("PHIL", 110, "Logic", 3, "B"),
        ]},
    ]
    degree = {"graduation_date": "May 2026", "honors": "cum laude"}
    print(render_transcript(student, semesters, degree))


if __name__ == "__main__":
    main()

