SOH = "\x01"
BEGIN_STRING = "FIX.4.2"

TAG_BEGIN_STRING = 8
TAG_BODY_LENGTH = 9
TAG_MSG_TYPE = 35
TAG_SENDER = 49
TAG_TARGET = 56
TAG_SEQ_NUM = 34
TAG_CHECKSUM = 10


def format_field(tag, value):
    try:
        tag_number = int(tag)
    except (TypeError, ValueError):
        raise ValueError(f"tag {tag!r} is not a numeric identifier")
    if tag_number <= 0:
        raise ValueError(f"tag {tag_number} must be a positive integer")
    text = str(value)
    if SOH in text:
        raise ValueError(f"value for tag {tag_number} contains the SOH delimiter")
    return f"{tag_number}={text}{SOH}"


def check_identifier(label, value):
    text = str(value).strip()
    if not text:
        raise ValueError(f"{label} identifier must not be empty")
    return text


def body_length(body):
    return len(body.encode("ascii"))


def checksum(payload):
    total = sum(payload.encode("ascii")) % 256
    return f"{total:03d}"


def readable(raw):
    return raw.replace(SOH, "|")


def describe(raw):
    lines = []
    for chunk in raw.split(SOH):
        if chunk:
            tag, _, value = chunk.partition("=")
            lines.append(f"  tag {tag:>3} -> {value}")
    return "\n".join(lines)


def build(sender, target, sequence, message, fields):
    sender_id = check_identifier("sender", sender)
    target_id = check_identifier("target", target)
    msg_type = check_identifier("message type", message)
    seq = int(sequence)
    if seq < 1:
        raise ValueError(f"sequence number {seq} must be 1 or greater")
    body = format_field(TAG_MSG_TYPE, msg_type)
    body += format_field(TAG_SENDER, sender_id)
    body += format_field(TAG_TARGET, target_id)
    body += format_field(TAG_SEQ_NUM, seq)
    for tag, value in fields:
        body += format_field(tag, value)
    head = format_field(TAG_BEGIN_STRING, BEGIN_STRING)
    head += format_field(TAG_BODY_LENGTH, body_length(body))
    partial = head + body
    return partial + format_field(TAG_CHECKSUM, checksum(partial))


def main():
    order = build("CLIENT", "BROKER", 1, "D", [(11, "ORDER1"), (55, "AAPL"), (38, 100)])
    print(f"raw: {readable(order)}")
    print(f"length: {len(order)} bytes")
    print(describe(order))
    heartbeat = build("CLIENT", "BROKER", 2, "0", [])
    print(f"heartbeat: {readable(heartbeat)}")


if __name__ == "__main__":
    main()

