def _check_port(name, port):
    if not isinstance(port, int) or isinstance(port, bool):
        raise TypeError(f"source {name!r} has a non-integer port: {port!r}")
    if not 0 < port < 65536:
        raise ValueError(f"source {name!r} has an out-of-range port: {port}")
    return port


def source_block(name, port):
    _check_port(name, port)
    header = f"source {name} {{"
    body = f"    tcp(port({port}));"
    return "\n".join([header, body, "};"])


def filter_block(name, facility, priority):
    expression = f"facility({facility}) and level({priority})"
    header = f"filter {name} {{"
    body = f"    {expression};"
    return "\n".join([header, body, "};"])


def destination_block(name, path):
    if not path.startswith("/"):
        raise ValueError(f"destination {name!r} needs an absolute path, got {path!r}")
    header = f"destination {name} {{"
    body = f'    file("{path}");'
    return "\n".join([header, body, "};"])


def log_path(source_name, filter_name, destination_name):
    parts = [
        f"source({source_name})",
        f"filter({filter_name})",
        f"destination({destination_name})",
    ]
    return "log { " + "".join(f"{part}; " for part in parts) + "};"


def build(sources, filters, destinations):
    blocks = []
    for name, port in sources:
        blocks.append(source_block(name, port))
    for name, facility, priority in filters:
        blocks.append(filter_block(name, facility, priority))
    for name, path in destinations:
        blocks.append(destination_block(name, path))
    for source in sources:
        for filt in filters:
            for destination in destinations:
                blocks.append(log_path(source[0], filt[0], destination[0]))
    return "\n".join(blocks) + "\n"


def summarize(sources, filters, destinations):
    routes = len(sources) * len(filters) * len(destinations)
    counts = f"{len(sources)} sources, {len(filters)} filters, {len(destinations)} destinations"
    return f"# {counts} -> {routes} log paths"


def main():
    sources = [("net", 514), ("relay", 601)]
    filters = [("f1", "auth", "info"), ("f2", "mail", "warning")]
    destinations = [("d1", "/var/log/auth.log"), ("d2", "/var/log/mail.log")]
    print(summarize(sources, filters, destinations))
    print(build(sources, filters, destinations), end="")


if __name__ == "__main__":
    main()

