import re

IDENTIFIER = re.compile(r"[A-Za-z_][A-Za-z0-9_]*$")


def guard_name(module):
    cleaned = re.sub(r"[^A-Za-z0-9_]", "_", module.strip())
    if not IDENTIFIER.match(cleaned):
        raise ValueError(f"module name {module!r} cannot be used as an include guard")
    return f"{cleaned.upper()}_H"


def constant_line(name, value):
    if not IDENTIFIER.match(name):
        raise ValueError(f"invalid constant name: {name!r}")
    return f"#define {name} {int(value)}"


def field_line(ftype, fname):
    return f"    {ftype} {fname};"


def structure_block(name, fields):
    lines = [f"struct {name} {{"]
    for ftype, fname in fields:
        lines.append(field_line(ftype, fname))
    lines.append("};")
    return lines


def parameter_list(parameters):
    if not parameters:
        return "void"
    return ", ".join(f"{ptype} {pname}" for ptype, pname in parameters)


def prototype_line(return_type, name, parameters):
    return f"{return_type} {name}({parameter_list(parameters)});"


def generate(module, constants, structures, functions):
    guard = guard_name(module)
    lines = [f"#ifndef {guard}"]
    lines.append(f"#define {guard}")
    lines.append("")

    for name, value in constants:
        lines.append(constant_line(name, value))
    if constants:
        lines.append("")

    for name, fields in structures:
        lines.extend(structure_block(name, fields))
        lines.append("")

    for return_type, name, parameters in functions:
        lines.append(prototype_line(return_type, name, parameters))
    if functions:
        lines.append("")

    lines.append(f"#endif /* {guard} */")
    return "\n".join(lines)


def summarize(module, constants, structures, functions):
    counts = ", ".join([
        f"{len(constants)} constant(s)",
        f"{len(structures)} structure(s)",
        f"{len(functions)} prototype(s)",
    ])
    return f"{module.lower()}.h: {counts}"


def main():
    module = "MATH"
    constants = [("PI", 3), ("MAX_TERMS", 64)]
    structures = [("vector", [("double", "x"), ("double", "y")])]
    functions = [
        ("int", "add", [("int", "a"), ("int", "b")]),
        ("double", "length", [("struct vector", "v")]),
        ("void", "reset", []),
    ]
    print(generate(module, constants, structures, functions))
    print(f"/* {summarize(module, constants, structures, functions)} */")


if __name__ == "__main__":
    main()

