        raise ValueError(f"network #{index} must have 4 fields, got {len(entry)}")
    ssid, psk, priority, hidden = entry
    if not ssid:
        raise ValueError(f"network #{index} has an empty ssid")
    if len(psk) < 8:
        raise ValueError(f"psk for {ssid!r} is too short ({len(psk)} chars, need 8)")
    if not isinstance(priority, int):
        raise ValueError(f"priority for {ssid!r} must be an integer, got {type(priority).__name__}")
    return ssid, psk, priority, bool(hidden)


def network_block(ssid, psk, priority, hidden, indent="\t"):
    lines = ["network={"]
    lines.append(f'{indent}ssid="{ssid}"')
    lines.append(f'{indent}psk="{psk}"')
    lines.append(f"{indent}priority={priority}")
    scan_ssid = 1 if hidden else 0
    lines.append(f"{indent}scan_ssid={scan_ssid}")
    lines.append(f"{indent}key_mgmt=WPA-PSK")
    lines.append("}")
    return "\n".join(lines)


