import re

STANDARDS_VERSION = "4.6.2"
BUILD_DEPENDS = "debhelper-compat (= 13)"
SHARED_LIBRARY_DEPENDS = "${shlibs:Depends}, ${misc:Depends}"


def check_maintainer(maintainer):
    if "<" not in maintainer or ">" not in maintainer:
        raise ValueError(f"maintainer must contain an email address: {maintainer!r}")
    return maintainer.strip()


def check_homepage(homepage):
    if not homepage.startswith(("http://", "https://")):
        raise ValueError(f"homepage must be an http(s) address: {homepage!r}")
    return homepage.strip()


def normalize_depends(depends):
    if isinstance(depends, str):
        items = [part.strip() for part in depends.split(",") if part.strip()]
    else:
        items = [str(part).strip() for part in depends if str(part).strip()]
    items.append(SHARED_LIBRARY_DEPENDS)
    return ", ".join(items)


def split_sentences(description):
    text = description.strip()
    if not text:
        raise ValueError("description must not be empty")
    return re.split(r"(?<=[.!?])\s+", text)


def format_long_description(sentences):
    return "\n".join(f" {sentence}" for sentence in sentences)


def format(source, maintainer, homepage, binary, architecture, depends, description):
    sentences = split_sentences(description)
    short = sentences[0].rstrip(".")
    lines = [
        f"Source: {source.strip()}",
        f"Maintainer: {check_maintainer(maintainer)}",
        f"Build-Depends: {BUILD_DEPENDS}",
        f"Standards-Version: {STANDARDS_VERSION}",
        f"Homepage: {check_homepage(homepage)}",
        "",
        f"Package: {binary.strip()}",
        f"Architecture: {architecture.strip()}",
        f"Depends: {normalize_depends(depends)}",
        f"Description: {short}",
        format_long_description(sentences),
    ]
    return "\n".join(lines)


def main():
    packages = [
        ("hello", "Jane Doe <jane@example.org>", "https://example.org/hello",
         "hello-bin", "any", ["libc6 (>= 2.34)"],
         "A greeting program. It says hello."),
        ("tinytool", "Ali Khan <ali@example.net>", "https://example.net/tinytool",
         "tinytool", "amd64", "libssl3, zlib1g",
         "A tiny command line tool. It converts files. Output goes to stdout."),
    ]
    for source, maintainer, homepage, binary, architecture, depends, description in packages:
        print(f"=== debian/control for {source} ===")
        print(format(source, maintainer, homepage, binary, architecture, depends, description))
        print()


if __name__ == "__main__":
    main()

