from datetime import datetime


def _timestamp(now=None):
    moment = now or datetime.now()
    return f"{moment:%Y%m%d%H%M%S}"


def build_msh(facility, control_id, now=None):
    stamp = _timestamp(now)
    return f"MSH|^~\\&|{facility}|||{stamp}||ORU^R01|{control_id}|P|2.3"


def build_pid(patient):
    identifier, last, first = patient
    name = f"{last}^{first}"
    return f"PID|||{identifier}||{name}"


def build_pv1(visit):
    account, doctor = visit
    return f"PV1||O|||||||{doctor}|||||||||||{account}"


def build_obx(observation):
    code, value, date = observation
    return f"OBX|||{code}||{value}||||||F|||{date}"


def _control_id(patient, now=None):
    identifier = patient[0]
    return f"{identifier}{_timestamp(now)}"


def build(facility, patient, visit, observation):
    if not facility:
        raise ValueError("facility name is required")
    if len(patient) != 3:
        raise ValueError(f"patient needs 3 fields, got {len(patient)}")
    if len(visit) != 2:
        raise ValueError(f"visit needs 2 fields, got {len(visit)}")
    if len(observation) != 3:
        raise ValueError(f"observation needs 3 fields, got {len(observation)}")
    now = datetime.now()
    segments = [
        build_msh(facility, _control_id(patient, now), now),
        build_pid(patient),
        build_pv1(visit),
        build_obx(observation),
    ]
    return "\r".join(segments)


def describe(message):
    lines = []
    for segment in message.split("\r"):
        code = segment[:3]
        fields = segment.count("|")
        lines.append(f"{code}: {fields} separators")
    return "\n".join(lines)


def main():
    message = build("CLINIC", ("123", "Doe", "John"), ("A0099", "SMITH^JANE"),
                    ("HR", "60", "20231010"))
    for segment in message.split("\r"):
        print(segment)
    print(describe(message))
    print(f"total length: {len(message)} characters")


if __name__ == "__main__":
    main()

