import builtins
import sys
from datetime import datetime

WIDTH = 38


def _center(text):
    return f"{text:^{WIDTH}}"


def _divider(char="-"):
    return char * WIDTH


def _two_column(left, right):
    return f"{left:<{WIDTH - len(right)}}{right}"


def _money(amount):
    return f"{amount:.2f}"


def _header_lines(restaurant):
    if isinstance(restaurant, str):
        parts = restaurant.splitlines()
    else:
        parts = list(restaurant)
    return [_center(part.strip()) for part in parts if part.strip()]


def _stamp_line(moment):
    return f"{moment:%Y-%m-%d %H:%M}"


def _server_line(server, table):
    right = f"Table {table}"
    return _two_column(f"Server: {server}", right)


def _item_line(name, quantity, price):
    return _two_column(f"{quantity} {name}", _money(quantity * price))


def _validate(items, tax):
    if tax < 0:
        raise ValueError(f"tax rate must be non-negative, got {tax!r}")
    for entry in items:
        if len(entry) != 3:
            raise ValueError(f"item entry needs name, quantity, price: {entry!r}")
        name, quantity, price = entry
        if quantity <= 0 or price < 0:
            raise ValueError(f"bad quantity/price for {name!r}: {quantity}, {price}")


def build_receipt(restaurant, server, table, items, tax, moment=None):
    _validate(items, tax)
    lines = _header_lines(restaurant)
    lines.append(_stamp_line(moment or datetime.now()))
    lines.append(_server_line(server, table))
    lines.append(_divider())
    subtotal = 0.0
    for name, quantity, price in items:
        subtotal += quantity * price
        lines.append(_item_line(name, quantity, price))
    lines.append(_divider())
    tax_amount = subtotal * tax
    lines.append(_two_column("Subtotal", _money(subtotal)))
    lines.append(_two_column(f"Tax ({tax * 100:.1f}%)", _money(tax_amount)))
    lines.append(_two_column("Total", _money(subtotal + tax_amount)))
    lines.append(_center("Thank you, please come again!"))
    return "\n".join(lines)


def print(restaurant, server, table, items, tax):
    sys.stdout.write(f"{build_receipt(restaurant, server, table, items, tax)}\n")


def main():
    diner = ("Joe's Diner", "123 Main Street", "Springfield")
    order = [("Burger", 2, 5.00), ("Fries", 1, 2.50), ("Coffee", 3, 1.75)]
    print(diner, "Alice", 7, order, 0.05)
    try:
        print(diner, "Bob", 9, [("Soup", 0, 3.00)], 0.05)
    except ValueError as error:
        builtins.print(f"receipt rejected: {error}")


if __name__ == "__main__":
    main()

