def _validate(index, filer):
    if len(filer) != 5:
        raise ValueError(f"Filer #{index} must have 5 fields, got {len(filer)}.")
    name, income, deductions, bracket, status = filer
    if income < 0 or deductions < 0:
        raise ValueError(f"Negative income or deductions for {name}.")
    if bracket < 0 or bracket > 100:
        raise ValueError(f"Tax bracket {bracket} for {name} is out of range.")
    return name, income, deductions, bracket, str(status).strip().lower()


def taxable_income(income, deductions):
    return max(income - deductions, 0)


def tax_owed(taxable, bracket):
    return taxable * bracket / 100


def status_note(name, status):
    if status == "single":
        return f"Individual standard deductions applied for {name}."
    if status == "married":
        return f"Joint filing benefits applied for {name}."
    if status == "head of household":
        return f"Dependent considerations reviewed for {name}."
    return f"Unrecognized filing status '{status}' for {name}."


def balance_note(name, owed):
    if owed <= 0:
        return f"Full refund expected for {name}."
    if owed > 10000:
        return f"High balance due for {name}."
    return None


def taxes(filers):
    lines = [f"Processing {len(filers)} tax returns."]
    total = 0
    for index, filer in enumerate(filers, start=1):
        name, income, deductions, bracket, status = _validate(index, filer)
        taxable = taxable_income(income, deductions)
        owed = tax_owed(taxable, bracket)
        total += owed
        lines.append(f"{name} owes {owed} in taxes.")
        lines.append(status_note(name, status))
        note = balance_note(name, owed)
        if note is not None:
            lines.append(note)
    lines.append(f"Total revenue collected: {total}.")
    return lines


def main():
    filers = [
        ("Alice", 50000, 10000, 20, "single"),
        ("Bob", 120000, 20000, 30, "married"),
        ("Cara", 30000, 35000, 15, "head of household"),
    ]
