def _validate(index, action):
    if len(action) != 5:
        raise ValueError(f"Action {index} must have 5 fields, got {len(action)}.")
    player, kind, resource, amount, target = action
    if not isinstance(amount, (int, float)):
        raise TypeError(f"Action {index} has a non-numeric amount: {amount!r}.")
    return player, kind.lower(), resource.lower(), amount, target


def describe(player, kind, resource, amount, target):
    if kind == "harvest":
        return f"{player} collected {amount} of {resource}."
    if kind == "steal":
        return f"{player} stole {amount} of {resource} from {target}."
    if kind == "trade":
        return f"{player} traded {resource} with {target}."
    if kind == "build":
        return f"{player} constructed a building using {amount} of {resource}."
    return f"{player} did something unrecognized: {kind}."


def turns(actions):
    narrative = [f"Round start: {len(actions)} actions."]
    players = []
    for index, action in enumerate(actions, start=1):
        player, kind, resource, amount, target = _validate(index, action)
        narrative.append(describe(player, kind, resource, amount, target))
        if resource == "magic":
            narrative.append(f"Arcane energy gathered by {player}.")
        if amount > 5:
            narrative.append(f"A massive play by {player}!")
        if player not in players:
            players.append(player)
    narrative.append(f"A total of {len(players)} players competed.")
    return narrative


def scoreboard(actions):
    totals = {}
    for index, action in enumerate(actions, start=1):
        player, kind, _resource, amount, target = _validate(index, action)
        totals[player] = totals.get(player, 0) + amount
        if kind == "steal":
            totals[target] = totals.get(target, 0) - amount
    return totals


def report(actions):
    lines = turns(actions)
    ranked = sorted(scoreboard(actions).items(), key=lambda item: -item[1])
    for rank, (player, total) in enumerate(ranked, start=1):
        lines.append(f"#{rank} {player} nets {total} resources.")
    return lines


def main():
    round_one = [
        ("Bob", "harvest", "wood", 3, "none"),
        ("Sue", "steal", "gold", 6, "Bob"),
        ("Ada", "trade", "magic", 2, "Sue"),
        ("Bob", "build", "stone", 8, "none"),
    ]
    for line in report(round_one):
        print(line)
    try:
        turns([("Bob", "harvest", "wood")])
    except ValueError as error:
        print(f"Rejected malformed round: {error}")


if __name__ == "__main__":
    main()

