    if len(action) != 5:
        raise ValueError("Action {} must have 5 fields, got {}.".format(index, len(action)))
    player, kind, resource, amount, target = action
    if not isinstance(amount, (int, float)):
        raise TypeError("Action {} has a non-numeric amount: {!r}.".format(index, amount))
    return player, kind.lower(), resource.lower(), amount, target


def describe(player, kind, resource, amount, target):
    if kind == "harvest":
        return "{} collected {} of {}.".format(player, amount, resource)
    if kind == "steal":
        return "{} stole {} of {} from {}.".format(player, amount, resource, target)
    if kind == "trade":
        return "{} traded {} with {}.".format(player, resource, target)
    if kind == "build":
        return "{} constructed a building using {} of {}.".format(player, amount, resource)
    return "{} did something unrecognized: {}.".format(player, kind)


def turns(actions):
    narrative = ["Round start: {} actions.".format(len(actions))]
    players = []
    for index, action in enumerate(actions, start=1):
        player, kind, resource, amount, target = _validate(index, action)
        narrative.append(describe(player, kind, resource, amount, target))
        if resource == "magic":
            narrative.append("Arcane energy gathered by {}.".format(player))
        if amount > 5:
            narrative.append("A massive play by {}!".format(player))
        if player not in players:
            players.append(player)
    narrative.append("A total of {} players competed.".format(len(players)))
    return narrative


def scoreboard(actions):
    totals = {}
    for index, action in enumerate(actions, start=1):
        player, kind, _resource, amount, target = _validate(index, action)
        totals[player] = totals.get(player, 0) + amount
        if kind == "steal":
            totals[target] = totals.get(target, 0) - amount
    return totals


def report(actions):
    lines = turns(actions)
    ranked = sorted(scoreboard(actions).items(), key=lambda item: -item[1])
    for rank, (player, total) in enumerate(ranked, start=1):
        lines.append("#{} {} nets {} resources.".format(rank, player, total))
    return lines


def main():
    round_one = [
        ("Bob", "harvest", "wood", 3, "none"),
        ("Sue", "steal", "gold", 6, "Bob"),
        ("Ada", "trade", "magic", 2, "Sue"),
        ("Bob", "build", "stone", 8, "none"),
    ]
    for line in report(round_one):
        print(line)
    try:
        turns([("Bob", "harvest", "wood")])
    except ValueError as error:
        print("Rejected malformed round: {}".format(error))


if __name__ == "__main__":
    main()

