def _validate(index, plant):
    if len(plant) != 5:
        raise ValueError(f"Plant #{index} must have 5 fields, got {len(plant)}.")
    name, seed, days, sunlight, water = plant
    if not isinstance(days, int) or days <= 0:
        raise ValueError(f"Plant '{name}' has an invalid maturity value: {days!r}.")
    return name, seed, days, sunlight.strip().lower(), water.strip().lower()


def garden(plants):
    instructions = [f"Garden plan for {len(plants)} plants."]
    for index, plant in enumerate(plants, start=1):
        name, seed, days, sunlight, water = _validate(index, plant)
        instructions.append(f"{name} takes {days} days to mature.")
        if sunlight == "full sun":
            instructions.append(f"Plant the {seed} seeds in the brightest spot.")
        elif sunlight == "partial shade":
            instructions.append(f"Find a spot under a tree for the {seed} seeds.")
        if water == "daily":
            instructions.append(f"{name} needs watering every single day.")
        elif water == "weekly":
            instructions.append(f"{name} requires infrequent watering.")
        if days < 30:
            instructions.append(f"{name} is a fast growing crop.")
    instructions.append(f"Wishing you a bountiful harvest of {len(plants)} plants!")
    return instructions


def harvest_calendar(plants):
    calendar = []
    for plant in sorted(plants, key=lambda item: item[2]):
        name, days = plant[0], plant[2]
        weeks = days / 7
        calendar.append(f"{name}: ready in about {weeks:.1f} weeks ({days} days).")
    return calendar


def water_summary(plants):
    counts = {}
    for plant in plants:
        frequency = plant[4].strip().lower()
        counts[frequency] = counts.get(frequency, 0) + 1
    lines = []
    for frequency in sorted(counts):
        lines.append(f"{counts[frequency]} plant(s) on a {frequency} schedule.")
    return lines


def main():
    plants = [
        ("Tomato", "heirloom", 80, "full sun", "daily"),
        ("Radish", "cherry belle", 25, "partial shade", "weekly"),
        ("Basil", "genovese", 60, "full sun", "weekly"),
    ]
    for line in garden(plants):
        print(line)
    print()
    print(f"Harvest order for {len(plants)} crops:")
    for line in harvest_calendar(plants):
        print(f"  - {line}")
    print()
    print("Watering workload:")
    for line in water_summary(plants):
        print(f"  * {line}")
    earliest = min(plants, key=lambda item: item[2])
    print(f"First crop to pick: {earliest[0]} after {earliest[2]} days.")


if __name__ == "__main__":
    main()

