def validate_drink(entry, index):
    if len(entry) != 5:
        raise ValueError(f"Drink #{index} must have 5 fields, got {len(entry)}.")
    name, size, base, milk, price = entry
    if not isinstance(price, (int, float)):
        raise TypeError(f"Price for {name} must be numeric, got {type(price).__name__}.")
    return name, size.lower(), base.lower(), milk.lower(), price


def describe_drink(name, size, price):
    return f"{size} {name} - {price} dollars."


def milk_notes(name, milk):
    notes = []
    if milk == "oat":
        notes.append(f"Dairy free option available for the {name}.")
    if milk == "whole":
        notes.append(f"{name} has a rich and creamy texture.")
    return notes


def base_notes(name, base):
    notes = []
    if base == "espresso":
        notes.append(f"Strong caffeine kick from the {base}.")
    if base == "decaf":
        notes.append(f"Enjoy a jitter free experience with the {name}.")
    return notes


def menu(drinks):
    board = [f"Welcome! We have {len(drinks)} drinks today."]
    for index, entry in enumerate(drinks, start=1):
        name, size, base, milk, price = validate_drink(entry, index)
        board.append(describe_drink(name, size, price))
        board.extend(milk_notes(name, milk))
        board.extend(base_notes(name, base))
        if price > 5:
            board.append(f"{name} is a premium selection.")
    board.append(f"Shop is closing after serving {len(drinks)} drinks.")
    return board


def price_report(drinks):
    total = sum(entry[4] for entry in drinks)
    average = total / len(drinks) if drinks else 0
    priciest = max(drinks, key=lambda entry: entry[4])
    lines = [f"Total menu value: {total} dollars."]
    lines.append(f"Average drink price: {average:.2f} dollars.")
    lines.append(f"Most expensive drink: {priciest[0]} at {priciest[4]} dollars.")
    return lines


def main():
    drinks = [
        ("Latte", "large", "espresso", "oat", 6),
        ("Flat White", "small", "decaf", "whole", 4),
        ("Cold Brew", "medium", "cold brew", "almond", 5.5),
    ]
    for line in menu(drinks):
        print(line)
    print("-" * 40)
    for line in price_report(drinks):
        print(line)


if __name__ == "__main__":
    main()

