def validate(puzzle, index):
    if len(puzzle) != 5:
        raise ValueError(f"Puzzle {index} must have 5 fields, got {len(puzzle)}.")
    room, obj, item, lock, level = puzzle
    if lock not in ("combination", "key"):
        raise ValueError(f"Unknown lock type '{lock}' in puzzle {index}.")
    if level not in ("easy", "medium", "hard"):
        raise ValueError(f"Unknown difficulty '{level}' in puzzle {index}.")
    return room, obj, item, lock, level


def lock_clue(obj, lock):
    if lock == "combination":
        return f"You will need numbers to open the {obj}."
    return f"Search for a physical key for the {obj}."


def difficulty_clue(item, level):
    if level == "easy":
        return f"The {item} should be a quick find."
    if level == "hard":
        return f"Work together to reveal the {item}."
    return None


def clues(puzzles):
    total = len(puzzles)
    lines = [f"There are {total} puzzles to solve."]
    for index, puzzle in enumerate(puzzles, start=1):
        room, obj, item, lock, level = validate(puzzle, index)
        lines.append(f"Direct your attention to the {room}.")
        lines.append(lock_clue(obj, lock))
        hint = difficulty_clue(item, level)
        if hint is not None:
            lines.append(hint)
        if item == "map":
            lines.append(f"Navigation in the {room} will become easier.")
    lines.append(f"Remember, you have 60 minutes to escape the {total} puzzles.")
    return lines


def briefing(puzzles):
    header = f"=== Game Master Briefing ({len(puzzles)} rooms) ==="
    body = [f"{number:>2}. {line}" for number, line in enumerate(clues(puzzles), start=1)]
    return "\n".join([header] + body)


def main():
    rooms = [
        ("Library", "desk", "map", "combination", "hard"),
        ("Cellar", "wine rack", "silver coin", "key", "easy"),
        ("Attic", "trunk", "diary", "key", "medium"),
    ]
    print(briefing(rooms))
    hard_rooms = [room for room in rooms if room[4] == "hard"]
    print(f"Rooms flagged as hard: {len(hard_rooms)}")
    for room in hard_rooms:
        print(f"  - {room[0]} hides the {room[2]}.")
    try:
        clues([("Vault", "safe", "ruby", "fingerprint", "easy")])
    except ValueError as error:
        print(f"Rejected puzzle set: {error}")


if __name__ == "__main__":
    main()

