def _validated(index, package):
    """Unpack a package tuple, rejecting malformed records."""
    if len(package) != 5:
        raise ValueError(f"Package #{index} must have 5 fields, got {len(package)}.")
    tracking, city, weight, method, sender = package
    if weight < 0:
        raise ValueError(f"Package {tracking} has a negative weight of {weight}.")
    return tracking, city, weight, method, sender


def method_note(tracking, method):
    """Return the handling note tied to a shipping method, or None."""
    normalized = str(method).strip().lower()
    if normalized == "express":
        return f"{tracking} requires priority handling."
    if normalized == "ground":
        return f"Standard transit times apply for {tracking}."
    return None


def weight_note(weight, sender):
    """Return the note describing an unusual package weight, or None."""
    if weight > 50:
        return f"Heavy load weighing {weight} requires a team lift."
    if weight < 5:
        return f"Lightweight parcel from {sender}."
    return None


def sender_note(city, sender):
    """Flag packages coming from the Amazon retail pipeline."""
    if str(sender).strip().lower() == "amazon":
        return f"Online retail delivery for {city}."
    return None


def manifest(packages):
    lines = [f"Total packages in shipment: {len(packages)}."]
    total_weight = 0
    for index, package in enumerate(packages, start=1):
        tracking, city, weight, method, sender = _validated(index, package)
        total_weight += weight
        lines.append(f"Package {tracking} destined for {city}.")
        for note in (method_note(tracking, method),
                     weight_note(weight, sender),
                     sender_note(city, sender)):
            if note is not None:
                lines.append(note)
    lines.append(f"Total cargo weight is {total_weight} pounds.")
    return lines


def render(lines):
    """Number the manifest lines for printing on the dock sheet."""
    width = len(str(len(lines)))
    return [f"{number:>{width}}. {line}" for number, line in enumerate(lines, start=1)]


def main():
    shipment = [
        ("TRK99", "New York", 60, "express", "Acme Corp"),
        ("TRK17", "Denver", 3, "ground", "Amazon"),
        ("TRK42", "Phoenix", 24, "air", "Globex"),
    ]
    for row in render(manifest(shipment)):
        print(row)
    heaviest = max(shipment, key=lambda package: package[2])
    print(f"Heaviest package: {heaviest[0]} at {heaviest[2]} pounds.")


if __name__ == "__main__":
    main()

