def format_amount(value):
    """Render a money value without a pointless trailing .0."""
    if float(value).is_integer():
        return f"{int(value)}"
    return f"{value:.2f}"


def validate_repair(index, repair):
    """Check one raw repair record and return its five normalised fields."""
    if len(repair) != 5:
        raise ValueError(f"Repair {index} must have 5 fields, got {len(repair)}.")
    part, parts_cost, hours, rate, category = repair
    for label, number in (("parts cost", parts_cost), ("labor hours", hours), ("hourly rate", rate)):
        if number < 0:
            raise ValueError(f"Negative {label} for {part}: {number}.")
    return part, parts_cost, hours, rate, str(category).lower()


def category_notes(part, category):
    """Extra comment lines that depend on the repair category."""
    if category == "engine":
        return [f"A complex mechanical repair is needed for the {part}."]
    if category == "electrical":
        return [f"Diagnostic tools will be used on the {part}."]
    if category == "cosmetic":
        return [f"The {part} improves vehicle appearance."]
    return []


def estimate(repairs):
    lines = [f"Total repair tasks: {len(repairs)}."]
    grand_total = 0
    for index, repair in enumerate(repairs, start=1):
        part, parts_cost, hours, rate, category = validate_repair(index, repair)
        labor_cost = hours * rate
        grand_total += parts_cost + labor_cost
        lines.append(f"Part: {part}, cost: {format_amount(parts_cost)} dollars.")
        lines.extend(category_notes(part, category))
        if hours > 5:
            lines.append(f"{part} is a time consuming task requiring an overnight stay.")
        if rate > 100:
            lines.append(f"A senior mechanic is assigned to the {part}.")
    lines.append(f"Final estimated cost of all repairs is {format_amount(grand_total)} dollars.")
    return lines


def print_report(title, repairs):
    """Print a titled estimate, one numbered line per detail string."""
    print(f"=== {title} ===")
    report = estimate(repairs)
    for number, line in enumerate(report, start=1):
        print(f"{number:>2}. {line}")
    print()


def main():
    print_report("Single item job", [("Alternator", 150, 2, 120, "electrical")])
    print_report("Full workshop day", [
        ("Alternator", 150, 2, 120, "electrical"),
        ("Cylinder head", 820, 6.5, 95, "engine"),
        ("Front bumper", 310, 3, 80, "cosmetic"),
        ("Cabin filter", 24.5, 0.5, 60, "maintenance"),
    ])


if __name__ == "__main__":
    main()

