def _validate_round(index, entry):
    """Check that a single round record has the five expected fields."""
    if len(entry) != 5:
        raise ValueError(f"Round {index} must have 5 fields, got {len(entry)}.")
    name, topic, side, score, opponent = entry
    if not isinstance(score, (int, float)):
        raise TypeError(f"Round {index} has a non-numeric speaking score: {score!r}.")
    if side not in ("affirmative", "negative"):
        raise ValueError(f"Round {index} has an unknown side: {side!r}.")
    return name, topic, side, score, opponent


def describe_side(name, side, opponent):
    """Return the sentence that explains which position the debater defended."""
    if side == "affirmative":
        return f"{name} supported the resolution."
    return f"{name} opposed the resolution against {opponent}."


def describe_score(name, score):
    """Return feedback lines triggered by an unusually high or low score."""
    lines = []
    if score > 90:
        lines.append(f"Praising {name} for excellent oratory.")
    if score < 70:
        lines.append(f"{name} needs more practice.")
    return lines


def describe_round(name, topic, side, score, opponent):
    """Return every summary line produced by one judged round."""
    lines = [f"{name} argued {topic}."]
    lines.append(describe_side(name, side, opponent))
    lines.extend(describe_score(name, score))
    if topic == "healthcare":
        lines.append(f"Complex policy debate on {topic}.")
    return lines


def debate(rounds):
    """Judge a list of debate rounds and return the full list of summaries."""
    summaries = [f"Total rounds judged: {len(rounds)}."]
    best = None
    for index, entry in enumerate(rounds, start=1):
        name, topic, side, score, opponent = _validate_round(index, entry)
        summaries.extend(describe_round(name, topic, side, score, opponent))
        if best is None or score > best:
            best = score
    if best is None:
        summaries.append("Highest speaking score: none.")
    else:
        summaries.append(f"Highest speaking score: {best}.")
    return summaries


def main():
    tournament = [
        ("Alice", "healthcare", "affirmative", 95, "Bob"),
        ("Bob", "healthcare", "negative", 68, "Alice"),
        ("Carla", "trade policy", "affirmative", 82, "Dan"),
        ("Dan", "trade policy", "negative", 91, "Carla"),
    ]
    for position, line in enumerate(debate(tournament), start=1):
        print(f"{position:>2}. {line}")
    print(f"Records processed: {len(tournament)}.")


if __name__ == "__main__":
    main()

