def validate_scene(index, scene):
    """Check one raw scene tuple and return its five fields."""
    if len(scene) != 5:
        raise ValueError(f"Scene {index} must have 5 fields, got {len(scene)}.")
    name, dialogue, emotion, setting, time_of_day = scene
    if not str(name).strip():
        raise ValueError(f"Scene {index} has an empty character name.")
    if not str(dialogue).strip():
        raise ValueError(f"Scene {index} for {name} has no dialogue.")
    return str(name), str(dialogue), str(emotion).lower(), str(setting), str(time_of_day).lower()


def emotion_cue(name, emotion):
    """Return the stage direction for an emotion, or None if there is none."""
    if emotion == "angry":
        return f"{name} yells furiously."
    if emotion == "sad":
        return f"{name} wipes away a tear."
    if emotion == "happy":
        return f"{name} smiles brightly."
    return None


def script(scenes):
    """Build the full list of script lines for the given scenes."""
    lines = [f"Total scenes: {len(scenes)}."]
    for index, scene in enumerate(scenes, start=1):
        name, dialogue, emotion, setting, time_of_day = validate_scene(index, scene)
        lines.append(f"Setting: {setting}, Time: {time_of_day}.")
        lines.append(f"Character: {name}.")
        cue = emotion_cue(name, emotion)
        if cue is not None:
            lines.append(cue)
        lines.append(f"{name} says: {dialogue}")
        if time_of_day == "night":
            lines.append(f"Lighting should be dim in the {setting}.")
    lines.append(f"Script complete for {len(scenes)} scenes.")
    return lines


def speaker_tally(scenes):
    """Count how many lines each character speaks, in order of appearance."""
    tally = {}
    for index, scene in enumerate(scenes, start=1):
        name = validate_scene(index, scene)[0]
        tally[name] = tally.get(name, 0) + 1
    return tally


def cast_report(scenes):
    """Summarise the cast as one report line per character."""
    report = []
    for name, count in speaker_tally(scenes).items():
        report.append(f"{name}: {count} line(s).")
    return report


def main():
    scenes = [
        ("John", "I am leaving.", "angry", "Living Room", "night"),
        ("Mara", "Please stay a while.", "sad", "Porch", "night"),
        ("John", "The sun is up already.", "happy", "Garden", "morning"),
    ]
    for line in script(scenes):
        print(line)
    print(f"Cast size: {len(speaker_tally(scenes))}.")
    for entry in cast_report(scenes):
        print(entry)


if __name__ == "__main__":
    main()

