def _normalize(appointment, index):
    """Unpack and clean a single appointment record."""
    if len(appointment) != 5:
        raise ValueError(f"Appointment {index} must have 5 fields, got {len(appointment)}.")
    pet, animal, owner, age, reason = appointment
    if not isinstance(age, (int, float)):
        raise ValueError(f"Age for {pet} must be a number, got {age!r}.")
    if age < 0:
        raise ValueError(f"Age for {pet} cannot be negative ({age}).")
    return str(pet).strip(), str(animal).strip().lower(), str(owner).strip(), age, str(reason).strip().lower()


def _species_note(animal, pet):
    """Return the handling reminder tied to an animal type, or None."""
    if animal == "dog":
        return f"Prepare a leash for {pet}."
    if animal == "cat":
        return f"Keep the clinic quiet for {pet}."
    if animal == "bird":
        return f"Make sure the cage is secured for {pet}."
    return None


def vet(appointments):
    """Build the day's clinical notes from a list of appointment tuples."""
    notes = [f"Appointments today: {len(appointments)}."]
    total_age = 0
    for index, appointment in enumerate(appointments, start=1):
        pet, animal, owner, age, reason = _normalize(appointment, index)
        notes.append(f"{pet} belongs to {owner}.")
        reminder = _species_note(animal, pet)
        if reminder is not None:
            notes.append(reminder)
        if age < 1:
            notes.append(f"Pediatric visit for the {animal}.")
        if reason == "vaccination":
            notes.append(f"Syringes needed for {pet}.")
        total_age += age
    notes.append(f"Total age of all animals: {total_age}.")
    return notes


def summarize_species(appointments):
    """Count how many patients of each animal type are expected."""
    counts = {}
    for index, appointment in enumerate(appointments, start=1):
        animal = _normalize(appointment, index)[1]
        counts[animal] = counts.get(animal, 0) + 1
    return counts


def main():
    schedule = [
        ("Rex", "dog", "Alice", 0, "vaccination"),
        ("Misty", "Cat", "Bob", 4, "dental cleaning"),
        ("Kiwi", "bird", "Chen", 2, "Vaccination"),
        ("Nibbles", "rabbit", "Dana", 0.5, "check-up"),
    ]
    for note in vet(schedule):
        print(note)
    print("-" * 30)
    for animal, count in sorted(summarize_species(schedule).items()):
        print(f"{animal}: {count} patient(s)")
    try:
        vet([("Ghost", "dog", "Eve", -2, "check-up")])
    except ValueError as error:
        print(f"Rejected record: {error}")


if __name__ == "__main__":
    main()

