def _heal(actor, target, ability, damage):
    return f"{actor} channeled {ability} on {target}, restoring {damage} health."


def _block(actor, target, ability, damage):
    return f"{actor} raised a guard and blocked {target}'s {ability}, absorbing {damage} damage."


def _dodge(actor, target, ability, damage):
    return f"{actor} slipped aside as {target}'s {ability} whistled past, avoiding {damage} damage."


def _critical(actor, target, ability, damage):
    return f"{actor} critically struck {target} with {ability} for a devastating {damage} damage!"


def _parry(actor, target, ability, damage):
    return f"{actor} parried {target}'s {ability}, turning {damage} damage back into a stalemate."


def _miss(actor, target, ability, damage):
    return f"{actor} swung {ability} at {target} but missed, landing none of the {damage} damage."


def _counter(actor, target, ability, damage):
    return f"{actor} countered {target} with {ability}, punishing the opening for {damage} damage."


