        return "crystal clear"
    if distance >= 15:
        return "good"
    if distance >= 7:
        return "moderate"
    return "murky"


def classify_profile(depth):
    if depth >= 30:
        return "deep"
    if depth >= 18:
        return "intermediate"
    return "shallow"


def list_creatures(creatures):
    if len(creatures) == 1:
        return creatures[0]
    return f"{', '.join(creatures[:-1])} and {creatures[-1]}"


def validate(dive):
    required = ("diver", "site", "depth", "time", "temp", "visibility", "gas", "marine_life")
    for field in required:
        if field not in dive:
            raise KeyError(f"dive record is missing the field '{field}'")
    if dive["time"] <= 0:
        raise ValueError(f"bottom time must be positive, got {dive['time']}")
    if dive["depth"] <= 0:
        raise ValueError(f"maximum depth must be positive, got {dive['depth']}")


def dive_entry(dive):
    validate(dive)
    depth = dive["depth"]
    bottom_time = dive["time"]
    lines = [f"{dive['diver']} dived at {dive['site']}."]
    lines.append(f"The maximum depth reached was {depth}m.")
    lines.append(f"The total bottom time was {bottom_time} minutes.")
