REQUIRED_FIELDS = (
    "name",
    "attending",
    "meal",
    "plus_one",
    "song",
    "arrival",
    "hotel",
    "gift",
)


def _clean_name(raw):
    return " ".join(part.capitalize() for part in str(raw).split())


def _check_record(record, position):
    missing = [field for field in REQUIRED_FIELDS if field not in record]
    if missing:
        raise KeyError("guest #{} is missing fields: {}".format(position, ', '.join(missing)))
    if not str(record["name"]).strip():
        raise ValueError("guest #{} has an empty name".format(position))


def format_arrival(value):
    text = str(value).strip()
    if ":" not in text:
        return "an unspecified time ({})".format(text)
    hours, minutes = text.split(":", 1)
    hour = int(hours)
    minute = int(minutes)
    suffix = "AM" if hour < 12 else "PM"
    display = hour % 12 or 12
    return "{}:{:02d} {}".format(display, minute, suffix)


def describe_plus_one(plus_one):
    if not str(plus_one).strip() or str(plus_one).strip().lower() == "none":
        return "coming solo, with no plus one registered"
    return "bringing {} along as their plus one".format(_clean_name(plus_one))


def describe_gift(gift):
    state = str(gift).strip().lower()
    if state in ("yes", "sent", "received", "true"):
        return "has already sent a gift, which we gratefully acknowledge"
    return "has not sent a gift yet (status: {})".format(state or 'unknown')


def guest_lines(record, position):
    _check_record(record, position)
    name = _clean_name(record["name"])
    lines = ["Welcome the esteemed {}.".format(name)]
    lines.append("They confirmed their attendance status as {}.".format(record['attending']))
    lines.append("Their meal choice is {}.".format(record['meal']))
    lines.append("{} is {}.".format(name, describe_plus_one(record['plus_one'])))
    lines.append("The song they requested for the reception is \"{}\".".format(record['song']))
    lines.append("We expect them to arrive at {}.".format(format_arrival(record['arrival'])))
    lines.append("Their overnight stay is booked at the {}.".format(record['hotel']))
    lines.append("Finally, {} {}.".format(name, describe_gift(record['gift'])))
    return lines


def rsvp(guests):
    return [guest_lines(record, index) for index, record in enumerate(guests, start=1)]


def main():
    party = [
        {
            "name": "john doe",
            "attending": "attending",
            "meal": "chicken",
            "plus_one": "jane doe",
            "song": "Dancing Queen",
            "arrival": "17:45",
            "hotel": "Grand Riverside Inn",
            "gift": "sent",
        },
        {
            "name": "amara okafor",
