            "plus_one": "none",
            "song": "September",
            "arrival": "20:05",
            "hotel": "Lakeview Lodge",
            "gift": "pending",
        },
    ]
    for number, lines in enumerate(rsvp(party), start=1):
        print("--- Guest {} ---".format(number))
        for line in lines:
            print(line)
        print()


if __name__ == "__main__":
    main()

