    for field in REQUIRED_FIELDS:
        if field not in trade:
            raise KeyError(f"trade #{index} is missing the '{field}' field")
        if not str(trade[field]).strip():
            raise ValueError(f"trade #{index} has an empty '{field}' field")


def describe(trade):
    one = str(trade["team_one"]).strip()
    two = str(trade["team_two"]).strip()
    player = str(trade["player"]).strip()
    status = str(trade["status"]).strip().lower()

    if status == "accepted":
        return f"{one} successfully acquired {player} from {two}."
    if status == "rejected":
        return f"{one} refused to trade {player} to {two}."
    if status == "vetoed":
        return f"The league office vetoed the transfer of {player} between {one} and {two}."
    if status == "pending":
        return f"{one} is still waiting for {two} to respond about {player}."
    if status == "countered":
        return f"{two} countered the offer for {player} with a proposal of their own to {one}."
    if status == "processing":
        return f"The move sending {player} from {two} to {one} is being processed."
    if status == "failed":
        return f"The trade for {player} between {one} and {two} failed to go through."
    if status == "completed":
        return f"{player} has officially joined {one} and is off the {two} roster."
    raise ValueError(f"unknown trade status '{status}' for player {player}")


def evaluate(trades):
    sentences = []
    for index, trade in enumerate(trades, start=1):
        _validate(trade, index)
        sentences.append(describe(trade))
