text_nat:
def format_bearing(bearing):
    """Normalize a bearing to the three-digit form used in sonar traffic."""
    degrees = int(round(float(bearing))) % 360
    return f"{degrees:03d}"


def format_range(distance):
    """Render a range in yards, switching to kiloyards past 2000 yards."""
    yards = float(distance)
    if yards >= 2000:
        return f"{yards / 1000:.1f} kiloyards"
    return f"{int(round(yards))} yards"


def format_speed(speed):
    return f"{float(speed):.1f} knots"


def describe(contact):
    """Build the one-line report for a single sonar contact."""
    track = contact["track"]
    bearing = format_bearing(contact["bearing"])
    distance = format_range(contact["range"])
    speed = format_speed(contact["speed"])
    kind = str(contact["classification"]).strip().lower()

    if kind == "biological":
        return f"Track {track} is marine life drifting at {bearing}, {distance} out."
    if kind == "friendly":
        return f"Track {track} squawks friendly at {bearing}, holding station {distance} away."
    if kind == "hostile":
        return f"Track {track} is a confirmed hostile target at {bearing} closing at {speed}."
    if kind == "unknown":
        return f"Track {track} remains unidentified at {bearing}, {distance}, making {speed}."
    if kind == "merchant":
        return f"Track {track} plods along as a merchant at {bearing}, {distance} distant."
    if kind == "anomaly":
        return f"Track {track} registers an acoustic anomaly at {bearing} with no solution at {distance}."
    if kind == "torpedo":
        return f"Track {track} is an inbound torpedo at {bearing}, running {speed}."
    if kind == "decoy":
        return f"Track {track} is a decoy at {bearing}, spoofing at {speed}."
    raise ValueError(f"unrecognized classification {kind!r} on track {track}")


def sonar(contacts):
    """Return a formatted report line for every sonar contact."""
    return [describe(contact) for contact in contacts]


def main():
    contacts = [
        {"track": 11, "bearing": 5, "range": 8400, "classification": "biological", "speed": 3},
        {"track": 18, "bearing": 275, "range": 12000, "classification": "friendly", "speed": 12},
        {"track": 23, "bearing": 133, "range": 9500, "classification": "hostile", "speed": 22},
