def format_bearing(bearing):
    """Normalize a bearing to the three-digit form used in sonar traffic."""
    degrees = int(round(float(bearing))) % 360
    return "{:03d}".format(degrees)


def format_range(distance):
    """Render a range in yards, switching to kiloyards past 2000 yards."""
    yards = float(distance)
    if yards >= 2000:
        return "{:.1f} kiloyards".format(yards / 1000)
    return "{} yards".format(int(round(yards)))


def format_speed(speed):
    return "{:.1f} knots".format(float(speed))


def describe(contact):
    """Build the one-line report for a single sonar contact."""
    track = contact["track"]
    bearing = format_bearing(contact["bearing"])
    distance = format_range(contact["range"])
    speed = format_speed(contact["speed"])
    kind = str(contact["classification"]).strip().lower()

    if kind == "biological":
        return "Track {} is marine life drifting at {}, {} out.".format(track, bearing, distance)
    if kind == "friendly":
        return "Track {} squawks friendly at {}, holding station {} away.".format(track, bearing, distance)
    if kind == "hostile":
        return "Track {} is a confirmed hostile target at {} closing at {}.".format(track, bearing, speed)
    if kind == "unknown":
        return "Track {} remains unidentified at {}, {}, making {}.".format(track, bearing, distance, speed)
    if kind == "merchant":
        return "Track {} plods along as a merchant at {}, {} distant.".format(track, bearing, distance)
    if kind == "anomaly":
        return "Track {} registers an acoustic anomaly at {} with no solution at {}.".format(track, bearing, distance)
    if kind == "torpedo":
        return "Track {} is an inbound torpedo at {}, running {}.".format(track, bearing, speed)
    if kind == "decoy":
        return "Track {} is a decoy at {}, spoofing at {}.".format(track, bearing, speed)
    raise ValueError("unrecognized classification {!r} on track {}".format(kind, track))


def sonar(contacts):
    """Return a formatted report line for every sonar contact."""
    return [describe(contact) for contact in contacts]


