    "speed_one",
    "speed_two",
)


def _validate(record, index):
    for field in REQUIRED_FIELDS:
        if field not in record:
            raise KeyError("accident record {} is missing the field '{}'".format(index, field))
    for field in ("speed_one", "speed_two"):
        value = record[field]
        if not isinstance(value, (int, float)):
            raise TypeError("accident record {} has a non-numeric '{}': {!r}".format(index, field, value))
        if value < 0:
            raise ValueError("accident record {} has a negative '{}': {}".format(index, field, value))


def _speed_text(speed):
    if float(speed).is_integer():
        return "{} mph".format(int(speed))
    return "{:.1f} mph".format(speed)


def _severity(difference):
    if difference >= 30:
        return "a high-energy impact"
    if difference >= 10:
        return "a moderate-energy impact"
    return "a low-energy impact"


def reconstruct(accidents):
    logs = []
    for index, record in enumerate(accidents, start=1):
        _validate(record, index)
        highway = record["highway"]
        vehicle_one = record["vehicle_one"]
        vehicle_two = record["vehicle_two"]
        difference = abs(record["speed_one"] - record["speed_two"])
        gap = "a gap of {} that suggests {}".format(_speed_text(difference), _severity(difference))
        sentences = [
            "Report ID {} covers an incident on {}.".format(record['report_id'], highway),
            "The collision was recorded at mile marker {}.".format(record['mile_marker']),
            "Responders reached the scene by travelling along {}.".format(highway),
            "The weather condition was {}.".format(record['weather']),
            "The first involved vehicle was a {}.".format(vehicle_one),
            "The second involved vehicle was a {}.".format(vehicle_two),
            "The {} was moving at an estimated {}.".format(vehicle_one, _speed_text(record['speed_one'])),
            "The {} approached at {}, {}.".format(vehicle_two, _speed_text(record['speed_two']), gap),
        ]
        logs.append(sentences)
    return logs


