    if missing:
        joined = ", ".join(missing)
        raise KeyError("Donation #{} is missing the fields: {}".format(index, joined))


def _format_amount(amount, index):
    try:
        value = float(amount)
    except (TypeError, ValueError):
        raise ValueError("Donation #{} has a non-numeric amount: {!r}".format(index, amount))
    if value <= 0:
        raise ValueError("Donation #{} must be a positive amount, got {:g}".format(index, value))
    if value == int(value):
        return "{}".format(int(value))
    return "{:.2f}".format(value)


def build_letter(donation, index):
