)


def validate(record, index):
    missing = [field for field in REQUIRED_FIELDS if field not in record]
    if missing:
        joined = ", ".join(missing)
        raise KeyError("athlete #{} is missing fields: {}".format(index, joined))
    return record


def format_time(seconds):
    if seconds >= 60:
        minutes, rest = divmod(seconds, 60)
        return "{}m {}s".format(minutes, rest)
    return "{}s".format(seconds)


def ordinal(rank):
    if 10 <= rank % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(rank % 10, "th")
    return "{}{}".format(rank, suffix)


def describe_penalty(penalty):
    if penalty:
        return "a penalty of {} was applied".format(penalty)
    return "no penalty was applied"


def announce(record):
    lines = ["Introducing {} competing in the {} event.".format(record['name'], record['event'])]
    lines.append("The clocked completion time is {}.".format(format_time(record['time'])))
    lines.append("The verified repetitions completed is {}.".format(record['reps']))
    lines.append("The heaviest weight lifted is {} kg.".format(record['weight']))
    pace = record["reps"] / record["time"] * 60
    lines.append("That pace works out to {:.1f} repetitions per minute.".format(pace))
    lines.append("Judge {} signed off on the attempt.".format(record['judge']))
    lines.append("On review, {}.".format(describe_penalty(record['penalty'])))
    lines.append("{} finishes in {} place.".format(record['name'], ordinal(record['rank'])))
    return lines


def score(athletes):
    return [announce(validate(record, i)) for i, record in enumerate(athletes, 1)]


