def table_rule(minimum):
    return f"This table has a minimum bet of ${minimum}."


def wager(bet):
    return f"Your wager of ${bet} is confirmed and on the felt."


def player_status(player_total):
    return f"You are showing {player_total}."


def dealer_reveal(dealer_total):
    return f"The dealer reveals a total of {dealer_total}."


def multiplier(factor, payout):
    return f"A bonus multiplier of {factor}x brings your payout to ${payout}."


def service(drink):
    return f"Please enjoy a complimentary {drink} while you play."


def farewell(player, drink):
    return f"Good luck, {player}, and may that {drink} bring you cards!"


def parse_round(entry):
    player, minimum, bet, player_total, dealer_total, factor, drink = entry
    if bet < minimum:
        raise ValueError(f"{player} bet ${bet}, below the ${minimum} table minimum")
    if factor <= 0:
        raise ValueError(f"{player} has an invalid bonus multiplier of {factor}")
    return player, minimum, bet, player_total, dealer_total, factor, drink


def settle(bet, player_total, dealer_total, factor):
    if player_total > 21:
        return 0
    if dealer_total > 21 or player_total > dealer_total:
        return round(bet * 2 * factor, 2)
    if player_total == dealer_total:
        return round(bet * factor, 2)
    return 0


def deal(rounds):
    monologues = []
    for entry in rounds:
        player, minimum, bet, player_total, dealer_total, factor, drink = parse_round(entry)
        payout = settle(bet, player_total, dealer_total, factor)
        phrases = [
            greeting(player),
            table_rule(minimum),
            wager(bet),
            player_status(player_total),
            dealer_reveal(dealer_total),
            multiplier(factor, payout),
            service(drink),
            farewell(player, drink),
        ]
        monologues.append(" ".join(phrases))
    return monologues


def main():
    rounds = [
        ("Ada", 25, 50, 20, 18, 1.5, "espresso"),
        ("Grace", 25, 25, 17, 21, 2, "lemonade"),
        ("Linus", 10, 100, 19, 19, 1, "iced tea"),
    ]
    for index, monologue in enumerate(deal(rounds), start=1):
