    return f"In English, this shape is known as {pose['english']}."

def breathing_cue(pose):
    return f"Settle the rhythm of your {pose['breath']} before you deepen the shape."

def timing_cue(pose):
    seconds = pose['hold']
    if seconds >= 60:
        minutes = seconds / 60
        span = f"{minutes:.1f} minutes"
    else:
        span = f"{seconds} seconds"
    return f"Stay here for {span}."

def concentration_cue(pose):
    return f"Let your gaze rest softly on {pose['focus']}."

def physical_cue(pose):
    return f"Feel the work gather in your {pose['muscles']}."

def movement_cue(pose):
    return f"When you are ready, prepare to flow into {pose['transition']}."

def encouragement_cue(pose):
    return f"Trust your {pose['breath']} and your {pose['focus']} will hold you steady."

def validate(pose, index):
    required = ('sanskrit', 'english', 'breath', 'hold', 'focus', 'muscles', 'transition')
    for key in required:
        if key not in pose:
            raise KeyError(f"Pose {index} is missing the '{key}' detail.")
    if not isinstance(pose['hold'], (int, float)) or pose['hold'] <= 0:
        raise ValueError(f"Pose {index} has an invalid hold duration: {pose['hold']!r}")

def instruct(poses):
    builders = (naming_cue, translation_cue, breathing_cue, timing_cue,
                concentration_cue, physical_cue, movement_cue, encouragement_cue)
    script = []
    for index, pose in enumerate(poses, start=1):
        validate(pose, index)
        cues = " ".join(build(pose) for build in builders)
        script.append(f"Pose {index}: {cues}")
    return script

def summarize(poses):
    total = sum(pose['hold'] for pose in poses)
    minutes = math.ceil(total / 60)
    return f"{len(poses)} poses, roughly {minutes} minute(s) of holding."

def main():
    sequence = [
        {'sanskrit': 'Tadasana', 'english': 'Mountain Pose', 'breath': 'ujjayi breath',
