FIELDS = ("landmark", "paces", "direction", "terrain", "hazard", "tool", "marker")


def starting_sentence(landmark):
    return f"Begin your journey at {landmark}."


def distance_sentence(paces):
    return f"From there, count out exactly {paces} paces."


def heading_sentence(direction):
    return f"Keep your compass needle pointing {direction} the whole way."


def landscape_sentence(terrain):
    return f"The ground underfoot turns to {terrain}."


def danger_sentence(hazard):
    return f"Beware: {hazard} has claimed travellers before you."


def equipment_sentence(tool):
    return f"You will get no further without {tool}."


def discovery_sentence(marker):
    return f"Look closely and you will spot {marker}."


def confirmation_sentence(paces, landmark):
    return f"If you have walked {paces} paces from {landmark}, you are on course."


def parse_step(step, index):
    if isinstance(step, dict):
        missing = [name for name in FIELDS if name not in step]
        if missing:
            raise ValueError(f"step {index} is missing fields: {', '.join(missing)}")
        return {name: step[name] for name in FIELDS}
    values = list(step)
    if len(values) != len(FIELDS):
        raise ValueError(f"step {index} has {len(values)} fields, expected {len(FIELDS)}")
    return dict(zip(FIELDS, values))


def navigate(steps):
    paragraphs = []
    for index, raw in enumerate(steps, start=1):
        leg = parse_step(raw, index)
        sentences = [
            starting_sentence(leg["landmark"]),
            distance_sentence(leg["paces"]),
            heading_sentence(leg["direction"]),
            landscape_sentence(leg["terrain"]),
            danger_sentence(leg["hazard"]),
            equipment_sentence(leg["tool"]),
            discovery_sentence(leg["marker"]),
            confirmation_sentence(leg["paces"], leg["landmark"]),
        ]
        paragraphs.append(" ".join(sentences))
    return paragraphs


def main():
    route = [
        ("the Cracked Lighthouse", 240, "north-east", "loose shale",
         "the tide pool sinkhole", "a coil of rope", "a gull carved into stone"),
        {"landmark": "the Whispering Pines", "paces": 512, "direction": "due south",
         "terrain": "peat bog", "hazard": "the adder nest", "tool": "an iron-shod staff",
         "marker": "a cairn topped with quartz"},
    ]
    paragraphs = navigate(route)
    for number, paragraph in enumerate(paragraphs, start=1):
        print(f"Leg {number} of {len(paragraphs)}")
        print(paragraph)
        print()
    print(f"Map complete: {len(paragraphs)} legs charted to the treasure.")


if __name__ == "__main__":
    main()

