def normalize(profile):
    required = ("name", "age", "profession", "hobby", "cuisine", "weekend", "pet")
    missing = [key for key in required if not profile.get(key)]
    if missing:
        raise ValueError(f"Profile is missing required fields: {', '.join(missing)}")
    age = profile["age"]
    if not isinstance(age, int) or age < 18:
        raise ValueError(f"Invalid age for {profile['name']}: {age}")
