def _format_duration(minutes):
    hours, mins = divmod(int(minutes), 60)
    if hours and mins:
        return f"{hours} hours and {mins} minutes"
    if hours:
        return f"{hours} hours"
    return f"{mins} minutes"


def destination_sentence(city):
    return f"Ladies and gentlemen, welcome aboard this flight to {city}."


def elevation_sentence(altitude):
    return f"We will be cruising at an altitude of {altitude:,} feet."


def time_sentence(duration_minutes):
    spoken = _format_duration(duration_minutes)
    return f"Our estimated flight time today is {spoken}."


def comfort_sentence(turbulence):
    return f"We are expecting {turbulence} turbulence, so please keep your seat belt fastened."


def meteorological_sentence(weather):
    return f"The weather at our destination is currently {weather}."


def terminal_sentence(gate):
    return f"We are scheduled to arrive at gate {gate}."


def transfer_sentence(connection):
    return f"Passengers continuing on to {connection} may remain seated until we reach the terminal."


def signoff_sentence(city, altitude):
    return f"Thank you for flying with us to {city} at {altitude:,} feet; enjoy the journey."


def _require(flight, key):
    value = flight.get(key)
    if value is None:
        raise ValueError(f"Flight record is missing the required field '{key}'.")
    return value


def broadcast(flights):
    announcements = []
    for index, flight in enumerate(flights, start=1):
        city = _require(flight, "destination")
        altitude = _require(flight, "altitude")
        duration = _require(flight, "duration")
        if duration <= 0:
            raise ValueError(f"Flight {index} to {city} has a non-positive duration.")
        sentences = [
            destination_sentence(city),
            elevation_sentence(altitude),
            time_sentence(duration),
            comfort_sentence(_require(flight, "turbulence")),
            meteorological_sentence(_require(flight, "weather")),
            terminal_sentence(_require(flight, "gate")),
            transfer_sentence(_require(flight, "connection")),
            signoff_sentence(city, altitude),
        ]
        announcements.append(" ".join(sentences))
    return announcements


def main():
    flights = [
        {
            "destination": "Reykjavik",
            "altitude": 36000,
            "duration": 305,
            "turbulence": "light",
            "weather": "overcast with light snow",
            "gate": "C14",
            "connection": "Oslo",
        },
        {
            "destination": "Lisbon",
            "altitude": 38500,
            "duration": 60,
            "turbulence": "moderate",
            "weather": "sunny and mild",
            "gate": "A3",
            "connection": "Casablanca",
        },
    ]
    for number, text in enumerate(broadcast(flights), start=1):
        print(f"--- Announcement {number} ---")
        print(text)


if __name__ == "__main__":
    main()

