def money(amount):
    """Format a monetary amount as a spoken-friendly string."""
    if amount >= 1_000_000:
        millions = amount / 1_000_000
        if millions == int(millions):
            return f"{int(millions)} million pounds"
        return f"{millions:.1f} million pounds"
    if amount >= 1_000:
        return f"{amount:,} pounds"
    return f"{amount} pounds"


def winners_phrase(count):
    """Describe how many ticket holders matched the numbers."""
    if count == 0:
        return "nobody matched tonight's numbers"
    if count == 1:
        return "a single lucky ticket holder matched tonight's numbers"
    return f"{count} lucky ticket holders matched tonight's numbers"


def share_phrase(jackpot, count):
    """Describe the per-winner share of the jackpot."""
    if count <= 1:
        return "the whole jackpot goes home tonight"
    share = jackpot // count
    return f"that is {money(share)} each"


def validate(results):
    """Check the broadcast tuple before the host reads from it."""
    if len(results) != 8:
        raise ValueError(f"expected 8 result values, got {len(results)}")
    jackpot, first, second, bonus, winners, date, estimate, charity = results
    for label, ball in (("first", first), ("second", second), ("bonus", bonus)):
        if not 1 <= ball <= 49:
            raise ValueError(f"{label} ball {ball} is outside the 1-49 range")
    if winners < 0:
        raise ValueError(f"winner count cannot be negative: {winners}")
    for label, amount in (("jackpot", jackpot), ("estimate", estimate), ("charity", charity)):
        if amount < 0:
            raise ValueError(f"{label} amount cannot be negative: {amount}")
    if not str(date).strip():
        raise ValueError("next draw date must not be blank")


def draw(results):
    """Return the eight spoken lines of the live lottery broadcast."""
    validate(results)
    jackpot, first, second, bonus, winners, date, estimate, charity = results
    lines = [
        f"Good evening, and welcome to tonight's draw for {money(jackpot)}!",
        f"And the first ball out of the machine is number {first}.",
        f"Following it, the second ball is number {second}.",
        f"And tonight's bonus ball is number {bonus}.",
        f"After checking the tickets, {winners_phrase(winners)}.",
    ]
    lines.append(f"Our next draw takes place on {date}, so do not miss it.")
    lines.append(f"The estimated jackpot for that draw stands at {money(estimate)}.")
    lines.append(f"And thanks to all of you, {money(charity)} has been raised for good causes.")
    return lines


def main():
    results = (10_000_000, 7, 14, 42, 3, "Saturday", 12_000_000, 500_000)
    for number, line in enumerate(draw(results), start=1):
        print(f"{number}. {line}")
    print(share_phrase(results[0], results[4]).capitalize() + ".")


if __name__ == "__main__":
