def reverse_string(s):
    """Return the characters of s in reverse order."""
    if not isinstance(s, str):
        raise TypeError(f"expected a string, got {type(s).__name__}")
    return s[::-1]


def is_palindrome(s):
    """Report whether s reads the same forwards and backwards."""
    cleaned = "".join(ch.lower() for ch in s if ch.isalnum())
    return cleaned == reverse_string(cleaned)


def reverse_words(sentence):
    """Reverse each word of a sentence while keeping the word order."""
    return " ".join(reverse_string(word) for word in sentence.split())


def describe(s):
    """Build a one-line description of a string and its reversal."""
    reversed_s = reverse_string(s)
    line = f"{s!r} -> {reversed_s!r}"
    if is_palindrome(s):
        return f"{line} (palindrome)"
    return line


def build_report(samples):
    """Return a multi-line report describing every sample string."""
    width = max((len(sample) for sample in samples), default=0)
    lines = [f"Reversing {len(samples)} sample(s), longest is {width} chars"]
    for index, sample in enumerate(samples, start=1):
        lines.append(f"{index:>3}. {describe(sample)}")
    return "\n".join(lines)


def main(argv):
    samples = argv[1:]
    if not samples:
        samples = ["hello", "Python", "racecar", "A man, a plan, a canal: Panama"]
