def simple_calculator(num1, operator, num2):
    """
    Performs basic arithmetic operations (+, -, *, /) on two numbers.
    Handles division by zero by returning 'Error'.
    """
    if operator == '+':
        result = num1 + num2
        return "The sum of {} and {} is {}.".format(num1, num2, result)
    elif operator == '-':
        result = num1 - num2
        return "The difference between {} and {} is {}.".format(num1, num2, result)
    elif operator == '*':
        result = num1 * num2
        return "The product of {} and {} is {}.".format(num1, num2, result)
    elif operator == '/':
        if num2 == 0:
            return "Error: Cannot divide {} by zero.".format(num1)
        result = num1 / num2
        return "The quotient of {} divided by {} is {}.".format(num1, num2, result)
    else:
        return "Error: Invalid operator '{}'. Please use +, -, *, or /.".format(operator)

