def validate_email(email):
    """Return True if email has a basic valid format: '@' before a '.'."""
    if not isinstance(email, str):
        raise TypeError(f"expected a string, got {type(email).__name__}")
    stripped = email.strip()
    if "@" not in stripped or "." not in stripped:
        return False
    at_index = stripped.index("@")
    dot_index = stripped.rindex(".")
    return at_index < dot_index


def split_email(email):
    """Return (local, domain) for an address that passes validate_email."""
    if not validate_email(email):
        raise ValueError(f"cannot split invalid address: {email!r}")
    local, _, domain = email.strip().partition("@")
    return local, domain


def describe_email(email):
    """Build a human readable one-line description of an address."""
    if not validate_email(email):
        return f"{email!r} -> invalid (needs '@' before a '.')"
    local, domain = split_email(email)
    tld = domain.rsplit(".", 1)[1]
    return f"{email!r} -> valid (user={local}, domain={domain}, tld={tld})"


def group_by_domain(emails):
    """Map each valid address' domain to the list of local parts using it."""
    groups = {}
    for email in emails:
        if validate_email(email):
            local, domain = split_email(email)
            groups.setdefault(domain.lower(), []).append(local)
    return groups


def summarize(emails):
    """Return a multi-line report about a batch of candidate addresses."""
    lines = [describe_email(email) for email in emails]
    valid = [e for e in emails if validate_email(e)]
    total = len(emails)
    lines.append(f"checked {total} address(es), {len(valid)} valid, {total - len(valid)} invalid")
    for domain, locals_ in sorted(group_by_domain(valid).items()):
        users = ", ".join(sorted(locals_))
        lines.append(f"  {domain}: {len(locals_)} user(s) [{users}]")
    return "\n".join(lines)


def main():
    candidates = [
        "test@example.com",
        "invalid-email",
        "  spaced@example.com  ",
        "admin@EXAMPLE.com",
        "dot.before@at",
        "no.at.sign.com",
        "user@sub.domain.org",
    ]
    print(summarize(candidates))
    try:
        validate_email(42)
    except TypeError as exc:
        print(f"rejected non-string input: {exc}")
    first_valid = next(e for e in candidates if validate_email(e))
    print(f"first usable address in the batch: {first_valid.strip()}")


if __name__ == "__main__":
    main()

