import math


def validate_numbers(numbers):
    """Return the input as a list of floats, rejecting anything non-positive."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError(f"expected a list or tuple of numbers, got {type(numbers).__name__}")
    if len(numbers) == 0:
        raise ValueError("geometric mean is undefined for an empty sequence")
    values = []
    for index, item in enumerate(numbers):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"item at index {index} is not a real number: {item!r}")
        value = float(item)
        if value <= 0.0:
            raise ValueError(f"item at index {index} must be positive, got {value}")
        values.append(value)
    return values


def geometric_mean(numbers):
    """Nth root of the product of N positive numbers, computed via logarithms."""
    values = validate_numbers(numbers)
    log_sum = math.fsum(math.log(value) for value in values)
    return math.exp(log_sum / len(values))


def arithmetic_mean(numbers):
    values = validate_numbers(numbers)
    return math.fsum(values) / len(values)


def harmonic_mean(numbers):
    values = validate_numbers(numbers)
    return len(values) / math.fsum(1.0 / value for value in values)


def format_mean(label, value):
    return f"{label:>16}: {value:.6f}"


def describe(numbers):
    """Build a multi-line report comparing the three Pythagorean means."""
    joined = ", ".join(f"{float(value):g}" for value in numbers)
    lines = [f"sample ({len(numbers)} values): [{joined}]"]
    geo = geometric_mean(numbers)
    ari = arithmetic_mean(numbers)
    har = harmonic_mean(numbers)
    lines.append(format_mean("arithmetic mean", ari))
    lines.append(format_mean("geometric mean", geo))
    lines.append(format_mean("harmonic mean", har))
    spread = ari - har
    lines.append(f"{'spread (A - H)':>16}: {spread:.6f}")
    if math.isclose(geo, ari, rel_tol=1e-12):
        lines.append("all values are equal, so the three means coincide")
    else:
        ratio = geo / ari
        lines.append(f"geometric / arithmetic ratio = {ratio:.4f}")
    return "\n".join(lines)


def main():
    samples = [
        [2, 8],
        [1, 1, 1],
        [4, 1, 1 / 32],
        [1.5, 2.5, 10, 40],
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)

    growth = [1.05, 1.12, 0.97, 1.21]
    average_factor = geometric_mean(growth)
    percent = (average_factor - 1.0) * 100.0
    print(f"average yearly growth over {len(growth)} years: {percent:+.2f}%")

    for bad in ([], [3, -1], "12"):
        try:
            geometric_mean(bad)
        except (TypeError, ValueError) as error:
            print(f"rejected {bad!r}: {error}")


if __name__ == "__main__":
    main()

