def simulate_queue(operations):
    queue = []
    print(f"Starting simulation with queue: {queue}")
    for i, op_tuple in enumerate(operations):
        operation_type = op_tuple[0]
        print(f"Processing operation {i+1}: {operation_type}")
        if operation_type == 'enqueue':
            item = op_tuple[1]
            queue.append(item)
            print(f"Enqueued item: {item}")
            print(f"Current queue state: {queue}")
        elif operation_type == 'dequeue':
            if queue:
                dequeued_item = queue.pop(0)
                print(f"Dequeued item: {dequeued_item}")
            else:
                print(f"Dequeue attempted on empty queue.")
            print(f"Current queue state: {queue}")
        else:
            print(f"Unknown operation type: {operation_type}")
    print(f"Simulation finished.")
    print(f"Final queue state: {queue}")
    return queue

