def validate_size(n):
    """Return n as a positive int, raising a clear error otherwise."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(f"table size must be an int, got {type(n).__name__}")
    if n < 1:
        raise ValueError(f"table size must be at least 1, got {n}")
    return n


def build_table(n):
    """Return the n x n multiplication table as a list of lists."""
    return [[row * col for col in range(1, n + 1)] for row in range(1, n + 1)]


def format_row(row, width):
    """Render one table row with every cell right-aligned to width."""
    return " ".join(f"{value:>{width}}" for value in row)


def format_table(table):
    """Render the whole table as a list of aligned text lines."""
    if not table:
        return []
    width = len(str(table[-1][-1]))
    header_cells = format_row(range(1, len(table) + 1), width)
    header = f"{'x':>{width}} | {header_cells}"
    lines = [header, "-" * len(header)]
    for index, row in enumerate(table, start=1):
        label = f"{index:>{width}}"
        lines.append(f"{label} | {format_row(row, width)}")
    return lines


def multiplication_table(n):
    """Print the multiplication table up to n x n and return it."""
    size = validate_size(n)
    table = build_table(size)
    for line in format_table(table):
