def flatten_list(list_of_lists):
    """Return a single list containing every element of the given sublists."""
    if not isinstance(list_of_lists, (list, tuple)):
        raise TypeError(f"expected a list of lists, got {type(list_of_lists).__name__}")
    flat = []
    for index, sublist in enumerate(list_of_lists):
        if not isinstance(sublist, (list, tuple)):
            raise TypeError(f"element at position {index} is not a list: {sublist!r}")
        flat.extend(sublist)
    return flat


def flatten_deep(nested):
    """Flatten a structure of arbitrarily nested lists into one flat list."""
    flat = []
    for item in nested:
        if isinstance(item, (list, tuple)):
            flat.extend(flatten_deep(item))
        else:
            flat.append(item)
    return flat


def describe_shape(list_of_lists):
    """Build a human readable summary of the sublist lengths."""
    parts = [f"{len(sublist)}" for sublist in list_of_lists]
    joined = " + ".join(parts) if parts else "0"
    total = sum(len(sublist) for sublist in list_of_lists)
    return f"{joined} = {total}"


def parse_nested(text):
    """Parse a string like '1,2 | 3,4,5' into a list of lists of integers."""
    groups = []
    for chunk in text.split("|"):
        chunk = chunk.strip()
        if not chunk:
            groups.append([])
            continue
        numbers = []
        for token in chunk.split(","):
            token = token.strip()
            if not token.lstrip("-").isdigit():
                raise ValueError(f"{token!r} is not a valid integer")
            numbers.append(int(token))
        groups.append(numbers)
    return groups


def report(text):
    """Parse a specification, flatten it and return a multi-line report."""
    groups = parse_nested(text)
    flat = flatten_list(groups)
    lines = [f"input      : {text}"]
    lines.append(f"sublists   : {len(groups)}")
    lines.append(f"shape      : {describe_shape(groups)}")
    lines.append(f"flattened  : {flat}")
    if flat:
        lines.append(f"sum/min/max: {sum(flat)} / {min(flat)} / {max(flat)}")
    return "\n".join(lines)


def main():
    specs = ["1,2 | 3,4,5", "", "7 | -8,9 | 10,11,12"]
    for spec in specs:
        print(report(spec))
        print("-" * 32)
    deep = [1, [2, [3, [4, 5]]], 6]
    print(f"deep {deep} -> {flatten_deep(deep)}")


if __name__ == "__main__":
    main()

