def reverse_words(sentence):
    """Reverse the order of the words in a sentence, keeping each word intact."""
    if not isinstance(sentence, str):
        raise TypeError(f"sentence must be a str, got {type(sentence).__name__}")
    words = sentence.split()
    return " ".join(reversed(words))


def word_count(sentence):
    """Number of whitespace-separated words in the sentence."""
    return len(sentence.split())


def describe(sentence):
    """Build a one-line human readable description of the reversal."""
    reversed_sentence = reverse_words(sentence)
    count = word_count(sentence)
    if count == 0:
        return "empty input -> empty result"
    if count == 1:
        return f"single word {sentence.strip()!r} is its own reversal"
    return f"{count} words: {sentence.strip()!r} -> {reversed_sentence!r}"


def is_palindromic_order(sentence):
    """True when the word order reads the same forwards and backwards."""
    words = sentence.split()
    return words == words[::-1]


def report_line(index, sentence):
    """Format a numbered table row for one sentence."""
    result = reverse_words(sentence)
    marker = "=" if is_palindromic_order(sentence) else " "
    return f"{index:>2}. {marker} {result}"


