def parse_numbers(text):
    """Turn a whitespace/comma separated string into a list of integers."""
    tokens = [tok for tok in text.replace(",", " ").split() if tok]
    numbers = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            raise ValueError(f"{token!r} is not a valid integer") from None
    return numbers


def validate(numbers):
    """Check the input really is a list of at least two distinct integers."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError(f"expected a list of integers, got {type(numbers).__name__}")
    for index, value in enumerate(numbers):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"element at position {index} is not an integer: {value!r}")
    if len(numbers) < 2:
        raise ValueError(f"need at least two elements, got {len(numbers)}")
    if len(set(numbers)) < 2:
        raise ValueError(f"need at least two distinct elements in {list(numbers)}")


def find_second_largest(numbers):
    """Return the second largest value of the list (duplicates of the maximum count)."""
    validate(numbers)
    ordered = sorted(numbers, reverse=True)
    return ordered[1]


def describe(numbers):
    """Build a one-line human readable report for a single list."""
    largest = max(numbers)
    second = find_second_largest(numbers)
    gap = largest - second
    body = f"{numbers} -> largest {largest}, second largest {second}"
    if gap == 0:
        return f"{body} (tied with the maximum)"
    return f"{body} (smaller by {gap})"


def report(datasets):
    """Describe every dataset, reporting problems instead of crashing."""
    lines = []
    for raw in datasets:
        if isinstance(raw, str):
            try:
                numbers = parse_numbers(raw)
            except ValueError as exc:
                lines.append(f"input {raw!r}: {exc}")
                continue
        else:
            numbers = list(raw)
        try:
            lines.append(describe(numbers))
        except (TypeError, ValueError) as exc:
            lines.append(f"input {numbers!r}: {exc}")
    return lines


def main():
