        [1, 1, 5, 5],
        "7, 7, 7, 3",
        "-4 -9 -1",
        [42],
        "3 x 9",
    ]
    for line in report(datasets):
        print(line)
    usable = sum(1 for line in report(datasets) if "->" in line)
    print(f"handled {usable} of {len(datasets)} datasets successfully")


if __name__ == "__main__":
