def run_length_encode(s):
    if not isinstance(s, str):
        raise TypeError(f"expected a string, got {type(s).__name__}")
    if any(ch.isdigit() for ch in s):
        raise ValueError(f"digits cannot be encoded unambiguously: {s!r}")
    parts = []
    index = 0
    while index < len(s):
        run = 1
        while index + run < len(s) and s[index + run] == s[index]:
            run += 1
        parts.append(f"{s[index]}{run}")
        index += run
    return "".join(parts)


def run_length_decode(encoded):
    out = []
    index = 0
    while index < len(encoded):
        char = encoded[index]
        index += 1
        start = index
        while index < len(encoded) and encoded[index].isdigit():
            index += 1
        if start == index:
            raise ValueError(f"missing count after {char!r} at position {start - 1}")
        out.append(char * int(encoded[start:index]))
    return "".join(out)


def compression_ratio(original, encoded):
    if not original:
        return 1.0
    return len(encoded) / len(original)


def describe(s):
    encoded = run_length_encode(s)
    ratio = compression_ratio(s, encoded)
    verdict = "shrinks" if ratio < 1 else "grows"
    summary = f"{s!r} -> {encoded!r}"
    return f"{summary} ({verdict}, ratio {ratio:.2f})"


def longest_run(s):
    encoded = run_length_encode(s)
    best_char, best_count = "", 0
    index = 0
    while index < len(encoded):
        char = encoded[index]
        index += 1
        start = index
        while index < len(encoded) and encoded[index].isdigit():
            index += 1
        count = int(encoded[start:index])
        if count > best_count:
            best_char, best_count = char, count
    return best_char, best_count


def main():
    samples = ["AAABBC", "A", "", "WWWWWWWWWWWWBWWWWWWWWWWWWBBB", "abcd"]
    for sample in samples:
        print(describe(sample))
        if sample:
            char, count = longest_run(sample)
            print(f"  longest run: {char} repeated {count} time(s)")
        restored = run_length_decode(run_length_encode(sample))
        if restored != sample:
            raise AssertionError(f"round trip failed for {sample!r}: got {restored!r}")
    try:
        run_length_encode("A3B2")
    except ValueError as exc:
        print(f"rejected input: {exc}")


if __name__ == "__main__":
    main()

