def binary_to_decimal(binary_string):
    """Convert a binary string such as '1011' into its decimal value."""
    cleaned = binary_string.strip()
    if not cleaned:
        raise ValueError("binary string must contain at least one digit")
    negative = cleaned.startswith("-")
    if negative:
        cleaned = cleaned[1:]
    for position, digit in enumerate(cleaned):
        if digit not in "01":
            raise ValueError(f"invalid digit {digit!r} at position {position}")
    value = 0
    for digit in cleaned:
        value = value * 2 + (1 if digit == "1" else 0)
    return -value if negative else value


def describe_conversion(binary_string):
    """Return a one-line human readable description of a conversion."""
    try:
        decimal = binary_to_decimal(binary_string)
    except ValueError as error:
        return f"{binary_string!r} -> error: {error}"
    return f"{binary_string} (base 2) = {decimal} (base 10)"


def expansion(binary_string):
    """Show the conversion as a sum of powers of two, e.g. 8 + 2 + 1."""
    digits = binary_string.strip().lstrip("-")
    width = len(digits)
    terms = []
    for index, digit in enumerate(digits):
        if digit == "1":
            power = width - index - 1
            terms.append(f"2^{power}")
    if not terms:
        return "0"
    joined = " + ".join(terms)
    total = binary_to_decimal(binary_string)
    return f"{joined} = {total}"


def convert_all(binary_strings):
    """Convert many strings, keeping failures as messages instead of values."""
    results = {}
    for text in binary_strings:
        try:
            results[text] = binary_to_decimal(text)
        except ValueError as error:
            results[text] = f"error: {error}"
    return results


def report(binary_strings):
    """Build a padded table of conversions suitable for printing."""
    results = convert_all(binary_strings)
    width = max(len(text) for text in results)
    lines = [f"{'binary'.ljust(width)} | decimal"]
    lines.append("-" * (width + 10))
    for text, value in results.items():
        lines.append(f"{text.ljust(width)} | {value}")
    return "\n".join(lines)


def main():
    samples = ["1011", "1", "0", "-110", "100000", "10201", ""]
    print(report(samples))
    print()
    for sample in ["1011", "100000", "-110"]:
        print(f"{describe_conversion(sample)}  [{expansion(sample)}]")
    total = sum(value for value in convert_all(samples).values()
                if isinstance(value, int))
    print(f"\nSum of the {len(samples)} sample values that converted: {total}")


if __name__ == "__main__":
    main()

