    if char in labels:
        return labels[char]
    return "'{}'".format(char)


def most_common(frequency_map):
    """Return the character with the highest count, ties broken alphabetically."""
    if not frequency_map:
        return None
    return min(frequency_map.items(), key=lambda item: (-item[1], item[0]))[0]


def format_row(char, count, total):
    """Format a single line of the frequency table."""
    share = count / total * 100
    label = describe_char(char)
    bar = "#" * count
    return "{:>10} {:>4} {:5.1f}% {}".format(label, count, share, bar)


def format_report(text):
    """Build a multi-line frequency report for text."""
    frequency_map = char_frequency(text)
    total = sum(frequency_map.values())
    lines = ["Frequency report for {!r}".format(text)]
    if total == 0:
        lines.append("  (empty input, nothing to count)")
        return "\n".join(lines)
    lines.append("  {} characters, {} distinct".format(total, len(frequency_map)))
    for char in sorted(frequency_map):
        lines.append("  " + format_row(char, frequency_map[char], total))
    top = most_common(frequency_map)
    lines.append("  most common: {} ({}x)".format(describe_char(top), frequency_map[top]))
    return "\n".join(lines)


def compare(first, second):
    """Summarise which characters the two texts share."""
    left = char_frequency(first)
    right = char_frequency(second)
    shared = sorted(set(left) & set(right))
    if not shared:
        return "{!r} and {!r} share no characters".format(first, second)
    parts = ["{}:{}/{}".format(describe_char(c), left[c], right[c]) for c in shared]
    return "{!r} vs {!r} -> ".format(first, second) + ", ".join(parts)


def main():
    samples = ["hello", "Python", "Mississippi River", ""]
    for sample in samples:
        print(format_report(sample))
        print()
    print(compare("hello", "Python"))
    print(compare("abc", "xyz"))
    counts = char_frequency("hello")
    print("char_frequency('hello') == {}".format(counts))


if __name__ == "__main__":
    main()

