"""Median calculation with input validation and a small reporting helper."""


def validate_numbers(numbers):
    """Return a list of numeric values, raising informative errors otherwise."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError(f"expected a list or tuple, got {type(numbers).__name__}")
    if len(numbers) == 0:
        raise ValueError("cannot compute the median of an empty sequence")
    checked = []
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"element at index {index} is not a number: {value!r}")
        checked.append(value)
    return checked


def calculate_median(numbers):
    """Return the median of numbers, averaging the two middle values if even."""
    values = sorted(validate_numbers(numbers))
    middle = len(values) // 2
    if len(values) % 2 == 1:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2


def format_number(value):
    """Render a number without a trailing '.0' so integers stay readable."""
    if isinstance(value, float) and value.is_integer():
        return f"{int(value)}"
    return f"{value}"


def describe_median(numbers):
    """Build a one-line human readable summary of the median computation."""
    values = sorted(validate_numbers(numbers))
    median_value = calculate_median(values)
    rendered = ", ".join(format_number(value) for value in values)
    middle = len(values) // 2
    if len(values) % 2 == 1:
        detail = f"middle element of {len(values)} values"
    else:
        low = format_number(values[middle - 1])
        high = format_number(values[middle])
        detail = f"average of {low} and {high}"
    return f"median([{rendered}]) = {format_number(median_value)} ({detail})"


def median_report(datasets):
    """Return a report line per dataset, noting the ones that are invalid."""
    lines = []
    for dataset in datasets:
        try:
            lines.append(describe_median(dataset))
        except (TypeError, ValueError) as error:
            lines.append(f"{dataset!r}: invalid input - {error}")
    return lines


def main():
    datasets = [
        [1, 2, 3, 4, 5],
        [1, 2, 3, 4],
        [7.5, 2, -3, 10],
        [42],
        [],
        [1, "two", 3],
    ]
    for line in median_report(datasets):
        print(line)
    total = sum(1 for dataset in datasets if isinstance(dataset, list) and dataset)
    print(f"processed {len(datasets)} datasets, {total} of them non-empty lists")


if __name__ == "__main__":
    main()

