def join_elements(items, separator):
    """Join all elements of items into one string using separator."""
    if not isinstance(items, list):
        raise TypeError(f"items must be a list, got {type(items).__name__}")
    if not isinstance(separator, str):
        raise TypeError(f"separator must be a str, got {type(separator).__name__}")
    for index, item in enumerate(items):
        if not isinstance(item, str):
            raise TypeError(f"items[{index}] must be a str, got {type(item).__name__}")
    return separator.join(items)


def describe_separator(separator):
    """Return a readable name for a separator so reports stay legible."""
    names = {" ": "space", ", ": "comma-space", "\t": "tab", "\n": "newline", "": "empty"}
    if separator in names:
        return names[separator]
    return f"{separator!r}"


def join_report(items, separator):
    """Join the items and return a one-line summary of the operation."""
    joined = join_elements(items, separator)
    sep_name = describe_separator(separator)
    return f"{len(items)} item(s) joined with {sep_name} -> {joined!r}"


def join_columns(rows, separator):
    """Join every row of a table, returning one joined line per row."""
    lines = []
    for row_number, row in enumerate(rows, start=1):
        if not isinstance(row, list):
            raise TypeError(f"row {row_number} must be a list, got {type(row).__name__}")
        lines.append(join_elements(row, separator))
    return lines


def render_table(rows, separator):
    """Render a table as text, prefixing each line with its row number."""
    lines = join_columns(rows, separator)
    width = len(str(len(lines)))
    numbered = []
    for row_number, line in enumerate(lines, start=1):
        label = str(row_number).rjust(width)
        numbered.append(f"{label} | {line}")
    return "\n".join(numbered)


def join_with_conjunction(items, conjunction="and"):
    """Join items in prose style: 'a, b and c'."""
    if len(items) == 0:
        return ""
    if len(items) == 1:
        return join_elements(items, "")
    head = join_elements(items[:-1], ", ")
    return f"{head} {conjunction} {items[-1]}"


def main():
    fruits = ["apple", "banana", "cherry"]
    print(join_elements(fruits, ", "))
    print(join_elements(["a", "b"], "-"))
    print(join_report(fruits, ", "))
    print(join_report(["a", "b"], "-"))
    print(join_report(fruits, " "))

    table = [["id", "name", "role"], ["1", "Ada", "engineer"], ["2", "Linus", "kernel"]]
    print(render_table(table, " | "))
    print(f"Prose: {join_with_conjunction(fruits)}.")
    print(f"Prose: {join_with_conjunction(['tea', 'coffee'], 'or')}.")

    csv_line = join_elements(table[0], ",")
    print(f"Header as CSV: {csv_line}")


if __name__ == "__main__":
    main()

