import os
import sys


def count_file_lines(filepath):
    """Return the number of lines in the text file at filepath."""
    line_count = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for _line in handle:
            line_count += 1
    return line_count


def count_blank_lines(filepath):
    """Return how many of the file's lines contain only whitespace."""
    blank_count = 0
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            if not line.strip():
                blank_count += 1
    return blank_count


def ends_without_newline(filepath):
    """True when the file has content whose last byte is not a newline."""
    size = os.path.getsize(filepath)
    if size == 0:
        return False
    with open(filepath, "rb") as handle:
        handle.seek(size - 1)
        return handle.read(1) != b"\n"


def describe_file(filepath):
    """Build a multi-line report about the line structure of one file."""
    total = count_file_lines(filepath)
    blank = count_blank_lines(filepath)
    name = os.path.basename(filepath)
    lines = [f"{name}: {total} line(s)"]
    if total == 0:
        lines.append("  the file is empty")
        return "\n".join(lines)
    lines.append(f"  blank lines: {blank}")
    lines.append(f"  content lines: {total - blank}")
    if ends_without_newline(filepath):
        lines.append(f"  note: line {total} is not terminated by a newline")
    return "\n".join(lines)


def summarize(filepaths):
    """Report each readable file and return the combined line count."""
    grand_total = 0
    for filepath in filepaths:
        if not os.path.isfile(filepath):
            print(f"skipping {filepath}: not a regular file", file=sys.stderr)
            continue
        print(describe_file(filepath))
        grand_total += count_file_lines(filepath)
    return grand_total


def main(argv):
    if len(argv) < 2:
        print(f"usage: {os.path.basename(argv[0])} FILE [FILE ...]", file=sys.stderr)
        return 2
    paths = argv[1:]
    total = summarize(paths)
    if len(paths) > 1:
        print(f"total across {len(paths)} file(s): {total} line(s)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

