def _validate(name, value):
    if not isinstance(value, dict):
        raise TypeError(f"{name} must be a dict, got {type(value).__name__}")
    return value


def update_dict(dict1, dict2):
    """Return a new dict with dict1's entries overridden/extended by dict2."""
    _validate("dict1", dict1)
    _validate("dict2", dict2)
    merged_dict = dict(dict1)
    merged_dict.update(dict2)
    return merged_dict


def classify_keys(dict1, dict2):
    """Split dict2's keys into the ones that overwrite dict1 and the new ones."""
    overlapping = [key for key in dict2 if key in dict1]
    added = [key for key in dict2 if key not in dict1]
    return overlapping, added


def describe_changes(dict1, dict2):
    """Build one human readable line per change applied by the merge."""
    overlapping, added = classify_keys(dict1, dict2)
    lines = []
    for key in overlapping:
        old, new = dict1[key], dict2[key]
        if old == new:
            lines.append(f"{key!r}: unchanged ({old!r})")
        else:
            lines.append(f"{key!r}: {old!r} -> {new!r}")
    for key in added:
        lines.append(f"{key!r}: added with value {dict2[key]!r}")
    return lines


def summarize(dict1, dict2):
    """One-line summary of how many keys are updated and how many are new."""
    overlapping, added = classify_keys(dict1, dict2)
    return f"{len(overlapping)} key(s) updated, {len(added)} key(s) added"


def format_report(dict1, dict2):
    merged = update_dict(dict1, dict2)
    parts = [f"{dict1} + {dict2}"]
    parts.append(f"  result: {merged}")
    parts.append(f"  summary: {summarize(dict1, dict2)}")
    for line in describe_changes(dict1, dict2):
        parts.append(f"  - {line}")
    return "\n".join(parts)


def main():
    cases = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
        ({'k': 'v', 'n': 5}, {'k': 'v'}),
        ({}, {'only': True}),
    ]
    for index, (first, second) in enumerate(cases, start=1):
        print(f"Case {index}")
        print(format_report(first, second))
        print(f"  originals intact: {first} / {second}")
        print()

    try:
        update_dict({'a': 1}, [('b', 2)])
    except TypeError as error:
        print(f"Rejected bad input: {error}")


if __name__ == "__main__":
    main()

