ALPHABET_SIZE = 26


def validate_input(text, shift):
    """Check that the ciphertext and shift are usable, raising ValueError if not."""
    if not isinstance(text, str):
        raise ValueError("text must be a str, got {}".format(type(text).__name__))
    if not isinstance(shift, int):
        raise ValueError("shift must be an int, got {}".format(type(shift).__name__))
    for position, char in enumerate(text):
        if not ("a" <= char <= "z"):
            raise ValueError("unsupported character {!r} at index {}".format(char, position))


def decrypt_caesar(text, shift):
    """Undo a Caesar shift applied to a lowercase message."""
    validate_input(text, shift)
    normalized = shift % ALPHABET_SIZE
    decrypted_chars = []
    for char in text:
        origin = (ord(char) - ord("a") - normalized) % ALPHABET_SIZE
        decrypted_chars.append(chr(ord("a") + origin))
    return "".join(decrypted_chars)


def encrypt_caesar(text, shift):
    """Apply a Caesar shift, useful for round-tripping a guess."""
    return decrypt_caesar(text, -shift)


def brute_force(text):
    """Return every candidate plaintext, keyed by the shift that produced it."""
    return {shift: decrypt_caesar(text, shift) for shift in range(ALPHABET_SIZE)}


def describe_attempt(text, shift):
    """Format a single decryption attempt as a one-line report."""
    plain = decrypt_caesar(text, shift)
    return "shift {:2d}: {} -> {}".format(shift, text, plain)


def report_candidates(text, wordlist):
    """List brute-force candidates, marking those that look like real words."""
    lines = ["Brute force of {!r} ({} candidates):".format(text, ALPHABET_SIZE)]
    known = {word.lower() for word in wordlist}
    for shift, candidate in brute_force(text).items():
        marker = " <== matches wordlist" if candidate in known else ""
        lines.append("  {:2d} {}{}".format(shift, candidate, marker))
    return "\n".join(lines)


def main():
    samples = [("khoor", 3), ("wkhuh", 3), ("bcd", 1), ("uryyb", 13)]
    for cipher, key in samples:
        print(describe_attempt(cipher, key))

    plain = "attack at dawn".replace(" ", "")
    key = 7
    cipher = encrypt_caesar(plain, key)
    print("{!r} encrypted with shift {} becomes {!r}".format(plain, key, cipher))
    recovered = decrypt_caesar(cipher, key)
    status = "ok" if recovered == plain else "mismatch"
    print("round trip: {!r} ({})".format(recovered, status))

    print(report_candidates("wkhuh", ["there", "where", "hello"]))

    try:
        decrypt_caesar("Khoor!", 3)
    except ValueError as error:
        print("rejected input: {}".format(error))


if __name__ == "__main__":
