def validate(numbers):
    """Return the numbers as floats, raising ValueError on invalid input."""
    if not numbers:
        raise ValueError("harmonic mean is undefined for an empty list")
    values = []
    for index, raw in enumerate(numbers):
        try:
            value = float(raw)
        except (TypeError, ValueError):
            raise ValueError(f"item {index} is not a number: {raw!r}")
        if value <= 0:
            raise ValueError(f"item {index} must be positive, got {value}")
        values.append(value)
    return values


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    values = validate(numbers)
    reciprocal_sum = sum(1.0 / value for value in values)
    mean_value = len(values) / reciprocal_sum
    return mean_value


def arithmetic_mean(numbers):
    values = validate(numbers)
    return sum(values) / len(values)


def describe(numbers):
    """Build a one-line summary comparing the harmonic and arithmetic means."""
    harmonic = harmonic_mean(numbers)
    arithmetic = arithmetic_mean(numbers)
    listing = ", ".join(f"{float(value):g}" for value in numbers)
    ratio = harmonic / arithmetic
    return f"[{listing}] -> H={harmonic:.6f} A={arithmetic:.6f} H/A={ratio:.4f}"


def average_speed(distances, speeds):
    """Average speed over equal-length legs is the harmonic mean of the speeds."""
    if len(distances) != len(speeds):
        raise ValueError(
            f"got {len(distances)} distances but {len(speeds)} speeds"
        )
    unique = set(distances)
    if len(unique) != 1:
        raise ValueError(f"legs must be equally long, found lengths {sorted(unique)}")
    return harmonic_mean(speeds)


def main():
    samples = [[1, 2, 4], [10, 10, 10], [1, 100], [2, 3, 6, 9]]
    for sample in samples:
        print(describe(sample))

    distances = [120.0, 120.0]
    speeds = [40.0, 60.0]
    speed = average_speed(distances, speeds)
    total = sum(distances)
    print(f"Driving {total:g} km in two legs at {speeds[0]:g} and {speeds[1]:g} km/h")
    print(f"gives an average speed of {speed:.2f} km/h ({total / speed:.2f} hours).")

    for bad in ([], [1, 0, 3], [1, "x"]):
        try:
            harmonic_mean(bad)
        except ValueError as error:
            print(f"rejected {bad!r}: {error}")


if __name__ == "__main__":
    main()

