def validate_inventory(inventory):
    """Ensure the inventory maps item names to non-negative integer quantities."""
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    for item, quantity in inventory.items():
        if not isinstance(item, str):
            raise TypeError(f"inventory keys must be strings, got {item!r}")
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError(f"quantity for {item!r} must be an int, got {quantity!r}")
        if quantity < 0:
            raise ValueError(f"quantity for {item!r} cannot be negative: {quantity}")
    return inventory


def validate_items(items_to_check):
    """Ensure the requested items form a list of strings."""
    if not isinstance(items_to_check, list):
        raise TypeError(f"items_to_check must be a list, got {type(items_to_check).__name__}")
    for position, item in enumerate(items_to_check):
        if not isinstance(item, str):
            raise TypeError(f"item at index {position} must be a string, got {item!r}")
    return items_to_check


def check_stock(inventory, items_to_check):
    """Return the available quantity of each requested item, 0 when missing."""
    validate_inventory(inventory)
    validate_items(items_to_check)
    stock_levels = {}
    for item in items_to_check:
        stock_levels[item] = inventory.get(item, 0)
    return stock_levels


def describe_level(item, quantity, low_threshold=3):
    """Turn a single stock level into a human readable line."""
    if quantity == 0:
        return f"{item}: out of stock"
    if quantity <= low_threshold:
        return f"{item}: only {quantity} left - reorder soon"
    return f"{item}: {quantity} in stock"


def build_report(inventory, items_to_check, low_threshold=3):
    """Produce a multi-line stock report for the requested items."""
    stock_levels = check_stock(inventory, items_to_check)
    lines = [f"Stock report for {len(stock_levels)} item(s)"]
    for item, quantity in stock_levels.items():
        lines.append(describe_level(item, quantity, low_threshold))
    missing = [item for item, quantity in stock_levels.items() if quantity == 0]
    if missing:
        lines.append(f"Unavailable: {', '.join(sorted(missing))}")
    total = sum(stock_levels.values())
    lines.append(f"Total units available: {total}")
    return "\n".join(lines)


def main():
    warehouse = {'apple': 10, 'banana': 5, 'milk': 2}
    requested = ['apple', 'orange', 'milk']
    levels = check_stock(warehouse, requested)
    print(f"Raw levels: {levels}")
    print(build_report(warehouse, requested))
    empty_result = check_stock({}, ['milk'])
    print(f"Empty warehouse lookup: {empty_result}")
    try:
        check_stock(warehouse, ['apple', 7])
    except TypeError as error:
        print(f"Rejected bad request: {error}")


if __name__ == '__main__':
    main()

