def validate_number(value, label):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{label} must be an int, got {type(value).__name__}")
    return value


def simulate_guess(target, guess):
    validate_number(target, "target")
    validate_number(guess, "guess")
    if guess > target:
        return 'Too high'
    if guess < target:
        return 'Too low'
    return 'Correct!'


def describe_round(round_number, guess, feedback):
    return f"Round {round_number}: guessed {guess} -> {feedback}"


def play_game(target, low, high, max_rounds=10):
    """Play a full game with a binary-search strategy, returning the log."""
    if low > high:
        raise ValueError(f"empty search range [{low}, {high}]")
    if not low <= target <= high:
        raise ValueError(f"target {target} is outside [{low}, {high}]")
    log = []
    for round_number in range(1, max_rounds + 1):
        guess = (low + high) // 2
        feedback = simulate_guess(target, guess)
        log.append(describe_round(round_number, guess, feedback))
        if feedback == 'Correct!':
            break
        if feedback == 'Too high':
            high = guess - 1
        else:
            low = guess + 1
    else:
        log.append(f"Gave up after {max_rounds} rounds; target was {target}")
    return log


def summarize(target, log):
    solved = log[-1].endswith('Correct!')
    if solved:
        return f"Found {target} in {len(log)} round(s)"
    return f"Failed to find {target} within the round limit"


def format_report(target, low, high):
    log = play_game(target, low, high)
    header = f"Searching for {target} in range [{low}, {high}]"
    lines = [header]
    lines.extend(log)
    lines.append(summarize(target, log))
    return "\n".join(lines)


def main():
    games = [(7, 1, 10), (42, 1, 100), (1, 1, 64)]
    for target, low, high in games:
