        print()
    single = simulate_guess(7, 5)
    print(f"Single round check: simulate_guess(7, 5) = {single!r}")
    try:
        simulate_guess(7, "five")
    except TypeError as exc:
        print(f"Rejected bad input: {exc}")


if __name__ == '__main__':
    main()

