def validate_input(dict_list, key):
    if not isinstance(dict_list, list):
        raise TypeError(f"dict_list must be a list, got {type(dict_list).__name__}")
    if not isinstance(key, str):
        raise TypeError(f"key must be a str, got {type(key).__name__}")
    for index, item in enumerate(dict_list):
        if not isinstance(item, dict):
            raise TypeError(f"element {index} is not a dict: {item!r}")
        if key not in item:
            raise KeyError(f"element {index} has no key {key!r}")


def sort_dicts_by_key(dict_list, key):
    validate_input(dict_list, key)
    return sorted(dict_list, key=lambda record: record[key])


def format_record(record, key):
    primary = f"{key}={record[key]!r}"
    extras = [f"{name}={value!r}" for name, value in record.items() if name != key]
    return " | ".join([primary] + extras)


def format_table(dict_list, key):
    lines = [f"sorted by {key!r} ({len(dict_list)} records)"]
    for position, record in enumerate(dict_list, start=1):
        lines.append(f"{position:>3}. {format_record(record, key)}")
    return "\n".join(lines)


def summarize(dict_list, key):
    values = [record[key] for record in dict_list]
    if not values:
        return f"no values available for key {key!r}"
    return f"{key}: first={values[0]!r} last={values[-1]!r}"


def report(dict_list, key):
    try:
        ordered = sort_dicts_by_key(dict_list, key)
    except (TypeError, KeyError) as error:
        return f"cannot sort: {error}"
    table = format_table(ordered, key)
    return f"{table}\n{summarize(ordered, key)}"


def main():
    people = [{'name': 'B', 'age': 30}, {'name': 'A', 'age': 20}]
    ids = [{'id': 2}, {'id': 1}]
    mixed = [{'name': 'C', 'age': 41}, {'name': 'D'}]

    print(f"example 1 -> {sort_dicts_by_key(people, 'age')}")
    print(f"example 2 -> {sort_dicts_by_key(ids, 'id')}")
    print(report(people, 'age'))
    print(report(ids, 'id'))
    print(report(mixed, 'age'))

    by_name = sort_dicts_by_key(people, 'name')
    names = ", ".join(record['name'] for record in by_name)
    print(f"names in order: {names}")


if __name__ == "__main__":
    main()

