def parse_tokens(encoded_string):
    """Split an RLE string into (count, char) pairs, validating as we go."""
    if not isinstance(encoded_string, str):
        raise TypeError(f"expected a string, got {type(encoded_string).__name__}")
    tokens = []
    index = 0
    length = len(encoded_string)
    while index < length:
        digits = ""
        while index < length and encoded_string[index].isdigit():
            digits += encoded_string[index]
            index += 1
        if not digits:
            raise ValueError(f"missing count before {encoded_string[index]!r} at position {index}")
        if index >= length:
            raise ValueError(f"count {digits} at end of input has no character")
        count = int(digits)
        if count == 0:
            raise ValueError(f"count of zero at position {index - 1} is not allowed")
        tokens.append((count, encoded_string[index]))
        index += 1
    return tokens


def run_length_decode(encoded_string):
    """Expand a 'count_char' run-length encoded string."""
    return "".join(char * count for count, char in parse_tokens(encoded_string))


def run_length_encode(plain_string):
    """Inverse of run_length_decode, used to show the normal form of an input."""
    pieces = []
    index = 0
    while index < len(plain_string):
        run = 1
        while index + run < len(plain_string) and plain_string[index + run] == plain_string[index]:
            run += 1
        pieces.append(f"{run}{plain_string[index]}")
        index += run
    return "".join(pieces)


def describe(encoded_string, decoded):
    """Build a human readable report line for one decoded input."""
    runs = len(parse_tokens(encoded_string))
    report = f"{encoded_string!r} -> {decoded!r} ({len(decoded)} chars, {runs} runs)"
    normalised = run_length_encode(decoded)
    if normalised != encoded_string:
        report += f" [normalises to {normalised!r}]"
    return report


def main():
    samples = ["3A2B1C", "1X", "", "10Z2a2A", "2A3A", "A3", "4"]
    decoded_total = 0
    for sample in samples:
        try:
            decoded = run_length_decode(sample)
        except (TypeError, ValueError) as error:
            print(f"{sample!r} -> error: {error}")
            continue
        decoded_total += len(decoded)
        print(describe(sample, decoded))
    print(f"decoded {decoded_total} characters in total")


if __name__ == "__main__":
    main()

