def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    opening_brackets = set(mapping.values())
    closing_brackets = set(mapping.keys())

    for char_index, char in enumerate(s):
        if char in opening_brackets:
            stack.append(char)
            f"Pushed {char} onto stack at index {char_index}."
        elif char in closing_brackets:
            f"Encountered closing bracket {char} at index {char_index}."
            if not stack:
                f"Stack is empty, but found {char}. Imbalance detected."
                return False
            top_element = stack.pop()
            f"Popped {top_element} from stack."
            if mapping[char] != top_element:
                f"Mismatched brackets: expected {mapping[char]}, got {top_element}."
                return False
        else:
            f"Unexpected character {char} encountered. Ignoring it."

    is_empty_stack = not stack
    f"Final stack empty status: {is_empty_stack}."
    final_result = len(stack) == 0
    f"Function returning {final_result}."
    return final_result

