def extract_numbers(text):
    """Return every digit found in *text*, concatenated in order of appearance."""
    if not isinstance(text, str):
        raise TypeError(f"extract_numbers() expects a str, got {type(text).__name__}")
    return "".join(character for character in text if character.isdigit())


def digit_runs(text):
    """Split the digits of *text* into the maximal runs they form in the source."""
    runs = []
    current = ""
    for character in text:
        if character.isdigit():
            current = f"{current}{character}"
        elif current:
            runs.append(current)
            current = ""
    if current:
        runs.append(current)
    return runs


def digit_sum(digits_string):
    """Add up the individual digits of an already extracted digit string."""
    return sum(int(digit) for digit in digits_string)


def describe(text):
    """Build a one-line human readable summary of the digits inside *text*."""
    digits_string = extract_numbers(text)
    if not digits_string:
        return f"{text!r}: no digits found"
    runs = digit_runs(text)
    joined_runs = " + ".join(runs)
    total = digit_sum(digits_string)
    summary = f"{text!r}: {digits_string!r}"
    return f"{summary} ({len(digits_string)} digits, runs {joined_runs}, digit sum {total})"


def largest_run(text):
    """Return the numerically largest run of digits, or None when there is none."""
    runs = digit_runs(text)
    if not runs:
        return None
    return max(runs, key=lambda run: (len(run.lstrip("0")), run))


def report(samples):
    """Produce a multi-line report for a sequence of input strings."""
    lines = [f"Scanned {len(samples)} sample(s)"]
    for index, sample in enumerate(samples, start=1):
        lines.append(f"{index:>3}. {describe(sample)}")
        biggest = largest_run(sample)
        if biggest is not None:
            lines.append(f"     largest run: {int(biggest)}")
    collected = "".join(extract_numbers(sample) for sample in samples)
    lines.append(f"All digits combined: {collected!r}")
    return "\n".join(lines)


def main():
    samples = [
        "abc123def45",
        "No numbers here.",
        "Order #00742 shipped on 2024-05-09 at 08:30",
        "pi is roughly 3.14159",
    ]
    print(report(samples))
    first = extract_numbers(samples[0])
    print(f"extract_numbers({samples[0]!r}) -> {first!r}")
    empty = extract_numbers(samples[1])
    print(f"extract_numbers({samples[1]!r}) -> {empty!r}")


if __name__ == "__main__":
    main()

