def validate_rectangle(x1, y1, x2, y2):
    """Raise ValueError unless (x1, y1)-(x2, y2) describes a proper rectangle."""
    if x1 > x2:
        raise ValueError(f"left edge {x1} lies right of right edge {x2}")
    if y1 > y2:
        raise ValueError(f"bottom edge {y1} lies above top edge {y2}")
    return True


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    """Return True when (px, py) lies inside or on the border of the rectangle."""
    validate_rectangle(x1, y1, x2, y2)
    return x1 <= px <= x2 and y1 <= py <= y2


def describe_rectangle(x1, y1, x2, y2):
    width = x2 - x1
    height = y2 - y1
    corners = f"({x1}, {y1}) to ({x2}, {y2})"
    return f"rectangle {corners} with width {width} and height {height}"


def classify_point(px, py, x1, y1, x2, y2):
    """Return 'inside', 'border' or 'outside' for the given point."""
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "outside"
    on_vertical = px == x1 or px == x2
    on_horizontal = py == y1 or py == y2
    if on_vertical or on_horizontal:
        return "border"
    return "inside"


def offset_report(px, py, x1, y1, x2, y2):
    """Describe how far the point is from the rectangle along each axis."""
    dx = max(x1 - px, px - x2, 0)
    dy = max(y1 - py, py - y2, 0)
    if dx == 0 and dy == 0:
        return "no offset needed"
    parts = []
    if dx:
        parts.append(f"{dx} unit(s) horizontally")
    if dy:
        parts.append(f"{dy} unit(s) vertically")
    return "off by " + " and ".join(parts)


def format_result(px, py, x1, y1, x2, y2):
    inside = is_point_in_rectangle(px, py, x1, y1, x2, y2)
    kind = classify_point(px, py, x1, y1, x2, y2)
    line = f"({px}, {py}) -> {inside} [{kind}]"
    return f"{line}; {offset_report(px, py, x1, y1, x2, y2)}"


def main():
    rect = (0, 0, 5, 5)
    print(f"Testing {describe_rectangle(*rect)}")
    for px, py in [(3, 3), (6, 2), (0, 0), (5, 1), (-2, 7)]:
        print(format_result(px, py, *rect))
    try:
        is_point_in_rectangle(1, 1, 4, 0, 2, 3)
    except ValueError as exc:
        print(f"invalid rectangle rejected: {exc}")


if __name__ == "__main__":
    main()

