def get_item_quantity(inventory, item_name):
    """Return the quantity of item_name in inventory, or 0 if it is absent."""
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    if not isinstance(item_name, str):
        raise TypeError(f"item_name must be a str, got {type(item_name).__name__}")
    quantity = inventory.get(item_name, 0)
    if not isinstance(quantity, int):
        raise ValueError(f"quantity for {item_name!r} is not an integer: {quantity!r}")
    return quantity


def describe_item(inventory, item_name):
    """Build a human readable line about one item."""
    quantity = get_item_quantity(inventory, item_name)
    if quantity == 0:
        return f"{item_name}: out of stock"
    unit = "unit" if quantity == 1 else "units"
    return f"{item_name}: {quantity} {unit} in stock"


