def validate_numbers(numbers):
    """Ensure the input is a list with at least two distinct numeric values."""
    if not isinstance(numbers, list):
        raise TypeError(f"expected a list of numbers, got {type(numbers).__name__}")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"element at index {index} is not a number: {value!r}")
    distinct = set(numbers)
    if len(distinct) < 2:
        raise ValueError(f"need at least two distinct numbers, found {len(distinct)}")
    return distinct


def find_second_smallest(numbers):
    """Return the second smallest distinct value of the list."""
    validate_numbers(numbers)
    smallest = None
    second = None
    for value in numbers:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value
    return second


def format_number(value):
    """Render a number without a trailing .0 for whole floats."""
    if isinstance(value, float) and value.is_integer():
        return f"{int(value)}"
    return f"{value}"


def describe(numbers):
    """Build a one-line report about the second smallest value of a list."""
    try:
        result = find_second_smallest(numbers)
    except (TypeError, ValueError) as error:
        return f"{numbers!r} -> error: {error}"
    shown = format_number(result)
    return f"{numbers!r} -> second smallest is {shown}"


def rank_lists(datasets):
    """Order datasets by their second smallest value, smallest first."""
    scored = []
    for dataset in datasets:
        scored.append((find_second_smallest(dataset), dataset))
    scored.sort(key=lambda pair: pair[0])
    return scored


def main():
    samples = [
        [5, 1, 8, 2, 9],
        [10, 20, 30, 5],
        [3.5, 3.5, 1.25, 7.0],
        [-4, -4, -9, 0],
    ]
    for sample in samples:
        print(describe(sample))
    print(describe([7, 7, 7]))
    print(describe([1, "two", 3]))

    print("\nRanking by second smallest:")
    for position, (value, dataset) in enumerate(rank_lists(samples), start=1):
        label = format_number(value)
        print(f"{position}. {label:>6}  from {dataset}")

    overall = find_second_smallest([find_second_smallest(s) for s in samples])
    print(f"\nSecond smallest among the results: {format_number(overall)}")


if __name__ == "__main__":
    main()

