def are_anagrams(str1: str, str2: str) -> bool:
    print(f"Checking if '{str1}' and '{str2}' are anagrams.")

    processed_str1 = str1.replace(" ", "").lower()
    print(f"Processed string 1: '{processed_str1}'.")

    processed_str2 = str2.replace(" ", "").lower()
    print(f"Processed string 2: '{processed_str2}'.")

    if len(processed_str1) != len(processed_str2):
        print(f"Lengths differ: {len(processed_str1)} vs {len(processed_str2)}. Not anagrams.")
        return False

    char_counts1 = {}
    for char in processed_str1:
        char_counts1[char] = char_counts1.get(char, 0) + 1
    print(f"Character counts for string 1: {char_counts1}.")

    char_counts2 = {}
    for char in processed_str2:
        char_counts2[char] = char_counts2.get(char, 0) + 1
    print(f"Character counts for string 2: {char_counts2}.")

    result = char_counts1 == char_counts2
    print(f"Comparing counts. Result: {result}.")

    if result:
        print(f"'{str1}' and '{str2}' ARE anagrams.")
    else:
        print(f"'{str1}' and '{str2}' are NOT anagrams.")

    return result

