"""Celsius to Fahrenheit conversion with a small command-line front end."""

import sys

ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return float(celsius) * 9 / 5 + 32


def parse_temperature(text):
    """Turn a user-supplied string into a float, raising a clear error."""
    cleaned = text.strip().rstrip("cC").strip()
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError(f"not a valid Celsius temperature: {text!r}")


def validate(celsius):
    """Reject temperatures below absolute zero."""
    if celsius < ABSOLUTE_ZERO_C:
        raise ValueError(
            f"{celsius:g} °C is below absolute zero ({ABSOLUTE_ZERO_C} °C)"
        )
    return celsius


def describe(celsius):
    """Return a short human-readable description of the conversion."""
    fahrenheit = celsius_to_fahrenheit(celsius)
    return f"{celsius:.2f} °C = {fahrenheit:.2f} °F"


def water_state(celsius):
    """Name the state of water at the given temperature, at sea level."""
    if celsius <= 0:
        return "ice"
    if celsius >= 100:
        return "steam"
    return "liquid water"


def report(celsius):
    """Combine the conversion and the water-state note into one line."""
    state = water_state(celsius)
    return f"{describe(celsius)} ({state})"


def conversion_table(start, stop, step):
    """Build a table of conversions from start to stop inclusive."""
    lines = [f"{'Celsius':>10} {'Fahrenheit':>12}"]
    value = start
    while value <= stop:
        fahrenheit = celsius_to_fahrenheit(value)
        lines.append(f"{value:>10.1f} {fahrenheit:>12.1f}")
        value += step
    return "\n".join(lines)


def main(argv):
    if not argv:
        print(conversion_table(ABSOLUTE_ZERO_C, 100.0, 25.0))
        return 0
    status = 0
    for arg in argv:
        try:
            celsius = validate(parse_temperature(arg))
        except ValueError as error:
            print(f"error: {error}", file=sys.stderr)
            status = 1
            continue
        print(report(celsius))
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

