import re
from collections import Counter

EMAIL_PATTERN = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+")


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    if not isinstance(text, str):
        raise TypeError(f"text must be a str, got {type(text).__name__}")
    return [match.group(0).rstrip(".") for match in EMAIL_PATTERN.finditer(text)]


def split_address(email):
    """Split an address into its local part and its domain."""
    local, _, domain = email.partition("@")
    return local, domain.lower()


def domain_of(email):
    return split_address(email)[1]


def unique_emails(emails):
    """Drop duplicates (case-insensitive on the domain) keeping first order."""
    seen = set()
    result = []
    for email in emails:
        local, domain = split_address(email)
        key = f"{local}@{domain}"
        if key not in seen:
            seen.add(key)
            result.append(email)
    return result


def group_by_domain(emails):
    groups = {}
    for email in emails:
        groups.setdefault(domain_of(email), []).append(email)
    return groups


def describe(email):
    local, domain = split_address(email)
    tld = domain.rsplit(".", 1)[-1]
    return f"{local} at {domain} (.{tld})"


def build_report(text):
    found = extract_emails(text)
    lines = [f"Scanned {len(text)} characters, found {len(found)} address(es)."]
    if not found:
        return lines
    distinct = unique_emails(found)
    if len(distinct) != len(found):
        lines.append(f"Removed {len(found) - len(distinct)} duplicate(s).")
    for domain, members in sorted(group_by_domain(distinct).items()):
        lines.append(f"{domain}: {len(members)}")
        for email in members:
            lines.append(f"  - {describe(email)}")
    top_tld, count = Counter(d.rsplit(".", 1)[-1] for d in group_by_domain(distinct)).most_common(1)[0]
    lines.append(f"Most common TLD: .{top_tld} ({count} domain(s))")
    return lines


def main():
    samples = [
        "Contact us at info@example.com or support@test.org.",
        "No emails here.",
        "Ping sales@shop.co.uk, sales@shop.co.uk or dev.ops@mail.example.com today!",
    ]
    for index, sample in enumerate(samples, start=1):
        print(f"--- sample {index} ---")
        print(f"input: {sample}")
        print(f"emails: {extract_emails(sample)}")
        for line in build_report(sample):
            print(line)


if __name__ == "__main__":
    main()

