def longest_common_prefix(strings):
    """Return the longest string that prefixes every entry of `strings`."""
    if not isinstance(strings, list):
        raise TypeError(f"expected a list of strings, got {type(strings).__name__}")
    for index, value in enumerate(strings):
        if not isinstance(value, str):
            raise TypeError(f"item {index} is not a string: {value!r}")
    if not strings:
        return ""
    shortest = min(strings, key=len)
    for position, char in enumerate(shortest):
        for candidate in strings:
            if candidate[position] != char:
                return shortest[:position]
    return shortest


def prefix_report(strings):
    """Describe the common prefix of `strings` in one human-readable line."""
    prefix = longest_common_prefix(strings)
    listed = ", ".join(repr(word) for word in strings)
    if not prefix:
        return f"[{listed}] share no common prefix"
    return f"[{listed}] share the prefix {prefix!r} ({len(prefix)} chars)"


def group_by_prefix(strings, length):
    """Bucket words by their first `length` characters."""
    if length < 1:
        raise ValueError(f"length must be positive, got {length}")
    groups = {}
    for word in strings:
        groups.setdefault(word[:length], []).append(word)
    return groups


def group_summary(strings, length):
    """Render one line per prefix group, including each group's true prefix."""
    lines = []
    for key, members in sorted(group_by_prefix(strings, length).items()):
        common = longest_common_prefix(members)
        joined = "/".join(members)
        lines.append(f"{key} -> {joined} [lcp={common!r}]")
    return lines


def main():
    samples = [
        ["flower", "flow", "flight"],
        ["dog", "racecar", "car"],
        ["interspecies", "interstellar", "interstate"],
        ["single"],
        [],
    ]
    for sample in samples:
        print(prefix_report(sample))

    words = ["apple", "apply", "apt", "banana", "band", "bandit", "cat"]
    print(f"Grouping {len(words)} words by their first 2 characters:")
    for line in group_summary(words, 2):
        print(f"  {line}")

    overall = longest_common_prefix(words)
    print(f"Overall prefix of the word list: {overall!r}")


if __name__ == "__main__":
    main()

