def validate_2x2(matrix, name):
    """Raise ValueError unless *matrix* is a 2x2 list of lists of numbers."""
    if not isinstance(matrix, list):
        raise ValueError(f"{name} must be a list of lists, got {type(matrix).__name__}")
    if len(matrix) != 2:
        raise ValueError(f"{name} must have exactly 2 rows, got {len(matrix)}")
    for index, row in enumerate(matrix):
        if not isinstance(row, list):
            raise ValueError(f"{name}[{index}] must be a list, got {type(row).__name__}")
        if len(row) != 2:
            raise ValueError(f"{name}[{index}] must have exactly 2 columns, got {len(row)}")
        for column, value in enumerate(row):
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"{name}[{index}][{column}] must be a number, got {value!r}")
    return matrix


def multiply_2x2_matrices(matrix_a, matrix_b):
    """Return the 2x2 product of two 2x2 matrices."""
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    return [
        [
            matrix_a[0][0] * matrix_b[0][0] + matrix_a[0][1] * matrix_b[1][0],
            matrix_a[0][0] * matrix_b[0][1] + matrix_a[0][1] * matrix_b[1][1],
        ],
        [
            matrix_a[1][0] * matrix_b[0][0] + matrix_a[1][1] * matrix_b[1][0],
            matrix_a[1][0] * matrix_b[0][1] + matrix_a[1][1] * matrix_b[1][1],
        ],
    ]


def format_matrix(matrix):
    """Render a 2x2 matrix on a single line, e.g. '[[1, 2], [3, 4]]'."""
    rows = []
    for row in matrix:
        cells = ", ".join(format_number(value) for value in row)
        rows.append(f"[{cells}]")
    return f"[{', '.join(rows)}]"


def format_number(value):
    """Drop the trailing '.0' from whole floats so output stays compact."""
    if isinstance(value, float) and value.is_integer():
        return f"{int(value)}"
    return f"{value}"


def describe_product(matrix_a, matrix_b):
    """Build a human readable 'A x B = C' description of the product."""
    product = multiply_2x2_matrices(matrix_a, matrix_b)
    return f"{format_matrix(matrix_a)} x {format_matrix(matrix_b)} = {format_matrix(product)}"


def main():
    pairs = [
        ([[1, 2], [3, 4]], [[5, 6], [7, 8]]),
        ([[1, 0], [0, 1]], [[10, 20], [30, 40]]),
        ([[0.5, 1.5], [-2, 4]], [[2, 0], [0, 2]]),
    ]
    for number, (matrix_a, matrix_b) in enumerate(pairs, start=1):
        print(f"Case {number}: {describe_product(matrix_a, matrix_b)}")

    broken = [[1, 2], [3]]
    try:
