def calculate_sma(data: list[float | int], window_size: int) -> list[float]:
    """
    Calculates the simple moving average for a given list of data points
    over a specified window size.
    """
    if not isinstance(data, list):
        raise TypeError(f"Input 'data' must be a list, got {type(data)}")
    if not all(isinstance(x, (int, float)) for x in data):
        raise ValueError(f"All elements in 'data' must be numeric. Found non-numeric.")
    if not isinstance(window_size, int) or window_size <= 0:
        raise ValueError(f"Window size must be a positive integer, got {window_size}")
    if window_size > len(data):
        raise ValueError(f"Window size ({window_size}) cannot be larger than the data length ({len(data)})")

    sma_values = []
    for i in range(len(data) - window_size + 1):
        current_window = data[i : i + window_size]
        window_sum = sum(current_window)
        average = window_sum / window_size
        sma_values.append(average)
        if i == 0:
            print(f"First window: {current_window}, sum: {window_sum}, average: {average:.1f}")

    print(f"Calculated {len(sma_values)} SMA values for window size {window_size}.")
    if sma_values:
        print(f"The first SMA value is {sma_values[0]:.1f} and the last is {sma_values[-1]:.1f}.")
    return sma_values

if __name__ == '__main__':
    data1 = [1, 2, 3, 4, 5]
    window1 = 3
    result1 = calculate_sma(data1, window1)
    print(f"SMA for {data1} with window {window1}: {result1}")

    data2 = [10, 20, 30, 40]
    window2 = 2
    result2 = calculate_sma(data2, window2)
    print(f"SMA for {data2} with window {window2}: {result2}")

