import math


def proper_divisors(number):
    """Return the sorted proper divisors of a positive integer."""
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 1:
        raise ValueError(f"number must be positive, got {number}")
    if number == 1:
        return []
    divisors = {1}
    limit = int(math.isqrt(number))
    for candidate in range(2, limit + 1):
        if number % candidate == 0:
            divisors.add(candidate)
            divisors.add(number // candidate)
    return sorted(divisors)


def is_perfect_number(number):
    """Return True when number equals the sum of its proper divisors."""
    return sum(proper_divisors(number)) == number


def classify(number):
    """Label a number as perfect, abundant or deficient."""
    total = sum(proper_divisors(number))
    if total == number:
        return "perfect"
    if total > number:
        return "abundant"
    return "deficient"


def describe(number):
    """Build a human readable explanation of the classification."""
    divisors = proper_divisors(number)
    total = sum(divisors)
    kind = classify(number)
    if not divisors:
        return f"{number} has no proper divisors, so it is {kind}"
    terms = " + ".join(str(d) for d in divisors)
    return f"{number} is {kind}: {terms} = {total}"


def perfect_numbers_below(bound):
    """List every perfect number strictly smaller than bound."""
    return [n for n in range(1, bound) if is_perfect_number(n)]


def main():
    for sample in (6, 28, 12, 1, 496):
        verdict = is_perfect_number(sample)
        print(f"is_perfect_number({sample}) -> {verdict}")
        print(f"  {describe(sample)}")

    bound = 10000
    found = perfect_numbers_below(bound)
    joined = ", ".join(str(n) for n in found)
    print(f"Perfect numbers below {bound}: {joined}")
    print(f"Count of perfect numbers below {bound}: {len(found)}")

    for bad in (0, -7, 3.5):
        try:
            is_perfect_number(bad)
        except (TypeError, ValueError) as error:
            print(f"rejected {bad!r}: {error}")


if __name__ == "__main__":
    main()

