def reverse_string(input_string):
    """Return a new string with the characters of input_string in reverse order."""
    if not isinstance(input_string, str):
        raise TypeError(
            "reverse_string expects a str, got {}".format(type(input_string).__name__)
        )
    reversed_chars = []
    for index in range(len(input_string) - 1, -1, -1):
        reversed_chars.append(input_string[index])
    return "".join(reversed_chars)


def is_palindrome(input_string):
    """Report whether the string reads the same forwards and backwards."""
    normalized = "".join(ch.lower() for ch in input_string if ch.isalnum())
    return normalized == reverse_string(normalized)


def reverse_words(input_string):
    """Reverse each whitespace-separated word, keeping the word order."""
    return " ".join(reverse_string(word) for word in input_string.split())


def describe(input_string):
    """Build a one-line human readable description of a reversal."""
    reversed_string = reverse_string(input_string)
    line = "{!r} -> {!r}".format(input_string, reversed_string)
    if is_palindrome(input_string):
        return "{} (palindrome)".format(line)
    return line


def build_report(samples):
    """Return the full multi-line report for a sequence of sample strings."""
    lines = ["Reversing {} sample string(s)".format(len(samples))]
    lines.append("-" * len(lines[0]))
    for position, sample in enumerate(samples, start=1):
        lines.append("{:>2}. {}".format(position, describe(sample)))
    total_chars = sum(len(sample) for sample in samples)
    lines.append("Total characters processed: {}".format(total_chars))
    return "\n".join(lines)


def main():
    samples = [
        "hello",
        "Python",
        "A man, a plan, a canal: Panama",
        "",
        "step on no pets",
    ]
    print(build_report(samples))

    phrase = "never odd or even"
    print("Words of {!r} reversed individually: {}".format(phrase, reverse_words(phrase)))

    longest = max(samples, key=len)
    print("Longest sample {!r} reverses to {!r}".format(longest, reverse_string(longest)))

    try:
        reverse_string(12345)
    except TypeError as error:
        print("Rejected non-string input: {}".format(error))


if __name__ == "__main__":
