        if not isinstance(initial_balance, (int, float)) or initial_balance < 0:
            raise ValueError(f"Initial balance must be a non-negative number, got {initial_balance}.")
        self._balance = initial_balance
        print(f"Account initialized with an initial balance of ${self._balance:.2f}.")

