        if not isinstance(amount, (int, float)) or amount <= 0:
            print(f"Withdrawal amount must be a positive number, got {amount}.")
            return False
        if amount > self._balance:
            print(f"Insufficient funds. Attempted to withdraw ${amount:.2f} but current balance is ${self._balance:.2f}.")
            return False
        self._balance -= amount
        print(f"Withdrew ${amount:.2f}. New balance is ${self._balance:.2f}.")
        return True

    def get_balance(self):
        return self._balance

    def __str__(self):
        return f"BankAccount with balance: ${self._balance:.2f}"

