def _validate_event(event, label):
    if not isinstance(event, tuple) or len(event) != 2:
        raise ValueError(f"{label} must be a tuple of (start_time, end_time), got {event!r}")
    start, end = event
    for name, value in (("start_time", start), ("end_time", end)):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"{label} {name} must be an integer, got {value!r}")
    if start > end:
        raise ValueError(f"{label} starts at {start} but ends at {end}")
    return start, end


def format_time(minutes):
    hours, mins = divmod(minutes % 1440, 60)
    return f"{hours:02d}:{mins:02d}"


def format_event(event):
    start, end = event
    return f"{format_time(start)}-{format_time(end)}"


def check_event_overlap(event1, event2):
    start1, end1 = _validate_event(event1, "event1")
    start2, end2 = _validate_event(event2, "event2")
    return start1 < end2 and start2 < end1


def overlap_interval(event1, event2):
    if not check_event_overlap(event1, event2):
        return None
    return max(event1[0], event2[0]), min(event1[1], event2[1])


def describe_overlap(event1, event2):
    shared = overlap_interval(event1, event2)
    left = format_event(event1)
    right = format_event(event2)
    if shared is None:
        return f"{left} and {right} do not overlap"
    duration = shared[1] - shared[0]
    return f"{left} and {right} overlap for {duration} min ({format_event(shared)})"


def find_conflicts(events):
    conflicts = []
    for i, first in enumerate(events):
        for second in events[i + 1:]:
            if check_event_overlap(first, second):
                conflicts.append((first, second))
    return conflicts


def schedule_report(events):
    lines = [f"Schedule with {len(events)} event(s):"]
    for index, event in enumerate(sorted(events), start=1):
        lines.append(f"  {index}. {format_event(event)}")
    conflicts = find_conflicts(events)
    if not conflicts:
        lines.append("No conflicts found.")
    else:
        lines.append(f"Found {len(conflicts)} conflict(s):")
        lines.extend(f"  - {describe_overlap(a, b)}" for a, b in conflicts)
    return "\n".join(lines)


def main():
    pairs = [((10, 20), (15, 25)), ((10, 15), (20, 25)), ((540, 600), (570, 585))]
    for event1, event2 in pairs:
        result = check_event_overlap(event1, event2)
        print(f"check_event_overlap({event1}, {event2}) -> {result}")
        print(f"  {describe_overlap(event1, event2)}")
    print(schedule_report([(540, 600), (570, 585), (630, 690), (680, 700)]))


if __name__ == "__main__":
    main()

