def mean_absolute_deviation(numbers):
    """Return the mean absolute deviation of a list of numbers (0.0 if empty)."""
    values = validate(numbers)
    if not values:
        return 0.0
    mean = sum(values) / len(values)
    return sum(abs(value - mean) for value in values) / len(values)


def validate(numbers):
    """Coerce an iterable of numeric values into a list of floats."""
    if isinstance(numbers, (str, bytes)):
        raise TypeError(f"expected a sequence of numbers, got {type(numbers).__name__}")
    values = []
    for position, item in enumerate(numbers):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"item {position} is not a number: {item!r}")
        values.append(float(item))
    return values


def parse_series(text):
    """Read a whitespace- or comma-separated series of numbers from text."""
    tokens = text.replace(",", " ").split()
    values = []
    for token in tokens:
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError(f"cannot read {token!r} as a number") from None
    return values


def describe(numbers):
    """Build a one-line summary of a series and its mean absolute deviation."""
    values = validate(numbers)
    if not values:
        return "empty series: mean = n/a, MAD = 0.0"
    mean = sum(values) / len(values)
    mad = mean_absolute_deviation(values)
    body = ", ".join(f"{value:g}" for value in values)
    return f"[{body}] -> n = {len(values)}, mean = {mean:.4f}, MAD = {mad:.4f}"


def report(series_list):
    """Return a multi-line report for several series, widest deviation last."""
    lines = []
    for index, series in enumerate(series_list, start=1):
        lines.append(f"{index:>2}. {describe(series)}")
    ranked = sorted(series_list, key=mean_absolute_deviation, reverse=True)
    top = ranked[0] if ranked else []
    if top:
        lines.append(f"most dispersed series has MAD {mean_absolute_deviation(top):.4f}")
    return "\n".join(lines)


def main():
    series_list = [
        [1, 2, 3, 4],
        [10, 20, 30],
        parse_series("2.5, 2.5, 2.5"),
        parse_series("-4 0 4 8"),
        [],
    ]
    print(report(series_list))
    combined = [value for series in series_list for value in series]
    print(f"pooled MAD over {len(combined)} values: {mean_absolute_deviation(combined):.4f}")
    try:
        mean_absolute_deviation([1, 2, "three"])
    except TypeError as error:
        print(f"rejected bad input: {error}")


if __name__ == "__main__":
    main()

