class ToDoList:
    def __init__(self):
        self.tasks = {}

    def add_task(self, task_name):
        if task_name in self.tasks:
            print(f"Task '{task_name}' already exists.")
        else:
            self.tasks[task_name] = False
            print(f"Added task: '{task_name}'.")

    def mark_completed(self, task_name):
        if task_name not in self.tasks:
            print(f"Task '{task_name}' not found.")
        elif self.tasks[task_name]:
            print(f"Task '{task_name}' is already completed.")
        else:
            self.tasks[task_name] = True
            print(f"Marked task '{task_name}' as completed.")

    def get_pending_tasks(self):
        pending = [task for task, completed in self.tasks.items() if not completed]
        if not pending:
            print(f"No pending tasks found. All {len(self.tasks)} tasks are completed!")
        else:
            print(f"Found {len(pending)} pending tasks.")
        return pending

