def _validate(value, name):
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a str, got {type(value).__name__}")
    return value


def _build_matrix(s1, s2):
    rows, cols = len(s1) + 1, len(s2) + 1
    matrix = [[0] * cols for _ in range(rows)]
    for i in range(1, rows):
        matrix[i][0] = i
    for j in range(1, cols):
        matrix[0][j] = j
    for i in range(1, rows):
        for j in range(1, cols):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            matrix[i][j] = min(
                matrix[i - 1][j] + 1,
                matrix[i][j - 1] + 1,
                matrix[i - 1][j - 1] + cost,
            )
    return matrix


def levenshtein_distance(s1, s2):
    _validate(s1, "s1")
    _validate(s2, "s2")
    matrix = _build_matrix(s1, s2)
    return matrix[len(s1)][len(s2)]


def edit_operations(s1, s2):
    _validate(s1, "s1")
    _validate(s2, "s2")
    matrix = _build_matrix(s1, s2)
    i, j = len(s1), len(s2)
    steps = []
    while i > 0 or j > 0:
        if i > 0 and j > 0 and s1[i - 1] == s2[j - 1]:
            i, j = i - 1, j - 1
        elif i > 0 and j > 0 and matrix[i][j] == matrix[i - 1][j - 1] + 1:
            steps.append(f"substitute {s1[i - 1]!r} at position {i - 1} with {s2[j - 1]!r}")
            i, j = i - 1, j - 1
        elif i > 0 and matrix[i][j] == matrix[i - 1][j] + 1:
            steps.append(f"delete {s1[i - 1]!r} at position {i - 1}")
            i -= 1
        else:
            steps.append(f"insert {s2[j - 1]!r} before position {i}")
            j -= 1
    steps.reverse()
    return steps


def similarity_ratio(s1, s2):
    longest = max(len(s1), len(s2))
    if longest == 0:
        return 1.0
    return 1.0 - levenshtein_distance(s1, s2) / longest


def format_report(s1, s2):
    distance = levenshtein_distance(s1, s2)
    ratio = similarity_ratio(s1, s2)
    lines = [f"{s1!r} -> {s2!r}: distance {distance}, similarity {ratio:.2%}"]
    for number, step in enumerate(edit_operations(s1, s2), start=1):
        lines.append(f"  {number}. {step}")
    return "\n".join(lines)


def main():
    pairs = [("kitten", "sitting"), ("flaw", "lawn"), ("", "abc"), ("same", "same")]
    for s1, s2 in pairs:
        print(format_report(s1, s2))
    total = sum(levenshtein_distance(a, b) for a, b in pairs)
    print(f"total distance across {len(pairs)} pairs: {total}")


if __name__ == "__main__":
    main()

