DIGITS = "0123456789ABCDEF"
MIN_BASE = 2
MAX_BASE = 16


def validate_base(base):
    if not isinstance(base, int) or isinstance(base, bool):
        raise TypeError(f"base must be an int, got {type(base).__name__}")
    if base < MIN_BASE or base > MAX_BASE:
        raise ValueError(f"base must be between {MIN_BASE} and {MAX_BASE}, got {base}")


def convert_base(number, base):
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    validate_base(base)
    if number == 0:
        return "0"
    sign = "-" if number < 0 else ""
    value = abs(number)
    digits = []
    while value:
        value, remainder = divmod(value, base)
        digits.append(DIGITS[remainder])
    return f"{sign}{''.join(reversed(digits))}"


def parse_base(text, base):
    validate_base(base)
    body = text.strip().upper()
    negative = body.startswith("-")
    if negative:
        body = body[1:]
    if not body:
        raise ValueError(f"no digits to parse in {text!r}")
    total = 0
    for char in body:
        position = DIGITS.find(char)
        if position < 0 or position >= base:
            raise ValueError(f"invalid digit {char!r} for base {base}")
        total = total * base + position
    return -total if negative else total


def rebase(text, from_base, to_base):
    return convert_base(parse_base(text, from_base), to_base)


def describe(number, base):
    return f"{number:>8} -> base {base:>2}: {convert_base(number, base)}"


def conversion_table(number, bases=range(MIN_BASE, MAX_BASE + 1)):
    return [describe(number, base) for base in bases]


def main():
    for sample in (10, 255, 0, -42, 4095):
        header = f"Conversions for {sample}"
        print(header)
        print("-" * len(header))
        for line in conversion_table(sample, (2, 8, 10, 16)):
            print(line)
        print()

    literals = [("1010", 2, 10), ("FF", 16, 10), ("777", 8, 16), ("-2A", 16, 2)]
    for text, source, target in literals:
        print(f"{text} (base {source}) = {rebase(text, source, target)} (base {target})")


if __name__ == "__main__":
    main()

