def normalize(s):
    """Return the lowercase alphanumeric-only form of s."""
    if not isinstance(s, str):
        raise TypeError(f"expected a string, got {type(s).__name__}")
    return "".join(ch.lower() for ch in s if ch.isalnum())


def is_palindrome_string(s):
    """Return True if s reads the same forwards and backwards."""
    cleaned = normalize(s)
    return cleaned == cleaned[::-1]


def first_mismatch(s):
    """Return the (left, right) index pair in the cleaned text that breaks symmetry."""
    cleaned = normalize(s)
    left, right = 0, len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return left, right
        left += 1
        right -= 1
    return None


def describe(s):
    """Build a one-line verdict for the string s."""
    cleaned = normalize(s)
    if not cleaned:
        return f"{s!r}: no alphanumeric characters, treated as a palindrome"
    verdict = "palindrome" if is_palindrome_string(s) else "not a palindrome"
    summary = f"{s!r} -> {cleaned!r} is a {verdict}"
    mismatch = first_mismatch(s)
    if mismatch is None:
        return summary
    left, right = mismatch
    detail = f"{cleaned[left]!r} at {left} vs {cleaned[right]!r} at {right}"
    return f"{summary} ({detail})"


def longest_palindromic_prefix(s):
    """Return the longest prefix of the cleaned text that is itself a palindrome."""
    cleaned = normalize(s)
    for end in range(len(cleaned), 0, -1):
        chunk = cleaned[:end]
        if chunk == chunk[::-1]:
            return chunk
    return ""


def report(strings):
    """Print a verdict per string and return how many were palindromes."""
    hits = 0
    for item in strings:
        print(describe(item))
        if is_palindrome_string(item):
            hits += 1
        else:
            prefix = longest_palindromic_prefix(item)
            print(f"    longest palindromic prefix: {prefix!r} ({len(prefix)} chars)")
    return hits


def main():
    samples = [
        "Racecar",
        "A man, a plan, a canal: Panama",
        "Was it a car or a cat I saw?",
        "hello world",
        "12321",
        "!!!",
        "Able was I, ere I saw Elba.",
    ]
    hits = report(samples)
    rate = 100.0 * hits / len(samples)
    print(f"{hits} of {len(samples)} samples are palindromes ({rate:.1f}%)")


if __name__ == "__main__":
    main()

