def convert_temperature(value, unit_from, unit_to):
    if unit_from == unit_to:
        print(f"No conversion needed: {value:.2f} {unit_from}")
        return value

    if unit_from == 'C':
        kelvin = value + 273.15
        fahrenheit = (value * 9/5) + 32
        print(f"Converting {value:.2f}°C...")
    elif unit_from == 'F':
        kelvin = (value - 32) * 5/9 + 273.15
        fahrenheit = value
        print(f"Converting {value:.2f}°F...")
    elif unit_from == 'K':
        kelvin = value
        fahrenheit = (value - 273.15) * 9/5 + 32
        print(f"Converting {value:.2f}K...")

    if unit_to == 'C':
        result = kelvin - 273.15
        print(f"Result: {result:.2f}°C from {unit_from}")
    elif unit_to == 'F':
        result = fahrenheit
        print(f"Result: {result:.2f}°F from {unit_from}")
    elif unit_to == 'K':
        result = kelvin
        print(f"Result: {result:.2f}K from {unit_from}")

    return result

