def analyze_password(password):
    """Return a dict mapping criterion names to whether the password meets them."""
    return {
        "length >= 8": len(password) >= 8,
        "uppercase letter": any(c.isupper() for c in password),
        "lowercase letter": any(c.islower() for c in password),
        "digit": any(c.isdigit() for c in password),
    }


def check_password_strength(password):
    """Classify a password as 'Strong', 'Medium' or 'Weak'."""
    if not isinstance(password, str):
        raise TypeError(f"password must be a string, got {type(password).__name__}")
    criteria = analyze_password(password)
    met = sum(criteria.values())
    if met == len(criteria):
        return "Strong"
    if len(password) >= 6 and met >= 2:
        return "Medium"
    return "Weak"


def missing_criteria(password):
    """List the criterion names that the password fails."""
    return [name for name, ok in analyze_password(password).items() if not ok]


def improvement_advice(password):
    """Human readable hint describing how to improve the password."""
    missing = missing_criteria(password)
    if not missing:
        return "no changes needed"
    if len(missing) == 1:
        return f"add {missing[0]}"
    listed = ", ".join(missing[:-1])
    return f"add {listed} and {missing[-1]}"


def mask(password):
    """Show only the first character of a password, hiding the rest."""
    if not password:
        return "(empty)"
    hidden = "*" * (len(password) - 1)
    return f"{password[0]}{hidden}"


def describe(password):
    """One line report about a single password."""
    strength = check_password_strength(password)
    met = sum(analyze_password(password).values())
    header = f"{mask(password):<12} {strength:<6} ({met}/4 criteria)"
    return f"{header} -> {improvement_advice(password)}"


def summarize(passwords):
    """Count how many passwords fall into each strength bucket."""
    tally = {"Strong": 0, "Medium": 0, "Weak": 0}
    for password in passwords:
        tally[check_password_strength(password)] += 1
    return tally


def main():
    samples = ["P@ssw0rd", "password", "abc", "Sunshine", "n0ttoolong", "A1b"]
    print(f"Checking {len(samples)} passwords")
    for password in samples:
        print(describe(password))
    tally = summarize(samples)
    parts = [f"{name}={count}" for name, count in tally.items()]
    print("Summary: " + ", ".join(parts))
    weakest = min(samples, key=lambda p: sum(analyze_password(p).values()))
    print(f"Weakest entry: {mask(weakest)} ({improvement_advice(weakest)})")


if __name__ == "__main__":
    main()

