def _validate(values, name):
    """Check that *values* is a sorted sequence of numbers."""
    if not isinstance(values, (list, tuple)):
        raise TypeError(f"{name} must be a list or tuple, got {type(values).__name__}")
    for index, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"{name}[{index}] is not a number: {item!r}")
    for index in range(1, len(values)):
        if values[index] < values[index - 1]:
            previous = values[index - 1]
            current = values[index]
            raise ValueError(f"{name} is not sorted: {previous} > {current} at index {index}")
    return list(values)


def merge_sorted_lists(list1, list2):
    """Merge two sorted lists of numbers into a single new sorted list."""
    left = _validate(list1, "list1")
    right = _validate(list2, "list2")
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged


def merge_all(lists):
    """Merge any number of sorted lists by folding merge_sorted_lists."""
    result = []
    for position, chunk in enumerate(lists):
        try:
            result = merge_sorted_lists(result, chunk)
        except (TypeError, ValueError) as error:
            raise ValueError(f"input #{position} is invalid: {error}") from error
    return result


def describe_merge(list1, list2):
    """Return a one-line human readable description of a merge."""
    merged = merge_sorted_lists(list1, list2)
    sizes = f"{len(list1)}+{len(list2)}"
    return f"{list1} + {list2} -> {merged} ({sizes} items)"


def main():
    pairs = [
        ([1, 3, 5], [2, 4, 6]),
        ([10], []),
        ([], []),
        ([1.5, 2.5], [0.5, 3.5, 3.5]),
        ([5, 4], [1, 2]),
    ]
    for list1, list2 in pairs:
        try:
            print(describe_merge(list1, list2))
        except (TypeError, ValueError) as error:
            print(f"skipped {list1} + {list2}: {error}")

    batch = [[1, 9], [2, 3], [0], [4, 5, 5]]
    combined = merge_all(batch)
    print(f"merged {len(batch)} lists into {combined}")
    total = sum(combined)
    print(f"sum of merged values: {total}, median-ish middle: {combined[len(combined) // 2]}")


if __name__ == "__main__":
    main()

