import os
import re
import tempfile

WORD_PATTERN = re.compile(r"[A-Za-z0-9]+")


def read_file_text(filepath):
    """Return the file's contents, or None when it cannot be read."""
    try:
        with open(filepath, "r", encoding="utf-8") as handle:
            return handle.read()
    except FileNotFoundError:
        print(f"warning: no such file: {filepath}")
        return None
    except OSError as exc:
        print(f"warning: could not read {filepath}: {exc}")
        return None


def extract_words(text):
    """Split raw text into alphanumeric words."""
    return WORD_PATTERN.findall(text)


def find_longest_word_in_file(filepath):
    text = read_file_text(filepath)
    if text is None:
        return ""
    words = extract_words(text)
    if not words:
        return ""
    longest = words[0]
    for word in words[1:]:
        if len(word) > len(longest):
            longest = word
    return longest


def describe_result(filepath, word):
    """Build a one-line human readable summary for a single file."""
    name = os.path.basename(filepath)
    if not word:
        return f"{name}: no words found"
    return f"{name}: longest word is '{word}' ({len(word)} characters)"


def write_sample_files(directory, samples):
    """Write the simulated files and return their paths in order."""
    paths = []
    for index, content in enumerate(samples, start=1):
        path = os.path.join(directory, f"sample_{index}.txt")
